// ── Claude proxy helper ────────────────────────────────────────────────
// Calls flow through a Supabase Edge Function (supabase/functions/claude-proxy)
// so the Anthropic key stays server-side and never reaches the browser.
async function callClaude(body) {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session) throw new Error("NOT_SIGNED_IN");
  const res = await fetch(`${import.meta.env.VITE_SUPABASE_URL}/functions/v1/claude-proxy`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${session.access_token}`,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err?.error?.message || err?.error || `HTTP ${res.status}`);
  }
  return res.json();
}

