function renderDialogLine(text, vocabIdx, color, onWordClick) {
  if (!vocabIdx || !text) return text;
  const parts = text.split(vocabIdx.regex);
  return parts.map((part, i) => {
    if (i % 2 === 1) {
      const entry = vocabIdx.lookup[part.toLowerCase()];
      if (entry) {
        return (
          <span key={i}
            onClick={(e) => { e.stopPropagation(); onWordClick(entry, part, e); }}
            style={{ borderBottom: '1.5px dotted #C2410C', color: '#C2410C', cursor: 'pointer', fontWeight: 700 }}>
            {part}
          </span>
        );
      }
    }
    return <span key={i}>{part}</span>;
  });
}


// ── دەنگ / German text-to-speech (browser Web Speech API) ─────────
let _deVoice = null;
// ناوی دەنگە نێرینەکانی ئەڵمانی لە سیستەمە جیاوازەکاندا
const MALE_DE_NAMES = ["stefan", "conrad", "markus", "hans", "klaus", "daniel", "yannick", "bernd", "viktor", "männlich", "male"];
function pickGermanVoice() {
  try {
    const vs = window.speechSynthesis.getVoices();
    const de = vs.filter((v) => v.lang && v.lang.toLowerCase().startsWith("de"));
    // ١) دەنگی نێرینەی ئەڵمانی بەپێی ناو
    _deVoice =
      de.find((v) => MALE_DE_NAMES.some((n) => v.name.toLowerCase().includes(n))) ||
      // ٢) دەنگی de-DE
      de.find((v) => v.lang === "de-DE") ||
      // ٣) هەر دەنگێکی ئەڵمانی
      de[0] || null;
  } catch { /* Browser capability may be unavailable. */ }
}
if (typeof window !== "undefined" && window.speechSynthesis) {
  pickGermanVoice();
  try { window.speechSynthesis.onvoiceschanged = pickGermanVoice; } catch { /* Voice events are optional. */ }
}
function speakDe(text) {
  try {
    const synth = window.speechSynthesis;
    if (!synth || !text) return;
    synth.cancel();
    const u = new SpeechSynthesisUtterance(String(text));
    u.lang = "de-DE";
    if (_deVoice) u.voice = _deVoice;
    u.rate = 0.9;
    u.pitch = 0.8;
    u.volume = 1;
    synth.speak(u);
  } catch { /* Browser capability may be unavailable. */ }
}

function Speak({ text, size = 15 }) {
  return (
    <button onClick={(e) => { e.stopPropagation(); speakDe(text); }}
      style={{ border: "none", background: "transparent", cursor: "pointer", color: C.gold, padding: "0 4px", lineHeight: 1, verticalAlign: "middle", flexShrink: 0, display:"inline-flex", alignItems:"center" }}>
      <Volume2 size={size} />
    </button>
  );
}

function StoryAudioControls({ text, lang = 'tr', containerId = 'story-audio-text' }) {
  const chunks = useMemo(() => String(text || '').match(/[^.!?]+[.!?]+|[^.!?]+$/g)?.map(s => s.trim()).filter(Boolean) || [], [text]);
  const durations = useMemo(() => chunks.map(s => Math.max(1.5, s.length / 13)), [chunks]);
  const starts = useMemo(() => durations.map((_, i) => durations.slice(0, i).reduce((a, b) => a + b, 0)), [durations]);
  const wordOffsets = useMemo(() => chunks.map((_, i) => chunks.slice(0, i).reduce((n, part) => n + (part.match(/\S+/g)?.length || 0), 0)), [chunks]);
  const [playing, setPlaying] = useState(false);
  const [paused, setPaused] = useState(false);
  const indexRef = useRef(0);
  const activeRef = useRef(false);
  const activeWordRef = useRef(null);

  const clearHighlight = useCallback(() => {
    activeWordRef.current?.classList.remove('story-audio-active');
    activeWordRef.current = null;
  }, []);
  const highlightWord = useCallback((wordIndex) => {
    const root = document.getElementById(containerId);
    const next = root?.querySelector(`[data-audio-word-index="${wordIndex}"]`);
    if (!next || next === activeWordRef.current) return;
    clearHighlight();
    next.classList.add('story-audio-active');
    activeWordRef.current = next;
    next.scrollIntoView?.({ block:'nearest', behavior:'smooth' });
  }, [containerId, clearHighlight]);

  const speakFrom = useCallback((index) => {
    const synth = window.speechSynthesis;
    if (!synth || !chunks.length) return;
    synth.cancel(); clearHighlight();
    indexRef.current = Math.max(0, Math.min(index, chunks.length - 1));
    activeRef.current = true;
    setPlaying(true); setPaused(false);
    const speakNext = () => {
      if (!activeRef.current || indexRef.current >= chunks.length) {
        activeRef.current = false; setPlaying(false); setPaused(false); clearHighlight(); return;
      }
      const chunkIndex = indexRef.current;
      const chunk = chunks[chunkIndex];
      const u = new SpeechSynthesisUtterance(chunk);
      u.lang = 'de-DE'; if (_deVoice) u.voice = _deVoice;
      u.rate = 0.9; u.pitch = 0.8; u.volume = 1;
      u.onstart = () => highlightWord(wordOffsets[chunkIndex]);
      u.onboundary = (event) => {
        if (event.name && event.name !== 'word') return;
        const before = chunk.slice(0, event.charIndex || 0);
        const localWord = before.match(/\S+/g)?.length || 0;
        highlightWord(wordOffsets[chunkIndex] + localWord);
      };
      u.onend = () => { if (activeRef.current) { indexRef.current += 1; speakNext(); } };
      u.onerror = () => { activeRef.current = false; setPlaying(false); setPaused(false); clearHighlight(); };
      synth.speak(u);
    };
    speakNext();
  }, [chunks, wordOffsets, highlightWord, clearHighlight]);

  const togglePause = () => {
    const synth = window.speechSynthesis;
    if (!playing) { speakFrom(indexRef.current); return; }
    if (paused) { synth.resume(); setPaused(false); }
    else { synth.pause(); setPaused(true); }
  };
  const seek = (delta) => {
    const current = starts[indexRef.current] || 0;
    const target = Math.max(0, Math.min(current + delta, durations.reduce((a, b) => a + b, 0)));
    let next = starts.findIndex((start, i) => target < start + durations[i]);
    if (next < 0) next = chunks.length - 1;
    speakFrom(next);
  };
  useEffect(() => () => { activeRef.current = false; clearHighlight(); window.speechSynthesis?.cancel(); }, [clearHighlight]);

  const labels = {
    tr:{ back:'5 saniye geri', pause:'Duraklat', resume:'Devam et', forward:'5 saniye ileri' },
    en:{ back:'Back 5 seconds', pause:'Pause', resume:'Resume', forward:'Forward 5 seconds' },
    de:{ back:'5 Sekunden zurück', pause:'Pause', resume:'Fortsetzen', forward:'5 Sekunden vor' },
    fa:{ back:'۵ ثانیه عقب', pause:'مکث', resume:'ادامه', forward:'۵ ثانیه جلو' },
  "es":{"back":"Atrás 5 segundos","pause":"Pausa","resume":"Reanudar","forward":"Adelante 5 segundos"},"fr":{"back":"En arrière 5 secondes","pause":"Pause","resume":"Résumé","forward":"En avant 5 secondes"}};
  const l = labels[lang] || labels.en;
  const btn = { border:'1px solid rgba(180,130,60,.35)', background:'rgba(180,130,60,.09)', color:'#8B6030', borderRadius:9, height:34, minWidth:42, padding:'0 9px', cursor:'pointer', fontWeight:800, fontSize:12 };
  return (
    <div style={{ display:'flex', alignItems:'center', gap:7 }}>
      <button onClick={() => seek(5)} title={l.forward} aria-label={l.forward} style={{...btn,borderRadius:'50%',width:38,minWidth:38,padding:0,fontSize:17}}>⏩</button>
      <button onClick={togglePause} title={playing ? (paused ? l.resume : l.pause) : l.resume} aria-label={playing ? (paused ? l.resume : l.pause) : l.resume} style={{...btn,minWidth:42,fontSize:16}}>{playing && !paused ? '⏸' : '▶'}</button>
      <button onClick={() => seek(-5)} title={l.back} aria-label={l.back} style={{...btn,borderRadius:'50%',width:38,minWidth:38,padding:0,fontSize:17}}>⏪</button>
    </div>
  );
}
function LevelPills({ value, onChange }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 8, marginBottom: 20 }}>
      {LEVELS.map((lv) => {
        const active = value === lv.id;
        return (
          <button key={lv.id} onClick={() => onChange(lv.id)}
            style={{
              border: active ? "none" : `1.5px solid ${lv.color}33`,
              background: active ? lv.color : "#fff",
              color: active ? "#fff" : lv.color,
              padding: "11px 6px 10px",
              borderRadius: 14,
              fontWeight: 700,
              fontSize: 13,
              cursor: "pointer",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 3,
              boxShadow: active
                ? `0 3px 0 rgba(0,0,0,.12), 0 8px 20px ${lv.color}44`
                : "0 2px 0 rgba(0,0,0,.06), 0 4px 12px rgba(0,0,0,.05)",
              transition: "all .25s cubic-bezier(.34,1.56,.64,1)",
              transform: active ? "translateY(-1px)" : "none",
            }}>
            <span style={{ fontSize: 16, fontWeight: 800, lineHeight: 1 }}>{lv.id}</span>
            <span style={{ fontSize: 11, fontWeight: 600, opacity: active ? .9 : .75, letterSpacing: ".01em" }}>{lv.label}</span>
          </button>
        );
      })}
    </div>
  );
}

