// ── Schreiben A: Formular ausfüllen ──────────────────────────────────
function SchreibenAItem({ ex, idx, lang = "ku" }) {
  const [shown, setShown] = useState({});
  function toggleField(i) { setShown(s => ({ ...s, [i]: !s[i] })); }
  function showAll() { const a = {}; ex.fields.forEach((_, i) => a[i] = true); setShown(a); }
  function reset() { setShown({}); }
  const shownCount = Object.values(shown).filter(Boolean).length;
  const allShown = shownCount === ex.fields.length;
  return (
    <div style={{ marginBottom: 16, background: "#F9F9FB", borderRadius: 14, border: "1.5px solid #E4E4E8", padding: 14 }}>
      <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, marginBottom: 8 }}>
        {lang==="tr" ? `Alıştırma ${idx+1} · ` : lang==="uk" ? `Вправа ${idx+1} · ` : lang==="es" ? `Ejercicio ${idx+1} · ` : lang === "fr" ? `Pratique ${idx+1} ·` : `تاقیکردنەوە ${idx+1} · `}<span dir="ltr">{ex.title}</span> · {lang==="tr" ? (ex.titleTr||ex.titleKu) : lang==="en" ? (ex.titleEn||ex.titleKu) : lang==="ar" ? (ex.titleAr||ex.titleKu) : lang==="uk" ? (ex.titleUk||ex.titleEn||ex.titleKu) : lang==="fa" ? (ex.titleFa||ex.titleEn||ex.titleKu) : lang==="es" ? (ex.titleEs||ex.titleEn||ex.titleKu) : ex.titleKu}
      </div>
      <div style={{ background: "#EEF0FF", borderRadius: 10, padding: "10px 12px", marginBottom: 6, fontSize: 13, lineHeight: 1.75 }} dir="ltr">
        {ex.personInfo}
      </div>
      <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 12 }}>{lang==="tr" ? (ex.personInfoTr||ex.personInfoKu) : lang==="en" ? (ex.personInfoEn||ex.personInfoKu) : lang==="ar" ? (ex.personInfoAr||ex.personInfoKu) : lang === "es" ? (ex.personInfoEs||ex.personInfoKu) : lang==="uk" ? (ex.personInfoUk||ex.personInfoEn||ex.personInfoKu) : lang==="fa" ? (ex.personInfoFa||ex.personInfoEn||ex.personInfoKu) : ex.personInfoKu}</div>
      <div style={{ display: "grid", gap: 5, marginBottom: 12 }}>
        {ex.fields.map((f, i) => (
          <div key={i} onClick={() => toggleField(i)}
            style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, alignItems: "center",
              background: "#fff", borderRadius: 8, padding: "8px 12px", cursor: "pointer",
              border: `1.5px solid ${shown[i] ? "#86EFAC" : "#E4E4E8"}`, transition: "all .15s" }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.muted }} dir="ltr">{f.label}</div>
            <div style={{ fontSize: 13, fontWeight: shown[i] ? 700 : 400, color: shown[i] ? "#16A34A" : "#C0C0C8" }} dir="ltr">
              {shown[i] ? f.answer : "· · · · ·"}
            </div>
          </div>
        ))}
      </div>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <button onClick={allShown ? reset : showAll}
          style={{ flex: 1, padding: "8px", borderRadius: 9, border: "none",
            background: allShown ? "#F0F0F5" : "#5B5BD6",
            color: allShown ? "#71717A" : "#fff", fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
          {allShown ? tApp(lang,"ubung_reset") : `✓ ${DONE_WORD[lang] || "تەواو"}`}
        </button>
        <span style={{ fontSize: 12, color: C.muted, flexShrink: 0 }}>{shownCount} / {ex.fields.length}</span>
      </div>
    </div>
  );
}

function SchreibenASection({ lang = "ku", open = false, onToggle }) {
  const secRef = useRef(null);
  const _openDidMount = useRef(false);
  useEffect(() => { if (!_openDidMount.current) { _openDidMount.current = true; return; } if (open && secRef.current) { const rect = secRef.current.getBoundingClientRect(); if (rect.height === 0) return; const y = rect.top + window.scrollY - 70; window.scrollTo({ top: y, behavior: "smooth" }); } }, [open]);
  return (
    <div ref={secRef} style={{ background: "#fff", borderRadius: 18, border: "1.5px solid #E4E4E8", overflow: "hidden" }}>
      <div onClick={onToggle}
        style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "15px 18px", cursor: "pointer", userSelect: "none" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div style={{ width: 38, height: 38, borderRadius: 11, background: "#EEF0FF", display: "grid", placeItems: "center" }}>
            <span style={{ fontSize: 18 }}>📝</span>
          </div>
          <div>
            <div style={{ fontWeight: 700, fontSize: 15 }}>{lang==="tr" ? "Schreiben A — Form Doldur" : lang==="en" ? "Schreiben A — Fill the Form" : lang==="ar" ? "Schreiben A — املأ النموذج" : lang === "es" ? "Schreiben A — Rellena el formulario" : lang === "uk" ? "Schreiben A — Заповніть форму" : lang === "fa" ? "Schreiben A — فرم را پر کنید" : lang === "fr" ? "Schreiben A — Remplissez le formulaire" : "Schreiben A — فۆرم پڕبکەرەوە"}</div>
            <div style={{ fontSize: 12.5, color: C.muted, marginTop: 2 }}>{lang==="tr" ? "3 alıştırma · Bilgileri forma gir" : lang==="en" ? "3 exercises · Enter the information into the form" : lang==="ar" ? "3 تمارين · أدخل المعلومات في النموذج" : lang === "es" ? "3 ejercicios · Introduce la información en el formulario" : lang === "uk" ? "3 вправи · Введіть інформацію у форму" : lang === "fa" ? "۳ تمرین · اطلاعات را در فرم وارد کنید" : lang === "fr" ? "3 exercices · Entrez l'information dans le formulaire" : "3 تاقیکردنەوە · داتا بخرە فۆرمەکەدا"}</div>
          </div>
        </div>
        <span style={{ fontSize: 20, color: C.muted, transform: open ? "rotate(90deg)" : "rotate(0deg)", transition: "transform .2s" }}>›</span>
      </div>
      <div style={{ padding: "4px 16px 16px", borderTop: "1px solid #E4E4E8", display: open ? "" : "none" }}>
        {A1_SCHREIBEN_A.map((ex, idx) => <SchreibenAItem key={ex.id} ex={ex} idx={idx} lang={lang} />)}
      </div>
    </div>
  );
}

// ── Schreiben B: Kurze Mitteilung ────────────────────────────────────
function SchreibenBItem({ ex, idx, lang = "ku" }) {
  const [showModel, setShowModel] = useState(false);
  return (
    <div style={{ marginBottom: 16, background: "#F9F9FB", borderRadius: 14, border: "1.5px solid #E4E4E8", padding: 14 }}>
      <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, marginBottom: 8 }}>{lang==="tr" ? `Alıştırma ${idx+1}` : lang==="en" ? `Exercise ${idx+1}` : lang==="ar" ? `تمرين ${idx+1}` : lang === "fa" ? `تمرین ${idx+1}` : lang === "es" ? `Ejercicio ${idx+1}` : lang==="uk" ? `Вправа ${idx+1}` : lang === "fr" ? `Exercice ${idx+1}` : `تاقیکردنەوە ${idx+1}`}</div>
      <div style={{ background: "#FFF7E6", borderRadius: 10, padding: "10px 12px", marginBottom: 6, fontSize: 13.5, lineHeight: 1.75 }} dir="ltr">
        {ex.task}
      </div>
      <div style={{ fontSize: 11.5, color: C.muted, marginBottom: 12 }}>{ex["task"+lang.charAt(0).toUpperCase()+lang.slice(1)] || ex.taskKu}</div>
      <div style={{ marginBottom: 10 }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: C.muted, marginBottom: 5 }}>{lang==="tr" ? "Şu noktalara değinmelisiniz:" : lang==="en" ? "You should cover these points:" : lang==="ar" ? "يجب أن تتناول هذه النقاط:" : lang === "es" ? "Debes cubrir estos puntos:" : lang === "uk" ? "Ви маєте висвітлити ці пункти:" : lang === "fa" ? "باید به این نکات بپردازید:" : lang === "fr" ? "Vous devriez couvrir ces points:" : "دەبێت لەم خاڵانە بنووسیت:"}</div>
        {ex.bullets.map((b, i) => (
          <div key={i} style={{ display: "flex", gap: 8, alignItems: "baseline", marginBottom: 4 }}>
            <span style={{ color: "#F59E0B", fontWeight: 800, flexShrink: 0 }}>•</span>
            <span style={{ fontSize: 13 }} dir="ltr">{b.de}</span>
            <span style={{ fontSize: 11.5, color: C.muted }}>({tC(b, lang)})</span>
          </div>
        ))}
      </div>
      <div style={{ fontSize: 12, color: "#F59E0B", fontWeight: 600, marginBottom: 8 }}>
        {lang==="tr" ? "✏️ Yaklaşık 30 kelime · ca. 30 Wörter" : lang==="en" ? "✏️ About 30 words · ca. 30 Wörter" : lang==="ar" ? "✏️ حوالي 30 كلمة · ca. 30 Wörter" : lang === "es" ? "✏️ Unas 30 palabras · ca. 30 Wörter" : lang === "uk" ? "✏️ Близько 30 слів · ca. 30 Wörter" : lang === "fa" ? "✏️ حدود ۳۰ واژه · ca. 30 Wörter" : lang === "fr" ? "Environ 30 mots · ca. 30 Wörter" : "✏️ نزیکەی ٣٠ وشە · ca. 30 Wörter"}
      </div>
      <div style={{ fontSize: 12.5, color: C.muted, fontStyle: "italic", marginBottom: 12 }} dir="ltr">
        Beginnen Sie mit: „{ex.salutation}"
      </div>
      <button onClick={() => setShowModel(s => !s)}
        style={{ width: "100%", padding: "9px", borderRadius: 9,
          border: `1.5px solid #5B5BD6`,
          background: showModel ? "#5B5BD6" : "#fff",
          color: showModel ? "#fff" : "#5B5BD6",
          fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
        {showModel ? (lang==="tr" ? "▲ Kapat" : lang==="en" ? "▲ Close" : lang==="ar" ? "▲ إغلاق" : lang === "es" ? "▲ Cerrar" : lang === "uk" ? "▲ Закрити" : lang === "fa" ? "▲ بستن" : lang === "fr" ? "- Fermez" : "▲ داخستن") : (lang==="tr" ? "▼ Örnek cevap — Musterlösung" : lang==="en" ? "▼ Sample answer — Musterlösung" : lang==="ar" ? "▼ إجابة نموذجية — Musterlösung" : lang === "es" ? "▼ Respuesta modelo — Musterlösung" : lang === "uk" ? "▼ Зразок відповіді — Musterlösung" : lang === "fa" ? "▼ نمونه پاسخ — Musterlösung" : lang === "fr" ? "▼ Exemple de réponse — Musterlösung" : "▼ نموونەی وەڵام — Musterlösung")}
      </button>
      {showModel && (
        <div style={{ marginTop: 10, background: "#F0FDF4", borderRadius: 10, padding: "12px 14px", border: "1.5px solid #86EFAC" }}>
          <div style={{ fontSize: 11.5, fontWeight: 700, color: "#16A34A", marginBottom: 6 }}>✓ Musterlösung</div>
          <div style={{ fontSize: 13.5, lineHeight: 1.85, whiteSpace: "pre-line" }} dir="ltr">{ex.modelAnswer}</div>
          <div style={{ fontSize: 11.5, color: C.muted, marginTop: 8 }}>{lang==="tr" ? (ex.modelAnswerTr||ex.modelAnswerKu) : lang==="en" ? (ex.modelAnswerEn||ex.modelAnswerKu) : lang==="ar" ? (ex.modelAnswerAr||ex.modelAnswerKu) : lang === "es" ? (ex.modelAnswerEs||ex.modelAnswerKu) : lang==="uk" ? (ex.modelAnswerUk||ex.modelAnswerEn||ex.modelAnswerKu) : lang==="fa" ? (ex.modelAnswerFa||ex.modelAnswerEn||ex.modelAnswerKu) : ex.modelAnswerKu}</div>
        </div>
      )}
    </div>
  );
}

