// ── تێست / AI-generated test (١٠ پرسیار هەر گەڕێک) ─────────────────
function AITest({ subject, level, pct = 0, onBatch, hint, lang = "ku" }) {
  const N = 10;
  const [phase, setPhase] = useState("intro"); // intro | loading | active | result | error
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [lastDelta, setLastDelta] = useState(null);

  async function generate() {
    setPhase("loading"); setAnswers({});
    const prompt = lang === "tr"
      ? `Konu: ${subject}. Seviye: ${level}. ` +
        `Bu konuyu Almanca olarak test etmek için ${N} çoktan seçmeli soru oluştur. ` +
        `Sorular yalnızca bu konuyla ilgili olsun ve ${level} seviyesine uygun olsun. Her soru üç seçenek içersin. ` +
        (hint ? hint + " " : "") +
        `Yalnızca JSON döndür, başka metin yok: ` +
        `{"questions":[{"q":"Almanca soru","options":["A","B","C"],"correct":0,"why":"Doğru cevabın Türkçe açıklaması"}]}`
      : `بابەت: ${subject}. ئاست: ${level}. ` +
        `${N} پرسیاری هەڵبژاردنی فرە (multiple choice) دروست بکە بۆ تاقیکردنەوەی ئەم بابەتە بە ئەڵمانی. ` +
        `پرسیارەکان تەنها سەبارەت بەم بابەتە بن و بەپێی ئاستی ${level}. هەر پرسیارێک سێ هەڵبژاردەی هەبێت. ` +
        (hint ? hint + " " : "") +
        `تەنها JSON بگەڕێنەرەوە بەبێ هیچ دەقێکی تر، بەم فۆرماتە: ` +
        `{"questions":[{"q":"پرسیار بە ئەڵمانی","options":["A","B","C"],"correct":0,"why":"ڕوونکردنەوەی وەڵامی ڕاست بە سۆرانی"}]}`;
    try {
      const data = await callClaude({ model: "claude-sonnet-4-20250514", max_tokens: 2800, messages: [{ role: "user", content: prompt }] });
      let txt = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n").trim().replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(txt);
      const clean = (parsed.questions || [])
        .filter((q) => q && Array.isArray(q.options) && q.options.length >= 2)
        .map((q) => ({ q: String(q.q || ""), options: q.options.map(String), correct: Number(q.correct) || 0, why: q.why ? String(q.why) : "" }))
        .slice(0, N);
      if (!clean.length) throw new Error("no q");
      setQuestions(clean);
      setPhase("active");
    } catch (e) { setPhase(e.message?.includes("credit") ? "nocredit" : e.message === "NO_KEY" ? "nokey" : "error"); }
  }

  const correctCount = questions.reduce((n, q, i) => n + (answers[i] === q.correct ? 1 : 0), 0);

  function check() {
    const c = correctCount, w = questions.length - c;
    setLastDelta(c - w);
    onBatch && onBatch(c, w);
    setPhase("result");
  }

  // ── INTRO (+ chart + last result message) ──
  if (phase === "intro") {
    return (
      <div style={{ marginTop: 26, background: C.card, borderRadius: 22, padding: "24px 20px", border: `1px solid ${C.line}`, boxShadow: "0 4px 24px rgba(0,0,0,.06)" }}>
        {/* header */}
        <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:20 }}>
          <div style={{ width:40, height:40, borderRadius:12, background:"linear-gradient(135deg,#5B5BD6,#818cf8)", display:"grid", placeItems:"center", flexShrink:0, boxShadow:"0 4px 12px rgba(91,91,214,.3)" }}>
            <span style={{ fontSize:20 }}>🧠</span>
          </div>
          <div>
            <div style={{ fontWeight:800, fontSize:16, color:C.text }}>{tApp(lang,"ai_quiz_title")}</div>
            <div style={{ fontSize:12, color:C.muted, marginTop:1 }}>{lang === "tr" ? "Her seferinde 10 soru" : lang === "en" ? "10 questions each round" : lang === "ar" ? "10 أسئلة في كل جولة" : lang === "es" ? "10 preguntas por ronda" : lang === "uk" ? "10 питань за раунд" : lang === "fa" ? "۱۰ سؤال در هر دور" : lang === "fr" ? "10 questions par cycle" : "هەر گەڕێک ١٠ پرسیار"}</div>
          </div>
        </div>

        {/* donut centered */}
        <div style={{ display:"flex", justifyContent:"center", marginBottom:16 }}>
          <Donut pct={pct} />
        </div>

        {/* stats row */}
        <div style={{ display:"flex", justifyContent:"center", gap:20, marginBottom: lastDelta !== null ? 12 : 20 }}>
          {[
            { label: lang === "tr" ? "Doğru" : lang === "en" ? "Correct" : lang === "ar" ? "صحيح" : lang === "es" ? "Correcto" : lang === "uk" ? "Правильно" : lang === "fa" ? "درست" : lang === "fr" ? "Corrigé" : "وەڵامی ڕاست", val:"+١٪", color:"#10b981" },
            { label: lang === "tr" ? "Yanlış" : lang === "en" ? "Wrong" : lang === "ar" ? "خطأ" : lang === "es" ? "Incorrecto" : lang === "uk" ? "Неправильно" : lang === "fa" ? "غلط" : lang === "fr" ? "Faux" : "وەڵامی هەڵە", val:"−١٪", color:"#ef4444" },
            { label: lang === "tr" ? "Hedef" : lang === "en" ? "Target" : lang === "ar" ? "الهدف" : lang === "es" ? "Objetivo" : lang === "uk" ? "Ціль" : lang === "fa" ? "هدف" : lang === "fr" ? "Objectif" : "ئامانج",       val:"٩٥٪",  color:"#5B5BD6" },
          ].map(r => (
            <div key={r.label} style={{ textAlign:"center" }}>
              <div style={{ fontWeight:700, fontSize:15, color:r.color }}>{r.val}</div>
              <div style={{ fontSize:11, color:C.muted, marginTop:2 }}>{r.label}</div>
            </div>
          ))}
        </div>

        {lastDelta !== null && (
          <div style={{ background: lastDelta >= 0 ? "rgba(16,185,129,.1)" : "rgba(239,68,68,.1)", borderRadius:10, padding:"7px 12px", fontSize:13, marginBottom:16, color: lastDelta >= 0 ? "#065f46" : "#991b1b", fontWeight:600, textAlign:"center" }}>
            {lastDelta >= 0 ? `+${lastDelta}٪` : `${lastDelta}٪`} — {lang === "tr" ? "Son test" : lang === "en" ? "Last test" : lang === "ar" ? "آخر اختبار" : lang === "es" ? "Última prueba" : lang === "uk" ? "Останній тест" : lang === "fa" ? "آخرین آزمون" : lang === "fr" ? "Dernier essai" : "دوایین تاقیکردنەوە"}
          </div>
        )}

        {/* button */}
        <button onClick={generate} style={{ width:"100%", padding:"13px", borderRadius:14, border:"none", cursor:"pointer", fontFamily:"'Vazirmatn',sans-serif", fontWeight:700, fontSize:15, background:"linear-gradient(135deg,#5B5BD6,#818cf8)", color:"#fff", boxShadow:"0 4px 14px rgba(91,91,214,.35)" }}>
          {pct > 0 ? tApp(lang,"ai_continue10") : tApp(lang,"ai_start")}
        </button>
      </div>
    );
  }
  if (phase === "loading") return <div style={{ marginTop: 26, textAlign: "center", color: C.muted, fontSize: 15, padding: 24 }}>{tApp(lang,"ai_loading")}</div>;
  if (phase === "nokey") return (
    <div style={{ marginTop:26, textAlign:"center", padding:20, background:"#fef3c7", borderRadius:14 }}>
      <div style={{ fontSize:22, marginBottom:8 }}>🔑</div>
      <div style={{ color:"#92400e", fontWeight:700, fontSize:15, marginBottom:6 }}>{lang === "tr" ? "API anahtarın yok" : lang === "en" ? "You don't have an API key" : lang === "ar" ? "ليس لديك مفتاح API" : lang === "es" ? "No tienes una clave API" : lang === "uk" ? "У вас немає ключа API" : lang === "fa" ? "شما کلید API ندارید" : lang === "fr" ? "Vous n'avez pas de clé API" : "API کلیلت نییە"}</div>
      <div style={{ color:"#78350f", fontSize:13 }}>{lang === "tr" ? "Sayfanın üstündeki 🔑 butonuna tıklayarak anahtarını ekle." : lang === "en" ? "Tap the 🔑 button at the top of the page to add your key." : lang === "ar" ? "انقر زر 🔑 أعلى الصفحة لإضافة مفتاحك." : lang === "es" ? "Toca el botón 🔑 en la parte superior de la página para añadir tu clave." : lang === "uk" ? "Натисніть кнопку 🔑 угорі сторінки, щоб додати свій ключ." : lang === "fa" ? "روی دکمه 🔑 بالای صفحه بزنید تا کلید خود را اضافه کنید." : lang === "fr" ? "Appuyez sur le bouton -- en haut de la page pour ajouter votre clé." : "لە سەرەوەی پەڕەکە کلیک بکە لەسەر 🔑 و کلیلەکەت زیاد بکە."}</div>
    </div>
  );
  if (phase === "nocredit") return (
    <div style={{ marginTop:26, textAlign:"center", padding:20, background:"#fef3c7", borderRadius:14 }}>
      <div style={{ fontSize:22, marginBottom:8 }}>💳</div>
      <div style={{ color:"#92400e", fontWeight:700, fontSize:15, marginBottom:6 }}>{lang === "tr" ? "Anthropic krediniz bitti" : lang === "en" ? "Your Anthropic credit has run out" : lang === "ar" ? "نفد رصيد Anthropic الخاص بك" : lang === "es" ? "Tu crédito de Anthropic se ha agotado" : lang === "uk" ? "Ваш кредит Anthropic вичерпано" : lang === "fa" ? "اعتبار Anthropic شما تمام شده است" : lang === "fr" ? "Votre crédit anthropologique est épuisé" : "Anthropic کرێدیتت تەواو بووە"}</div>
      <div style={{ color:"#78350f", fontSize:13, lineHeight:1.7, marginBottom:12 }}>
        {lang === "tr" ? <><strong>console.anthropic.com/settings/billing</strong> adresine giderek kredi ekle, ardından tekrar dene.</> : lang === "en" ? <>Go to <strong>console.anthropic.com/settings/billing</strong> to add credit, then try again.</> : lang === "ar" ? <>اذهب إلى <strong>console.anthropic.com/settings/billing</strong> لإضافة رصيد، ثم أعد المحاولة.</> : lang === "fa" ? <>برای افزودن اعتبار به <strong>console.anthropic.com/settings/billing</strong> بروید، سپس دوباره تلاش کنید.</> : lang === "es" ? <>Ve a <strong>console.anthropic.com/settings/billing</strong> para añadir crédito y vuelve a intentarlo.</> : lang === "uk" ? <>Перейдіть на <strong>console.anthropic.com/settings/billing</strong>, щоб додати кредит, потім спробуйте знову.</> : <>بچۆ بۆ <strong>console.anthropic.com/settings/billing</strong> و کرێدیت زیاد بکە، پاشان دووبارە هەوڵبدەرەوە.</>}
      </div>
      <button onClick={generate} style={{ background:"#f59e0b", color:"#fff", border:"none", padding:"9px 18px", borderRadius:9, fontWeight:700 }}>{lang === "tr" ? "Tekrar dene" : lang === "en" ? "Try again" : lang === "ar" ? "أعد المحاولة" : lang === "es" ? "Intentar de nuevo" : lang === "uk" ? "Спробуйте ще раз" : lang === "fa" ? "دوباره تلاش کنید" : lang === "fr" ? "Essayez encore" : "دووبارە هەوڵبدە"}</button>
    </div>
  );
  if (phase === "error") return (
    <div style={{ marginTop:26, textAlign:"center", padding:20, background:"#fbeae6", borderRadius:14 }}>
      <div style={{ color:C.redDk, fontSize:15, marginBottom:10 }}>{lang === "tr" ? "Üzgünüz, soru oluşturma başarısız oldu." : lang === "en" ? "Sorry, question generation failed." : lang === "ar" ? "عذرًا، فشل إنشاء السؤال." : lang === "es" ? "Lo sentimos, no se pudo generar la pregunta." : lang === "uk" ? "Вибачте, не вдалося згенерувати питання." : lang === "fa" ? "متأسفیم، ساختن سؤال ممکن نشد." : lang === "fr" ? "Désolé, la génération des questions a échoué." : "ببورە، دروستکردنی پرسیار سەرکەوتوو نەبوو."}</div>
      <button onClick={generate} style={{ background:C.red, color:"#fff", border:"none", padding:"9px 18px", borderRadius:9, fontWeight:700 }}>{lang === "tr" ? "Tekrar dene" : lang === "en" ? "Try again" : lang === "ar" ? "أعد المحاولة" : lang === "es" ? "Intentar de nuevo" : lang === "uk" ? "Спробуйте ще раз" : lang === "fa" ? "دوباره تلاش کنید" : lang === "fr" ? "Essayez encore" : "دووبارە هەوڵبدە"}</button>
    </div>
  );

  const reviewed = phase === "result";
  return (
    <div style={{ marginTop: 26 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <div style={{ fontWeight: 700, fontSize: 18 }}>🧠 {tApp(lang,"ai_quiz_title")}</div>
        <span style={{ background: reviewed ? C.green : C.muted, color: "#fff", padding: "4px 13px", borderRadius: 14, fontWeight: 700, fontSize: 14 }} dir="ltr">{correctCount} / {questions.length}</span>
      </div>

      {reviewed && (
        <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 16, padding: 18, marginBottom: 16, display: "flex", alignItems: "center", gap: 18, flexWrap: "wrap", justifyContent: "center" }}>
          <Donut pct={pct} />
          <div style={{ textAlign: "center", minWidth: 150 }}>
            <div style={{ fontSize: 14, color: C.muted, marginBottom: 4 }}>{lang === "tr" ? "Bu test" : lang === "en" ? "This test" : lang === "ar" ? "هذا الاختبار" : lang === "es" ? "Esta prueba" : lang === "uk" ? "Цей тест" : lang === "fa" ? "این آزمون" : lang === "fr" ? "Cet essai" : "ئەم تاقیکردنەوەیە"}</div>
            <div style={{ fontSize: 26, fontWeight: 800, color: lastDelta >= 0 ? C.green : C.redDk }} dir="ltr">{lastDelta >= 0 ? "+" : ""}{lastDelta}%</div>
            <div style={{ fontSize: 13.5, color: C.muted, marginTop: 6 }}>{lang === "tr" ? "Genel puan:" : lang === "en" ? "Overall score:" : lang === "ar" ? "النتيجة الإجمالية:" : lang === "es" ? "Puntuación total:" : lang === "uk" ? "Загальний бал:" : lang === "fa" ? "امتیاز کلی:" : lang === "fr" ? "Note globale:" : "ڕێژەی گشتی:"} <b style={{ color: C.green }}>{Math.round(pct)}٪</b></div>
          </div>
        </div>
      )}

      <div style={{ display: "grid", gap: 14 }}>
        {questions.map((q, i) => (
          <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 14, padding: 16 }}>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 4, marginBottom: 10 }}>
              <div style={{ fontWeight: 600, fontSize: 15.5, lineHeight: 1.7, flex: 1 }} dir="auto">{i + 1}. {q.q}</div>
              <Speak text={q.q} />
            </div>
            <div style={{ display: "grid", gap: 8 }}>
              {q.options.map((opt, oi) => {
                const chosen = answers[i] === oi, isCorrect = q.correct === oi;
                let bg = "#fff", bd = C.line, col = C.ink;
                if (reviewed) {
                  if (isCorrect) { bg = "#e7f1ea"; bd = C.green; col = C.green; }
                  else if (chosen) { bg = "#fbeae6"; bd = C.red; col = C.redDk; }
                } else if (chosen) { bg = "#e3f0ef"; bd = C.red; }
                return (
                  <button key={oi} disabled={reviewed} onClick={() => setAnswers((a) => ({ ...a, [i]: oi }))}
                    style={{ textAlign: "right", background: bg, border: `1.5px solid ${bd}`, color: col, padding: "10px 14px", borderRadius: 10, fontSize: 14.5, fontWeight: chosen || (reviewed && isCorrect) ? 700 : 400 }}>
                    <span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}>{opt}</span>
                    {reviewed && isCorrect && " ✓"}{reviewed && chosen && !isCorrect && " ✗"}
                  </button>
                );
              })}
            </div>
            {reviewed && q.why && (
              <div style={{ marginTop: 10, background: "#fff8ec", border: `1px solid ${C.gold}`, borderRadius: 10, padding: "9px 13px", fontSize: 13.5, lineHeight: 1.7 }}>
                <span style={{ color: C.gold, fontWeight: 700 }}>◆ </span>{q.why}
              </div>
            )}
          </div>
        ))}
      </div>

      {!reviewed ? (
        <>
          {Object.keys(answers).length < questions.length && (
            <div style={{ marginTop: 14, textAlign: "center", fontSize: 13, color: C.muted }}>
              {questions.length - Object.keys(answers).length} {tApp(lang,"ai_unanswered")} — {tApp(lang,"ai_unanswered2")}.
            </div>
          )}
          <button onClick={check} style={{ width: "100%", marginTop: 12, background: C.green, color: "#fff", border: "none", padding: "13px", borderRadius: 11, fontWeight: 700, fontSize: 15 }}>
            {tApp(lang,"ai_submit")}
          </button>
        </>
      ) : (
        <div style={{ display: "flex", gap: 10, marginTop: 16 }}>
          <button onClick={generate} style={{ flex: 1, background: C.green, color: "#fff", border: "none", padding: "13px", borderRadius: 11, fontWeight: 700, fontSize: 15 }}>
            {tApp(lang,"ai_more10")}
          </button>
          <button onClick={() => setPhase("intro")} style={{ flex: 1, background: "transparent", color: C.red, border: `1.5px solid ${C.red}`, padding: "13px", borderRadius: 11, fontWeight: 700, fontSize: 15 }}>
            {tApp(lang,"ai_later")}
          </button>
        </div>
      )}
    </div>
  );
}

// ── تاقیکردنەوەی فەرمی / Official-style exam runner ───────────────
// ── دەستەواژە و گرێدەرە گرنگەکانی B1 / B1 Redemittel ──────────────
const B1_REDEMITTEL = [
  { de: "Meinung äußern", ku: "بۆچوون دەربڕین", tr: "Görüş bildirmek", uk: "Висловлювати думку", items: [
    { p: "Meiner Meinung nach …", ex: "Meiner Meinung nach ist Lernen sehr wichtig.", exku: "بەلای منەوە فێربوون زۆر گرنگە.", extr: "Benim görüşüme göre öğrenmek çok önemlidir." , exuk: "На мою думку, навчання дуже важливе." ,"exfr":"À mon avis, l'apprentissage est très important."},
    { p: "Ich denke, dass …", ex: "Ich denke, dass du recht hast.", exku: "پێم وایە تۆ ڕاست دەکەیت.", extr: "Bence haklısın." , exuk: "Я вважаю, що ти маєш рацію." ,"exfr":"Je pense que vous avez raison."},
    { p: "Ich glaube, dass …", ex: "Ich glaube, dass es morgen regnet.", exku: "باوەڕم وایە سبەینێ باران دەبارێت.", extr: "Yarın yağmur yağacağına inanıyorum." , exuk: "Я думаю, що завтра буде дощ." ,"exfr":"Je crois qu'il va pleuvoir demain."},
    { p: "Ich bin der Meinung, dass …", ex: "Ich bin der Meinung, dass Sport gesund ist.", exku: "ئەو بۆچوونەم هەیە کە وەرزش بۆ تەندروستی باشە.", extr: "Sporun sağlıklı olduğu görüşündeyim." , exuk: "Я дотримуюся думки, що спорт корисний для здоров'я." ,"exfr":"Je pense que le sport est en bonne santé."},
    { p: "Ich vertrete die Ansicht, dass …", ex: "Ich vertrete die Ansicht, dass Bildung frei sein sollte.", exku: "ئەو ڕایە دەگرم کە خوێندن دەبێت بەخۆڕایی بێت.", extr: "Eğitimin özgür olması gerektiği görüşünü savunuyorum." , exuk: "Я обстоюю думку, що освіта має бути безкоштовною." ,"exfr":"Je dis que l'éducation devrait être gratuite."},
    { p: "Soweit ich weiß …", ex: "Soweit ich weiß, ist das Geschäft heute geschlossen.", exku: "بەو ئەندازەیەی دەزانم، دوکانەکە ئەمڕۆ داخراوە.", extr: "Bildiğim kadarıyla dükkan bugün kapalı." , exuk: "Наскільки я знаю, магазин сьогодні зачинений." ,"exfr":"Pour autant que je sache, le magasin est fermé aujourd'hui."},
    { p: "Meines Erachtens …", ex: "Meines Erachtens ist das eine gute Idee.", exku: "بەبڕوای من ئەمە بیرۆکەیەکی باشە.", extr: "Bence bu iyi bir fikir." , exuk: "На мій погляд, це гарна ідея." ,"exfr":"Je pense que c'est une bonne idée."},
  ],"fr":"Rapport d'avis"},
  { de: "Zustimmung ausdrücken", ku: "ڕەزامەندی دەربڕین", tr: "Onay bildirmek", uk: "Висловлювати згоду", items: [
    { p: "Da stimme ich zu.", ex: "Du hast viel gearbeitet – da stimme ich zu.", exku: "زۆرت کار کردووە – لەگەڵتدا ڕازیم.", extr: "Çok çalıştın – buna katılıyorum." , exuk: "Ти багато працював — з цим я погоджуюся." ,"exfr":"Vous avez travaillé dur, je suis d'accord."},
    { p: "Ich bin damit einverstanden.", ex: "Ich bin damit einverstanden, früher anzufangen.", exku: "ڕازیم بە زووتر دەستپێکردن.", extr: "Daha erken başlamaya razıyım." , exuk: "Я згоден почати раніше." ,"exfr":"Je suis prêt à commencer plus tôt."},
    { p: "Das sehe ich genauso.", ex: "Das Wetter ist toll – das sehe ich genauso.", exku: "کەش‌وهەوا نایابە – منیش هەروا دەبینم.", extr: "Hava harika – ben de aynı şekilde görüyorum." , exuk: "Погода чудова — я вважаю так само." ,"exfr":"Le temps est beau, je le vois de la même façon."},
    { p: "Genau!", ex: "Genau! Das wollte ich auch sagen.", exku: "تەواو! منیش دەمویست ئەوە بڵێم.", extr: "Kesinlikle! Ben de bunu söylemek istedim." , exuk: "Саме так! Я теж хотів це сказати." ,"exfr":"C'est exactement ce que je voulais dire."},
    { p: "Da haben Sie recht.", ex: "Da haben Sie recht, das ist zu teuer.", exku: "ڕاست دەفەرموون، ئەمە زۆر گرانە.", extr: "Haklısınız, bu çok pahalı." , exuk: "Тут ви маєте рацію, це занадто дорого." ,"exfr":"Vous avez raison, c'est trop cher."},
  ],"fr":"Pour signaler la confirmation"},
  { de: "Widersprechen", ku: "پێچەوانەبوون", tr: "Karşı çıkmak", uk: "Заперечувати", items: [
    { p: "Da bin ich anderer Meinung.", ex: "Da bin ich anderer Meinung als du.", exku: "بۆچوونێکی جیاوازم لە تۆ هەیە.", extr: "Bu konuda senden farklı düşünüyorum." , exuk: "Тут я іншої думки, ніж ти." ,"exfr":"Je pense à ça différemment de toi."},
    { p: "Das sehe ich anders.", ex: "Das sehe ich anders, das ist nicht so einfach.", exku: "بە جۆرێکی تر دەیبینم، ئەوەندە ئاسان نییە.", extr: "Ben bunu farklı görüyorum, o kadar kolay değil." , exuk: "Я бачу це інакше, це не так просто." ,"exfr":"Je vois ça différemment, ce n'est pas si facile."},
    { p: "Ich kann dem nicht zustimmen.", ex: "Ich kann dem nicht zustimmen.", exku: "ناتوانم لەگەڵ ئەوەدا ڕازی بم.", extr: "Buna katılamıyorum." , exuk: "Я не можу з цим погодитися." ,"exfr":"Je ne peux pas être d'accord avec ça."},
    { p: "Ich bezweifle, dass …", ex: "Ich bezweifle, dass das funktioniert.", exku: "گومان دەکەم کە ئەمە کار بکات.", extr: "Bunun işe yarayacağından şüphe duyuyorum." , exuk: "Я сумніваюся, що це спрацює." ,"exfr":"Je doute que ça marche."},
    { p: "Ich bin nicht ganz überzeugt.", ex: "Ich bin nicht ganz überzeugt von dieser Idee.", exku: "بەتەواوی قایل نەبووم بەم بیرۆکەیە.", extr: "Bu fikre tam olarak ikna olmadım." , exuk: "Я не зовсім переконаний у цій ідеї." ,"exfr":"Je ne suis pas entièrement convaincu de cette idée."},
  ],"fr":"Pour résister"},
  { de: "Vorteile nennen", ku: "سوودەکان", tr: "Avantajları sıralamak", uk: "Називати переваги", items: [
    { p: "Ein Vorteil ist, dass …", ex: "Ein Vorteil ist, dass man Zeit spart.", exku: "سوودێک ئەوەیە کە کات دەپارێزرێت.", extr: "Bir avantajı zaman kazandırmasıdır." , exuk: "Одна перевага в тому, що це заощаджує час." ,"exfr":"Un avantage est qu'il gagne du temps."},
    { p: "Positiv ist auch, dass …", ex: "Positiv ist auch, dass es billig ist.", exku: "خاڵێکی ئەرێنیش ئەوەیە کە هەرزانە.", extr: "Olumlu bir nokta da ucuz olmasıdır." , exuk: "Позитивним є також те, що це дешево." ,"exfr":"Et le plus positif, c'est que c'est pas cher."},
    { p: "Dafür spricht, dass …", ex: "Dafür spricht, dass es umweltfreundlich ist.", exku: "ئەوەی لەبەرژەوەندیدایە ئەوەیە کە دۆستی ژینگەیە.", extr: "Lehine olan şu ki çevre dostudur." , exuk: "На користь цього говорить те, що це екологічно." ,"exfr":"Ce qui est en sa faveur, c'est qu'il est respectueux de l'environnement."},
    { p: "Nicht zu vergessen ist, dass …", ex: "Nicht zu vergessen ist, dass es gesund ist.", exku: "نابێت لەبیر بکرێت کە تەندروستە.", extr: "Unutulmaması gereken şu ki sağlıklıdır." , exuk: "Не варто забувати, що це корисно для здоров'я." ,"exfr":"Le truc à retenir, c'est que c'est sain."},
  ],"fr":"Pour mettre en place les avantages"},
  { de: "Nachteile nennen", ku: "زیانەکان", tr: "Dezavantajları sıralamak", uk: "Називати недоліки", items: [
    { p: "Ein Nachteil ist, dass …", ex: "Ein Nachteil ist, dass es teuer ist.", exku: "زیانێک ئەوەیە کە گرانە.", extr: "Bir dezavantajı pahalı olmasıdır." , exuk: "Один недолік у тому, що це дорого." ,"exfr":"Un inconvénient, c'est que c'est cher."},
    { p: "Problematisch ist, dass …", ex: "Problematisch ist, dass es zu wenig Zeit gibt.", exku: "کێشە ئەوەیە کە کاتی کەم هەیە.", extr: "Sorunlu olan şu ki çok az zaman var." , exuk: "Проблематично те, що замало часу." ,"exfr":"Le problème, c'est qu'il y a très peu de temps."},
    { p: "Dagegen spricht, dass …", ex: "Dagegen spricht, dass es laut ist.", exku: "ئەوەی دژیەتی ئەوەیە کە دەنگەدەنگە.", extr: "Aleyhine olan şu ki gürültülüdür." , exuk: "Проти цього говорить те, що це гучно." ,"exfr":"Le truc, c'est que c'est bruyant."},
    { p: "Kritisch sehe ich …", ex: "Kritisch sehe ich die hohen Kosten.", exku: "بە ڕەخنەوە لە تێچووە بەرزەکان دەڕوانم.", extr: "Eleştirel gözle yüksek maliyetleri değerlendiriyorum." , exuk: "Критично я оцінюю високі витрати." ,"exfr":"Je considère les coûts élevés avec l'œil critique."},
  ],"fr":"Pour régler les problèmes"},
  { de: "Vergleichen", ku: "بەراوردکردن", tr: "Karşılaştırmak", uk: "Порівнювати", items: [
    { p: "Im Vergleich zu …", ex: "Im Vergleich zu früher ist es besser.", exku: "بەراورد بە جاران، باشترە.", extr: "Eskiyle karşılaştırıldığında daha iyi." , exuk: "Порівняно з тим, що було раніше, це краще." ,"exfr":"Mieux que l'ancien."},
    { p: "Im Gegensatz zu …", ex: "Im Gegensatz zu dir mag ich Tee.", exku: "بەپێچەوانەی تۆ، حەزم لە چایە.", extr: "Senden farklı olarak çayı seviyorum." , exuk: "На відміну від тебе, я люблю чай." ,"exfr":"Contrairement à toi, j'aime le thé."},
    { p: "Einerseits …, andererseits …", ex: "Einerseits ist es teuer, andererseits ist es gut.", exku: "لەلایەکەوە گرانە، لەلایەکی ترەوە باشە.", extr: "Bir yandan pahalı, öte yandan iyi." , exuk: "З одного боку, це дорого, з іншого — добре." ,"exfr":"C'est cher, mais c'est bon."},
    { p: "Während …", ex: "Während er schläft, arbeite ich.", exku: "لە کاتێکدا ئەو دەخەوێت، من کار دەکەم.", extr: "O uyurken ben çalışıyorum." , exuk: "Поки він спить, я працюю." ,"exfr":"Je travaille pendant qu'il dort."},
    { p: "Anders als …", ex: "Anders als gestern ist es heute kalt.", exku: "بەپێچەوانەی دوێنێ، ئەمڕۆ ساردە.", extr: "Dünün aksine bugün soğuk." , exuk: "На відміну від учора, сьогодні холодно." ,"exfr":"Il fait froid aujourd'hui, contrairement à hier."},
  ],"fr":"Comparer"},
  { de: "Schlussfolgerung", ku: "دەرئەنجام", tr: "Sonuç çıkarmak", uk: "Висновок", items: [
    { p: "Zusammenfassend lässt sich sagen, dass …", ex: "Zusammenfassend lässt sich sagen, dass Sport wichtig ist.", exku: "بەکورتی دەتوانرێت بگوترێت کە وەرزش گرنگە.", extr: "Özetle sporun önemli olduğunu söyleyebiliriz." , exuk: "Підсумовуючи, можна сказати, що спорт важливий." ,"exfr":"Donc, en gros, le sport est important."},
    { p: "Abschließend möchte ich sagen, dass …", ex: "Abschließend möchte ich sagen, dass ich zufrieden bin.", exku: "لە کۆتاییدا دەمەوێت بڵێم کە ڕازیم.", extr: "Son olarak memnun olduğumu belirtmek istiyorum." , exuk: "На завершення хочу сказати, що я задоволений." ,"exfr":"Je suis enfin ravi."},
    { p: "Insgesamt kann man feststellen, dass …", ex: "Insgesamt kann man feststellen, dass es gut war.", exku: "بەگشتی دەتوانرێت دیاری بکرێت کە باش بوو.", extr: "Genel olarak iyi olduğu söylenebilir." , exuk: "Загалом можна констатувати, що це було добре." ,"exfr":"En général, c'est bon."},
    { p: "Daher bin ich der Meinung, dass …", ex: "Daher bin ich der Meinung, dass wir warten sollten.", exku: "بۆیە ئەو بۆچوونەم هەیە کە دەبێت چاوەڕێ بکەین.", extr: "Bu nedenle beklememiz gerektiği görüşündeyim." , exuk: "Тому я дотримуюся думки, що нам слід зачекати." ,"exfr":"C'est pourquoi je pense qu'on devrait attendre."},
  ],"fr":"Tirer des conclusions"},
  { de: "Formelle Redewendungen (E-Mail / Brief)", ku: "دەستەواژەی فەرمی", tr: "Resmi Deyimler (E-posta / Mektup)", uk: "Офіційні звороти (електронний лист / лист)", items: [
    { p: "Hiermit möchte ich …", ex: "Hiermit möchte ich mich für die Stelle bewerben.", exku: "بەمەوە دەمەوێت بۆ پۆستەکە داواکاری بکەم.", extr: "Bu vesileyle söz konusu pozisyona başvurmak istiyorum." , exuk: "Цим я хочу подати заявку на цю посаду." ,"exfr":"Je voudrais saisir cette occasion pour postuler à ce poste."},
    { p: "Ich wende mich an Sie, weil …", ex: "Ich wende mich an Sie, weil ich eine Frage habe.", exku: "پەیوەندیتان پێوە دەکەم، چونکە پرسیارێکم هەیە.", extr: "Bir sorum olduğu için size başvuruyorum." , exuk: "Я звертаюся до вас, бо в мене є запитання." ,"exfr":"Je vous demande à vous car j'ai une question."},
    { p: "Ich würde mich freuen, wenn …", ex: "Ich würde mich freuen, wenn Sie mir antworten.", exku: "دڵخۆش دەبم ئەگەر وەڵامم بدەنەوە.", extr: "Yanıt verirseniz çok memnun olurum." , exuk: "Я був би радий, якби ви мені відповіли." ,"exfr":"J'apprécierais que vous répondiez."},
    { p: "Für weitere Fragen stehe ich Ihnen gerne zur Verfügung.", ex: "Für weitere Fragen stehe ich Ihnen gerne zur Verfügung.", exku: "بۆ پرسیاری زیاتر بە خۆشحاڵییەوە لە خزمەتتانم.", extr: "Ek sorularınız için memnuniyetle hizmetinizdeyim." , exuk: "Із додаткових питань я із задоволенням до ваших послуг." ,"exfr":"Je suis heureux d'être à votre service pour d'autres questions."},
    { p: "Vielen Dank im Voraus.", ex: "Vielen Dank im Voraus für Ihre Hilfe.", exku: "پێشوەخت زۆر سوپاس بۆ یارمەتیتان.", extr: "Yardımınız için şimdiden çok teşekkürler." , exuk: "Заздалегідь дуже дякую за вашу допомогу." ,"exfr":"Merci beaucoup pour votre aide."},
  ],"fr":"Mots officiels (courriel / lettre)"},
  { de: "Konnektoren", ku: "گرێدەرەکان", tr: "Bağlaçlar", uk: "Сполучники", items: [
    { p: "weil", ex: "Ich bleibe, weil ich krank bin.", exku: "دەمێنمەوە، چونکە نەخۆشم.", extr: "Hasta olduğum için kalıyorum." , exuk: "Я залишаюся, бо я хворий." ,"exfr":"Je reste parce que je suis malade."},
    { p: "dass", ex: "Ich weiß, dass du kommst.", exku: "دەزانم کە دێیت.", extr: "Geleceğini biliyorum." , exuk: "Я знаю, що ти прийдеш." ,"exfr":"Je sais que tu viendras."},
    { p: "obwohl", ex: "Obwohl es regnet, gehe ich.", exku: "هەرچەندە باران دەبارێت، دەڕۆم.", extr: "Yağmur yağmasına rağmen gidiyorum." , exuk: "Хоча йде дощ, я йду." ,"exfr":"Je pars même s'il pleut."},
    { p: "wenn", ex: "Wenn ich Zeit habe, komme ich.", exku: "ئەگەر کاتم هەبێت، دێم.", extr: "Vaktim olursa gelirim." , exuk: "Якщо в мене буде час, я прийду." ,"exfr":"Je viendrai si j'ai le temps."},
    { p: "als", ex: "Als ich klein war, spielte ich viel.", exku: "کاتێک بچووک بووم، زۆر یاریم دەکرد.", extr: "Küçükken çok oynardım." , exuk: "Коли я був малим, я багато грався." ,"exfr":"J'avais l'habitude de jouer beaucoup quand j'étais petite."},
    { p: "nachdem", ex: "Nachdem ich gegessen hatte, ging ich.", exku: "دوای ئەوەی خواردبووم، ڕۆیشتم.", extr: "Yedikten sonra gittim." , exuk: "Після того, як я поїв, я пішов." ,"exfr":"Je suis parti après avoir mangé."},
    { p: "bevor", ex: "Bevor ich gehe, esse ich.", exku: "پێش ئەوەی بڕۆم، دەخۆم.", extr: "Gitmeden önce yerim." , exuk: "Перш ніж піти, я поїм." ,"exfr":"Je mangerai avant de partir."},
    { p: "während", ex: "Während sie kocht, lese ich.", exku: "لە کاتێکدا ئەو خواردن لێدەنێ، دەخوێنمەوە.", extr: "O pişirirken ben okuyorum." , exuk: "Поки вона готує, я читаю." ,"exfr":"Je l'ai lu pendant qu'il cuisine."},
    { p: "deshalb", ex: "Es regnet, deshalb bleibe ich zu Hause.", exku: "باران دەبارێت، بۆیە لە ماڵەوە دەمێنمەوە.", extr: "Yağmur yağıyor, bu yüzden evde kalıyorum." , exuk: "Йде дощ, тому я залишаюся вдома." ,"exfr":"Il pleut, alors je reste à la maison."},
    { p: "deswegen", ex: "Ich bin müde, deswegen schlafe ich.", exku: "ماندووم، لەبەر ئەوە دەخەوم.", extr: "Yorgunum, bu nedenle uyuyorum." , exuk: "Я втомився, тому я сплю." ,"exfr":"Je suis fatiguée, donc je dors."},
    { p: "daher", ex: "Es ist spät, daher gehe ich.", exku: "درەنگە، بۆیە دەڕۆم.", extr: "Geç oldu, bu yüzden gidiyorum." , exuk: "Уже пізно, тому я йду." ,"exfr":"Il est tard, alors je m'en vais."},
    { p: "trotzdem", ex: "Es regnet, trotzdem gehe ich spazieren.", exku: "باران دەبارێت، لەگەڵ ئەوەشدا بۆ پیادەڕۆیی دەچم.", extr: "Yağmur yağıyor, yine de yürüyüşe çıkıyorum." , exuk: "Йде дощ, проте я йду на прогулянку." ,"exfr":"Il pleut, mais je vais me promener."},
    { p: "außerdem", ex: "Es ist teuer, außerdem ist es alt.", exku: "گرانە، سەرباری ئەوەش کۆنە.", extr: "Pahalı, üstelik eski." , exuk: "Це дорого, до того ж воно старе." ,"exfr":"Cher, et vieux."},
    { p: "darüber hinaus", ex: "Es ist gut, darüber hinaus ist es billig.", exku: "باشە، جگە لەوەش هەرزانە.", extr: "İyi, üstelik ucuz." , exuk: "Це добре, до того ж воно дешеве." ,"exfr":"Bien, et bon marché."},
    { p: "hingegen", ex: "Ich mag Tee, er hingegen mag Kaffee.", exku: "حەزم لە چایە، ئەو بەپێچەوانەوە حەزی لە قاوەیە.", extr: "Ben çay severim, o ise kahveyi sever." , exuk: "Я люблю чай, а він натомість любить каву." ,"exfr":"J'aime le thé, il aime le café."},
  ],"fr":"Lingots"},
];

const B1_REDEMITTEL_UK = [
  { uk:"Висловлення думки", ex:["На мою думку, навчання є дуже важливим.","Я думаю, що ти маєш рацію.","Я вважаю, що завтра буде дощ.","Я дотримуюся думки, що спорт корисний для здоров’я.","Я відстоюю погляд, що освіта має бути вільною.","Наскільки мені відомо, магазин сьогодні зачинений.","На мій погляд, це гарна ідея."]},
  { uk:"Висловлення згоди", ex:["Ти багато працював — я з цим згоден.","Я згоден почати раніше.","Погода чудова — я бачу це так само.","Саме так! Я теж хотів це сказати.","Ви маєте рацію, це надто дорого."]},
  { uk:"Заперечення", ex:["Я маю іншу думку, ніж ти.","Я бачу це інакше, це не так просто.","Я не можу з цим погодитися.","Я сумніваюся, що це спрацює.","Ця ідея не цілком мене переконує."]},
  { uk:"Називання переваг", ex:["Одна з переваг полягає в тому, що можна заощадити час.","Позитивним є також те, що це дешево.","На користь цього свідчить те, що це екологічно.","Не слід забувати, що це корисно для здоров’я."]},
  { uk:"Називання недоліків", ex:["Один із недоліків полягає в тому, що це дорого.","Проблема полягає в тому, що часу замало.","Проти цього свідчить те, що там шумно.","Я критично оцінюю високі витрати."]},
  { uk:"Порівняння", ex:["Порівняно з минулим це стало краще.","На відміну від тебе, я люблю чай.","З одного боку, це дорого, а з іншого — якісно.","Поки він спить, я працюю.","На відміну від учора, сьогодні холодно."]},
  { uk:"Висновок", ex:["Підсумовуючи, можна сказати, що спорт важливий.","На завершення хочу сказати, що я задоволений.","Загалом можна констатувати, що все було добре.","Тому я вважаю, що нам слід зачекати."]},
  { uk:"Офіційні вислови (електронний лист / лист)", ex:["Цим я хотів би подати заявку на цю посаду.","Я звертаюся до Вас, тому що маю запитання.","Я був би радий, якби Ви мені відповіли.","Я охоче відповім на подальші запитання.","Заздалегідь дякую за Вашу допомогу."]},
  { uk:"Сполучники", ex:["Я залишаюся, тому що хворий.","Я знаю, що ти прийдеш.","Хоча йде дощ, я йду.","Якщо матиму час, я прийду.","Коли я був малим, я багато грався.","Після того як я поїв, я пішов.","Перед тим як піти, я поїм.","Поки вона готує, я читаю.","Йде дощ, тому я залишаюся вдома.","Я втомився, тому сплю.","Уже пізно, тому я йду.","Йде дощ, проте я йду гуляти.","Це дорого, а крім того, старе.","Це добре, до того ж дешево.","Я люблю чай, натомість він любить каву."]},
];
B1_REDEMITTEL.forEach((cat, ci) => {
  const uk = B1_REDEMITTEL_UK[ci];
  if (!uk) return;
  cat.uk = uk.uk;
  cat.items.forEach((item, ii) => { item.exuk = uk.ex[ii] || ""; });
});

function RedemittelPanel({ lang = "ku" }) {
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.muted, marginBottom: 10 }}>📚 {lang === "tr" ? "B1 Önemli İfadeler ve Bağlaçlar (örneklerle)" : lang === "en" ? "B1 Key Phrases and Connectors (with examples)" : lang === "ar" ? "عبارات وروابط B1 المهمة (بأمثلة)" : lang === "es" ? "B1 Frases clave y conectores (con ejemplos)" : lang === "uk" ? "B1 Ключові фрази та сполучники (з прикладами)" : lang === "fa" ? "B1 عبارات کلیدی و حروف ربط (با مثال)" : lang === "fr" ? "B1 Phrases et connecteurs clés (avec exemples)" : "دەستەواژە و گرێدەرە گرنگەکانی B1 (بە نموونە)"}</div>
      <div style={{ display: "grid", gap: 12 }}>
        {B1_REDEMITTEL.map((cat, ci) => (
          <CollapsibleCat key={ci} de={cat.de} ku={tC(cat, lang)} accent={C.gold}>
            <div style={{ display: "grid", gap: 12, marginTop: 12 }}>
              {cat.items.map((it, i) => (
                <div key={i} style={{ borderTop: i ? `1px dashed ${C.line}` : "none", paddingTop: i ? 10 : 0 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 4 }}><De size={15} color={C.red}>{it.p}</De></div>
                  <div style={{ display: "flex", alignItems: "center", gap: 3, marginTop: 4 }}>
                    <span style={{ color: C.gold, fontSize: 12, fontWeight: 700 }}>◆</span>
                    <De size={14.5} color={C.ink}>{it.ex}</De><Speak text={it.ex} size={13} />
                  </div>
                  {(lang === "uk" ? it.exuk : (it["ex"+lang] || it.exku)) && <div style={{ color: C.muted, fontSize: 14, marginTop: 3, lineHeight: 1.7 }}>{lang === "uk" ? it.exuk : (it["ex"+lang] || it.exku)}</div>}
                </div>
              ))}
            </div>
          </CollapsibleCat>
        ))}
      </div>
    </div>
  );
}

