function CollapsibleCat({ de, ku, accent, children }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderInlineStart: `5px solid ${accent}`, borderRadius: 14, overflow: "hidden" }}>
      <div
        onClick={() => setOpen(o => !o)}
        style={{ padding: 16, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "space-between", userSelect: "none" }}
      >
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: 16 }} dir="ltr">{de}</div>
          <div style={{ color: C.muted, fontSize: 13, marginTop: 2 }}>{ku}</div>
        </div>
        <span style={{ fontSize: 20, color: C.muted, transform: open ? "rotate(90deg)" : "rotate(0deg)", transition: "transform .2s", flexShrink: 0, marginInlineStart: 10 }}>›</span>
      </div>
      {open && (
        <div style={{ padding: "0 16px 16px", borderTop: `1px solid ${C.line}` }}>
          {children}
        </div>
      )}
    </div>
  );
}

function PhrasePanel({ title, data, accent, lang = "ku" }) {
  return (
    <div style={{ marginBottom: 18 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.muted, marginBottom: 10 }}>{title}</div>
      <div style={{ display: "grid", gap: 12 }}>
        {data.map((cat, ci) => (
          <CollapsibleCat key={ci} de={cat.de} ku={tC(cat, lang)} accent={accent}>
            <div style={{ display: "grid", gap: 11, marginTop: 12 }}>
              {cat.items.map((it, i) => {
                const hasEx = it.ex && it.ex !== it.p;
                const exTrans = lang === "uk" ? it.exuk : (it["ex"+lang] || it.exku);
                return (
                  <div key={i} style={{ borderTop: i ? `1px dashed ${C.line}` : "none", paddingTop: i ? 9 : 0 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 3 }}>
                      <De size={15} color={accent}>{it.p}</De>{!hasEx && <Speak text={it.p} size={13} />}
                    </div>
                    {hasEx && (
                      <div style={{ display: "flex", alignItems: "center", gap: 3, marginTop: 4 }}>
                        <span style={{ color: accent, fontSize: 12, fontWeight: 700 }}>◆</span>
                        <De size={14.5} color={C.ink}>{it.ex}</De><Speak text={it.ex} size={13} />
                      </div>
                    )}
                    {exTrans && <div style={{ color: C.muted, fontSize: 14, marginTop: 3, lineHeight: 1.7 }}>{exTrans}</div>}
                  </div>
                );
              })}
            </div>
          </CollapsibleCat>
        ))}
      </div>
    </div>
  );
}

function sectionsForLevel(level) {
  if (level === "A1") return [
    { type: "sprachbausteine", de: "Sprachbausteine", ku: "پێکهاتەی زمان" },
    { type: "hoeren", de: "Hören", ku: "گوێگرتن" },
    { type: "antworten", de: "Hören und antworten", ku: "گوێگرتن و وەڵامدانەوە" },
    { type: "lesen", de: "Lesen", ku: "خوێندنەوە" },
    { type: "schreiben", de: "Schreiben", ku: "نووسین" },
    { type: "muendlich", de: "Mündliche Prüfung", ku: "تاقیکردنەوەی زارەکی" },
  ];
  return [
    { type: "sprachbausteine", de: "Sprachbausteine", ku: "پێکهاتەی زمان" },
    { type: "hoeren", de: "Hören", ku: "گوێگرتن" },
    { type: "lesen", de: "Lesen", ku: "خوێندنەوە" },
    { type: "schreiben", de: "Schreiben", ku: "نووسین" },
    { type: "muendlich", de: "Mündliche Prüfung", ku: "تاقیکردنەوەی زارەکی" },
  ];
}

async function callAI(prompt, maxTokens = 1600) {
  const data = await callClaude({ model: "claude-sonnet-4-20250514", max_tokens: maxTokens, messages: [{ role: "user", content: prompt }] });
  let txt = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n").trim().replace(/```json|```/g, "").trim();
  return JSON.parse(txt);
}

function ExamRunner({ provName, provDe, level, onClose, onScore, lang = "ku" }) {
  const [idx, setIdx] = useState(0);
  const [data, setData] = useState({});      // type → content | "loading" | "error"
  const [ans, setAns] = useState({});        // type → answers
  const [phase, setPhase] = useState("run"); // run | overview | result
  const [result, setResult] = useState(null);
  const SECS = sectionsForLevel(level);

  const sec = SECS[idx];
  const base = lang === "tr"
    ? `${provName} (${provDe}) ${level} seviyesi resmi sınavı için Almanca içerik üret. `
    : `بۆ تاقیکردنەوەی فەرمی ${provName} (${provDe}) ئاستی ${level} بە زمانی ئەڵمانی. `;

  async function gen(type) {
    setData((d) => ({ ...d, [type]: "loading" }));
    let prompt, tokens = 2000;
    const A1 = level === "A1";
    if (type === "sprachbausteine") {
      prompt = lang === "tr"
        ? (A1
          ? base + `Bir mektup veya kısa metin oluştur, içinde ___1___ ile ___5___ şeklinde 5 boşluk olsun. Her boşluk için 3 seçenek ve doğru indeks. Yalnızca JSON: {"text":"___1___ içeren metin","gaps":[{"n":1,"options":["a","b","c"],"correct":0}]}`
          : base + `Sprachbausteine bölümü iki parçayla: Teil 1 (gap) ___1___-___6___ aralığında 6 boşluklu mektup, her biri 3 seçenek. Teil 2 (wordbank) ___11___-___15___ aralığında 5 boşluklu diyalog ve 6 kelimelik liste (a–f), her biri yalnızca bir kez kullanılır. Yalnızca JSON: {"parts":[{"kind":"gap","instruction":"Teil 1","text":"___1___ içeren metin","gaps":[{"n":1,"options":["a","b","c"],"correct":0}]},{"kind":"wordbank","instruction":"Teil 2","text":"___11___ içeren diyalog","options":["w1","w2","w3","w4","w5","w6"],"gaps":[{"n":11,"correct":2}]}]}`)
        : (A1
          ? base + `نامە یان دەقێکی کورت دروست بکە کە تێیدا ٥ بۆشایی هەبێت بە شێوەی ___1___ تا ___5___. بۆ هەر بۆشاییەک ٣ هەڵبژاردە و ئەو ژمارەیەی وەڵامی ڕاست. تەنها JSON: {"text":"دەق لەگەڵ ___1___","gaps":[{"n":1,"options":["a","b","c"],"correct":0}]}`
          : base + `بەشی Sprachbausteine بە دوو پارچە: Teil 1 (gap) نامەیەک لەگەڵ ٦ بۆشایی ___1___ تا ___6___، هەرکام ٣ هەڵبژاردە. Teil 2 (wordbank) دیالۆگێک لەگەڵ ٥ بۆشایی ___11___ تا ___15___ و لیستی ٦ وشە (a–f) کە هەرکام تەنها جارێک بەکاردێت (correct = ئیندێکسی وشە لە options). تەنها JSON: {"parts":[{"kind":"gap","instruction":"Teil 1","text":"دەق لەگەڵ ___1___","gaps":[{"n":1,"options":["a","b","c"],"correct":0}]},{"kind":"wordbank","instruction":"Teil 2","text":"دیالۆگ لەگەڵ ___11___","options":["w1","w2","w3","w4","w5","w6"],"gaps":[{"n":11,"correct":2}]}]}`);
      tokens = 2600;
    } else if (type === "hoeren") {
      prompt = lang === "tr"
        ? (A1
          ? base + `Dinleme için 3 kısa metin (doğru/yanlış) ve 3 metin (a/b seçimi). Yalnızca JSON: {"rf":[{"situation":"Türkçe durum açıklaması","transcript":"Almanca metin","statement":"Almanca ifade","correct":true}],"mc":[{"transcript":"Almanca metin","q":"Soru","options":["a","b"],"correct":0}]}`
          : base + `Hören bölümü üç parçayla, tümü doğru/yanlış ve sesli. Teil 1: 3 parça, Teil 2: 2 parça, Teil 3: 3 parça. Her parça transcript (Almanca), statement (Almanca) ve correct(true/false). Yalnızca JSON: {"parts":[{"kind":"rf","instruction":"Teil 1","audio":true,"items":[{"transcript":"..","statement":"..","correct":true}]},{"kind":"rf","instruction":"Teil 2","audio":true,"items":[{"transcript":"..","statement":"..","correct":false}]},{"kind":"rf","instruction":"Teil 3","audio":true,"items":[{"transcript":"..","statement":"..","correct":true}]}]}`)
        : (A1
          ? base + `٣ تێکستی گوێگرتنی کورت بۆ ڕاست/هەڵە و ٣ تێکست بۆ هەڵبژاردنی a/b. تەنها JSON: {"rf":[{"situation":"دۆخ بە سۆرانی","transcript":"دەقی ئەڵمانی","statement":"بانگەشە بە ئەڵمانی","correct":true}],"mc":[{"transcript":"دەقی ئەڵمانی","q":"پرسیار","options":["a","b"],"correct":0}]}`
          : base + `بەشی Hören بە سێ پارچە، هەموو ڕاست/هەڵە و دەنگدار. Teil 1: ٣ بەند، Teil 2: ٢ بەند، Teil 3: ٣ بەند. هەر بەند transcript (ئەڵمانی) و statement (ئەڵمانی) و correct(true/false). تەنها JSON: {"parts":[{"kind":"rf","instruction":"Teil 1","audio":true,"items":[{"transcript":"..","statement":"..","correct":true}]},{"kind":"rf","instruction":"Teil 2","audio":true,"items":[{"transcript":"..","statement":"..","correct":false}]},{"kind":"rf","instruction":"Teil 3","audio":true,"items":[{"transcript":"..","statement":"..","correct":true}]}]}`);
      tokens = 2600;
    } else if (type === "antworten") {
      prompt = base + (lang === "tr"
        ? `3 kısa Almanca konuşma/soru (prompts) ve 4 hazır yanıt (responses). Her konuşma için uygun yanıtın indeksi. Yalnızca JSON: {"prompts":["..","..",".."],"responses":["..","..","..",".."],"answers":[2,0,3]}`
        : `٣ ئاخاوتن یان پرسیاری کورت (prompts) و ٤ وەڵامی ئامادە (responses). بۆ هەر ئاخاوتنێک ئیندێکسی ئەو وەڵامەی دەگونجێت. تەنها JSON: {"prompts":["..","..",".."],"responses":["..","..","..",".."],"answers":[2,0,3]}`);
    } else if (type === "lesen") {
      prompt = lang === "tr"
        ? (A1
          ? base + `Okuma bölümü üç parçayla. Teil A: 4 başlık ve 3 çok kısa metin, her metin için uygun başlık indeksi. Teil B: Kısa metin + 3 doğru/yanlış ifade. Teil C: 3 durum, her biri iki ilan (a,b), doğru indeks. Yalnızca JSON: {"teilA":{"headings":["a","b","c","d"],"texts":["..","..",".."],"answers":[0,1,2]},"teilB":{"text":"..","items":[{"statement":"..","correct":true}]},"teilC":[{"situation":"..","a":"..","b":"..","correct":0}]}`
          : base + `Lesen bölümü üç parçayla. Teil 1 (eşleştirme): 4 kısa metin + 6 başlık, her metin için başlık indeksi. Teil 2 (rf): Bir metin + 2 doğru/yanlış ifade. Teil 3 (pasaj eşleştirme): 6 parçaya bölünmüş metin (a–f) + 4 görev, her görev için bilgiyi içeren parça indeksi. Yalnızca JSON: {"parts":[{"kind":"match","instruction":"Teil 1","texts":["t1","t2","t3","t4"],"options":["h1","h2","h3","h4","h5","h6"],"answers":[0,1,2,3]},{"kind":"rf","instruction":"Teil 2","text":"..","items":[{"statement":"..","correct":true},{"statement":"..","correct":false}]},{"kind":"match","instruction":"Teil 3","passage":[{"label":"a","text":".."},{"label":"b","text":".."}],"prompts":["..","..","..",".."],"answers":[0,1,2,3]}]}`)
        : (A1
          ? base + `بەشی خوێندنەوە بە سێ پارچە. Teil A: ٤ سەردێڕ و ٣ دەقی زۆر کورت، بۆ هەر دەقێک ئیندێکسی سەردێڕی گونجاو. Teil B: دەقێکی کورت + ٣ بانگەشە ڕاست/هەڵە. Teil C: ٣ دۆخ، هەر یەک دوو ڕیکلام (a,b)، ئیندێکسی ڕاست. تەنها JSON: {"teilA":{"headings":["a","b","c","d"],"texts":["..","..",".."],"answers":[0,1,2]},"teilB":{"text":"..","items":[{"statement":"..","correct":true}]},"teilC":[{"situation":"..","a":"..","b":"..","correct":0}]}`
          : base + `بەشی Lesen بە سێ پارچە. Teil 1 (match): ٤ دەقی کورت + ٦ سەردێڕ (headings)، بۆ هەر دەقێک ئیندێکسی سەردێڕ. Teil 2 (rf): دەقێک + ٢ بانگەشە ڕاست/هەڵە. Teil 3 (match-passage): دەقێکی دابەشکراو بۆ ٦ پارچە (label a–f) + ٤ ئەرک، بۆ هەر ئەرکێک ئیندێکسی ئەو پارچەیەی زانیاری تێدایە. تەنها JSON: {"parts":[{"kind":"match","instruction":"Teil 1","texts":["t1","t2","t3","t4"],"options":["h1","h2","h3","h4","h5","h6"],"answers":[0,1,2,3]},{"kind":"rf","instruction":"Teil 2","text":"..","items":[{"statement":"..","correct":true},{"statement":"..","correct":false}]},{"kind":"match","instruction":"Teil 3","passage":[{"label":"a","text":".."},{"label":"b","text":".."}],"prompts":["..","..","..",".."],"answers":[0,1,2,3]}]}`);
      tokens = 2800;
    } else if (type === "schreiben") {
      prompt = base + (lang === "tr"
        ? (A1
          ? `Yazma bölümü iki parçayla. Teil A: Form (Formular) — talimat + bir kişi tanımı + 5 alan (36–40). Teil B: 3 maddelik kısa e-posta. Yalnızca JSON: {"teilA":{"intro":"..","person":"..","fields":[{"n":36,"label":"Familienname"}]},"teilB":{"task":".."}}`
          : `Bir arkadaşa 6 maddelik e-posta görevi, öğrenci 3 tane seçsin. Yalnızca JSON: {"task":"Almanca görev isteği + 6 madde (•) + Türkçe kısa açıklama"}`)
        : (A1
          ? `بەشی نووسین بە دوو پارچە. Teil A: فۆرم (Formular) — ڕێنمایی + وەسفی کەسێک + ٥ خانە (٣٦–٤٠). Teil B: ئیمەیلێکی کورت لەگەڵ ٣ خاڵ. تەنها JSON: {"teilA":{"intro":"..","person":"..","fields":[{"n":36,"label":"Familienname"}]},"teilB":{"task":".."}}`
          : `ئەرکی نووسینی ئیمەیل بۆ هاوڕێیەک لەگەڵ ٦ خاڵ، فێرخواز ٣ هەڵدەبژێرێت. تەنها JSON: {"task":"داواکاری ئەرکەکە بە ئەڵمانی + ٦ خاڵ (•) + ڕوونکردنەوەی کورتی سۆرانی"}`));
    } else if (type === "muendlich") {
      prompt = base + (lang === "tr"
        ? (A1
          ? `A1 için konuşma görevi. Yalnızca JSON: {"task":"Almanca görev + Türkçe kısa açıklama"}`
          : `Üç bölümlü sözlü sınav görevi: Teil 1 kendini tanıtma, Teil 2 bilgi alışverişi, Teil 3 etkinlik üzerinde anlaşma. Yalnızca JSON: {"task":"Her üç bölüm Almanca + Türkçe kısa açıklama"}`)
        : (A1
          ? `ئەرکێکی قسەکردن بۆ A1. تەنها JSON: {"task":"ئەرکەکە بە ئەڵمانی + ڕوونکردنەوەی کورتی سۆرانی"}`
          : `ئەرکی تاقیکردنەوەی زارەکی بە سێ پارچە: Teil 1 ناسیاوبوون، Teil 2 ئاڵوگۆڕی زانیاری، Teil 3 ڕێككەوتن لەسەر چالاکی. تەنها JSON: {"task":"هەر سێ پارچەکە بە ئەڵمانی + ڕوونکردنەوەی کورتی سۆرانی"}`));
    }
    try { const j = await callAI(prompt, tokens); setData((d) => ({ ...d, [type]: j })); }
    catch { setData((d) => ({ ...d, [type]: "error" })); }
  }

  useEffect(() => {
    queueMicrotask(() => gen(SECS[0].type));
    // This intentionally starts only the first section on mount; navigation loads later sections.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function openSection(nextIdx) {
    const nextType = SECS[nextIdx].type;
    setPhase("run");
    setIdx(nextIdx);
    if (data[nextType] === undefined) gen(nextType);
  }

  function submit() {
    let correct = 0, total = 0;
    const gradeParts = (parts, a) => {
      (parts || []).forEach((p, pi) => {
        if (p.kind === "gap" || p.kind === "wordbank") (p.gaps || []).forEach((g, i) => { total++; if (a[pi + "_" + i] === g.correct) correct++; });
        else if (p.kind === "rf") (p.items || []).forEach((it, i) => { total++; if (a[pi + "_" + i] === it.correct) correct++; });
        else if (p.kind === "mc") (p.items || []).forEach((it, i) => { total++; if (a[pi + "_" + i] === it.correct) correct++; });
        else if (p.kind === "match") (p.answers || []).forEach((cor, i) => { total++; if (a[pi + "_" + i] === cor) correct++; });
      });
    };
    for (const s of SECS) {
      const c = data[s.type]; const a = ans[s.type] || {};
      if (!c || c === "loading" || c === "error") continue;
      if (c.parts) { gradeParts(c.parts, a); continue; }
      if (s.type === "sprachbausteine") c.gaps.forEach((g, i) => { total++; if (a[i] === g.correct) correct++; });
      else if (s.type === "hoeren") { (c.rf || []).forEach((it, i) => { total++; if (a["rf" + i] === it.correct) correct++; }); (c.mc || []).forEach((it, i) => { total++; if (a["mc" + i] === it.correct) correct++; }); }
      else if (s.type === "antworten") (c.answers || []).forEach((cor, i) => { total++; if (a[i] === cor) correct++; });
      else if (s.type === "lesen") {
        if (c.teilA) (c.teilA.answers || []).forEach((cor, i) => { total++; if (a["A" + i] === cor) correct++; });
        if (c.teilB) (c.teilB.items || []).forEach((it, i) => { total++; if (a["B" + i] === it.correct) correct++; });
        if (Array.isArray(c.teilC)) c.teilC.forEach((it, i) => { total++; if (a["C" + i] === it.correct) correct++; });
      }
    }
    const pct = total ? Math.round((correct / total) * 100) : 0;
    setResult({ correct, total, pct });
    setPhase("result");
    onScore && onScore(pct);
  }

  // ── RESULT ──
  if (phase === "result" && result) {
    const passed = result.pct >= 60;
    return (
      <div className="rise" style={{ textAlign: "center" }}>
        <div style={{ background: passed ? C.green : C.red, color: "#fff", borderRadius: 20, padding: "28px 20px" }}>
          <div style={{ fontSize: 40 }}>{passed ? "🎉" : "💪"}</div>
          <div style={{ fontWeight: 700, fontSize: 22, marginTop: 8 }}>{provName} — {level}</div>
          <div style={{ fontSize: 48, fontWeight: 800, marginTop: 6 }} dir="ltr">{result.pct}%</div>
          <div style={{ fontSize: 15, opacity: .92, marginTop: 4 }} dir="ltr">{result.correct} / {result.total}</div>
          <div style={{ fontSize: 15, marginTop: 10 }}>{passed ? (lang === "tr" ? "Tebrikler! Geçtiniz ✓" : lang === "en" ? "Congratulations! You passed ✓" : lang === "ar" ? "تهانينا! لقد نجحت ✓" : lang === "es" ? "¡Enhorabuena! Has aprobado ✓" : lang === "uk" ? "Вітаємо! Ви склали ✓" : lang === "fa" ? "تبریک! قبول شدید ✓" : lang === "fr" ? "Félicitations! Vous avez passé ✓" : "پیرۆزە! دەرچوویت ✓") : (lang === "tr" ? "Henüz daha fazla pratik yapmanız gerekiyor." : lang === "en" ? "You still need more practice." : lang === "ar" ? "ما زلت بحاجة إلى مزيد من التدريب." : lang === "es" ? "Aún necesitas practicar más." : lang === "uk" ? "Вам потрібно ще потренуватися." : lang === "fa" ? "هنوز باید بیشتر تمرین کنید." : lang === "fr" ? "Il te faut encore plus d'entraînement." : "هێشتا پێویستت بە مەشقی زیاترە.")}</div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          <button onClick={() => { setData({}); setAns({}); setResult(null); gen(SECS[0].type); openSection(0); }} style={{ flex: 1, background: C.red, color: "#fff", border: "none", padding: 13, borderRadius: 11, fontWeight: 700 }}>{lang === "tr" ? "Tekrar" : lang === "en" ? "Retry" : lang === "ar" ? "إعادة" : lang === "es" ? "Reintentar" : lang === "uk" ? "Повторити" : lang === "fa" ? "تکرار" : lang === "fr" ? "Réessayer" : "دووبارە"}</button>
          <button onClick={onClose} style={{ flex: 1, background: "transparent", color: C.ink, border: `1.5px solid ${C.line}`, padding: 13, borderRadius: 11, fontWeight: 700 }}>{lang === "tr" ? "Kapat" : lang === "en" ? "Close" : lang === "ar" ? "إغلاق" : lang === "es" ? "Cerrar" : lang === "uk" ? "Закрити" : lang === "fa" ? "بستن" : lang === "fr" ? "Fermer" : "داخستن"}</button>
        </div>
      </div>
    );
  }

  // ── OVERVIEW ──
  if (phase === "overview") {
    return (
      <div className="rise">
        <h3 style={{ fontWeight: 700, fontSize: 20, marginBottom: 4 }}>📋 {lang === "tr" ? "Genel Bakış" : lang === "en" ? "Overview" : lang === "ar" ? "نظرة عامة" : lang === "es" ? "Resumen" : lang === "uk" ? "Огляд" : lang === "fa" ? "نمای کلی" : lang === "fr" ? "Aperçu général" : "پێداچوونەوە"}</h3>
        <p style={{ color: C.muted, fontSize: 14, marginBottom: 16 }}>{lang === "tr" ? "Göndermeden önce bölümleri kontrol edin." : lang === "en" ? "Check the sections before submitting." : lang === "ar" ? "تحقق من الأقسام قبل الإرسال." : lang === "es" ? "Revisa las secciones antes de enviar." : lang === "uk" ? "Перевірте розділи перед надсиланням." : lang === "fa" ? "پیش از ارسال بخش‌ها را بررسی کنید." : lang === "fr" ? "Vérifiez les sections avant de soumettre." : "پێش ناردن، دڵنیابە لە بەشەکان."}</p>
        <div style={{ display: "grid", gap: 10 }}>
          {SECS.map((s, i) => {
            const c = data[s.type]; const a = ans[s.type] || {};
            let info = lang === "tr" ? "Tamamlanmadı" : lang === "en" ? "Not completed" : lang === "ar" ? "غير مكتمل" : lang === "es" ? "Sin completar" : lang === "uk" ? "Не завершено" : lang === "fa" ? "کامل نشده" : lang === "fr" ? "Non achevée" : "نەکراوەتەوە";
            if (c && c !== "loading" && c !== "error") {
              if (s.type === "schreiben") info = lang === "tr" ? "Elle (kağıt) ✍️" : lang === "en" ? "By hand (paper) ✍️" : lang === "ar" ? "بخط اليد (ورقة) ✍️" : lang === "es" ? "A mano (papel) ✍️" : lang === "uk" ? "Від руки (папір) ✍️" : lang === "fa" ? "با دست (کاغذ) ✍️" : lang === "fr" ? "À la main (papier)" : "بە دەست (دەفتەر) ✍️";
              else if (s.type === "muendlich") info = lang === "tr" ? "Sözlü 🗣️" : lang === "en" ? "Spoken 🗣️" : lang === "ar" ? "شفهي 🗣️" : lang === "es" ? "Oral 🗣️" : lang === "uk" ? "Усно 🗣️" : lang === "fa" ? "شفاهی 🗣️" : lang === "fr" ? "Parlé" : "زارەکی 🗣️";
              else { const n = Object.keys(a).length; info = lang === "tr" ? `${n} cevap` : lang === "en" ? `${n} answers` : lang === "ar" ? `${n} إجابة` : lang === "fa" ? `${n} پاسخ` : lang === "es" ? `${n} respuestas` : lang === "uk" ? `${n} відповідей` : lang === "fr" ? `Réponses` : `${n} وەڵام`; }
            }
            return (
              <button key={s.type} onClick={() => openSection(i)} style={{ textAlign: "right", background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: "13px 16px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span><b dir="ltr">{i + 1}. {s.de}</b> <span style={{ color: C.muted, fontSize: 13 }}>· {tC(s, lang)}</span></span>
                <span style={{ color: C.muted, fontSize: 13 }}>{info}</span>
              </button>
            );
          })}
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 18 }}>
          <button onClick={submit} style={{ flex: 1, background: C.green, color: "#fff", border: "none", padding: 14, borderRadius: 11, fontWeight: 700, fontSize: 15 }}>📨 {lang === "tr" ? "Gönder ve Puanı Al" : lang === "en" ? "Submit and Get Score" : lang === "ar" ? "إرسال والحصول على النتيجة" : lang === "es" ? "Enviar y obtener puntuación" : lang === "uk" ? "Надіслати та отримати бал" : lang === "fa" ? "ارسال و دریافت امتیاز" : lang === "fr" ? "Soumettre et obtenir un score" : "ناردن و وەرگرتنی نمرە"}</button>
          <button onClick={() => openSection(SECS.length - 1)} style={{ background: "transparent", color: C.ink, border: `1.5px solid ${C.line}`, padding: "14px 18px", borderRadius: 11, fontWeight: 700 }}>{lang === "tr" ? "Geri" : lang === "en" ? "Back" : lang === "ar" ? "رجوع" : lang === "es" ? "Atrás" : lang === "uk" ? "Назад" : lang === "fa" ? "بازگشت" : lang === "fr" ? "Précédent" : "گەڕانەوە"}</button>
        </div>
      </div>
    );
  }

  // ── RUN (one section) ──
  const content = data[sec.type];
  const a = ans[sec.type] || {};
  const setA = (v) => setAns((p) => ({ ...p, [sec.type]: v }));
  const Opt = ({ on, active, children }) => (
    <button onClick={on} style={{ textAlign: "right", background: active ? "#e3f0ef" : "#fff", border: `1.5px solid ${active ? C.red : C.line}`, color: C.ink, padding: "9px 13px", borderRadius: 9, fontSize: 14.5, fontWeight: active ? 700 : 400 }}>{children}</button>
  );

  return (
    <div className="rise">
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
        <span dir="ltr" style={{ background: C.red, color: "#fff", borderRadius: 8, padding: "2px 9px", fontSize: 13, fontWeight: 700 }}>{idx + 1}/{SECS.length}</span>
        <h3 style={{ fontWeight: 700, fontSize: 19 }} dir="ltr">{sec.de}</h3>
      </div>
      <p style={{ color: C.muted, fontSize: 13.5, marginBottom: 14 }}>{tC(sec, lang)}</p>

      {content === "loading" && <div style={{ textAlign: "center", color: C.muted, padding: 24 }}>⏳ {lang === "tr" ? "AI bu bölümü oluşturuyor…" : lang === "en" ? "AI is generating this section…" : lang === "ar" ? "الذكاء الاصطناعي يُنشئ هذا القسم…" : lang === "es" ? "La IA está generando esta sección…" : lang === "uk" ? "ШІ генерує цей розділ…" : lang === "fa" ? "هوش مصنوعی در حال ساختن این بخش است…" : lang === "fr" ? "L'IA génère cette section..." : "ڕێبەر AI ئەم بەشە دروست دەکات…"}</div>}
      {content === "error" && <div style={{ textAlign: "center", padding: 18, background: "#fbeae6", borderRadius: 12 }}><div style={{ color: C.redDk, marginBottom: 8 }}>{lang === "tr" ? "Hata oluştu." : lang === "en" ? "An error occurred." : lang === "ar" ? "حدث خطأ." : lang === "es" ? "Ocurrió un error." : lang === "uk" ? "Сталася помилка." : lang === "fa" ? "خطایی رخ داد." : lang === "fr" ? "Une erreur s'est produite." : "هەڵە ڕوویدا."}</div><button onClick={() => gen(sec.type)} style={{ background: C.red, color: "#fff", border: "none", padding: "8px 16px", borderRadius: 9, fontWeight: 700 }}>{lang === "tr" ? "Tekrar" : lang === "en" ? "Retry" : lang === "ar" ? "إعادة" : lang === "es" ? "Reintentar" : lang === "uk" ? "Повторити" : lang === "fa" ? "تکرار" : lang === "fr" ? "Réessayer" : "دووبارە"}</button></div>}

      {content && content !== "loading" && content !== "error" && (
        <div style={{ display: "grid", gap: 14 }}>
          {content.parts && content.parts.map((p, pi) => {
            const setPA = (i, v) => setA({ ...a, [pi + "_" + i]: v });
            return (
              <div key={pi} style={{ display: "grid", gap: 12 }}>
                {p.instruction && <div style={{ fontWeight: 700, color: C.muted, fontSize: 13 }} dir="auto">{p.instruction}</div>}

                {(p.kind === "gap") && (<>
                  <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 2 }} dir="ltr"><De size={15}>{p.text}</De></div>
                  {p.gaps.map((g, i) => (
                    <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: "10px 14px", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                      <span style={{ fontWeight: 700, color: C.red, minWidth: 22 }} dir="ltr">{g.n}.</span>
                      {g.options.map((o, oi) => {
                        const on = a[pi + "_" + i] === oi;
                        return <button key={oi} onClick={() => setPA(i, oi)} style={{ background: on ? C.red : "#fff", color: on ? "#fff" : C.ink, border: `1.5px solid ${on ? C.red : C.line}`, borderRadius: 8, padding: "5px 11px", fontSize: 14, fontWeight: on ? 700 : 400 }}><span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}>{o}</span></button>;
                      })}
                    </div>
                  ))}
                </>)}

                {(p.kind === "wordbank") && (<>
                  <div style={{ background: C.bg, border: `1px solid ${C.line}`, borderRadius: 12, padding: 12 }}>
                    {p.options.map((o, oi) => <span key={oi} dir="ltr" style={{ display: "inline-block", margin: 3, background: "#fff", border: `1px solid ${C.line}`, borderRadius: 8, padding: "4px 9px", fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 13.5 }}>{String.fromCharCode(97 + oi)}) {o}</span>)}
                  </div>
                  <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 2 }} dir="ltr"><De size={15}>{p.text}</De></div>
                  {p.gaps.map((g, i) => (
                    <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: "10px 14px", display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                      <span style={{ fontWeight: 700, color: C.red, minWidth: 22 }} dir="ltr">{g.n}.</span>
                      {p.options.map((o, oi) => {
                        const on = a[pi + "_" + i] === oi;
                        return <button key={oi} onClick={() => setPA(i, oi)} style={{ background: on ? C.red : "#fff", color: on ? "#fff" : C.ink, border: `1.5px solid ${on ? C.red : C.line}`, borderRadius: 7, padding: "5px 10px", fontSize: 13.5, fontWeight: 700 }}><span dir="ltr">{String.fromCharCode(97 + oi)}</span></button>;
                      })}
                    </div>
                  ))}
                </>)}

                {(p.kind === "rf") && (<>
                  {p.text && <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="ltr"><De size={14.5}>{p.text}</De></div>}
                  {p.items.map((it, i) => (
                    <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                      {p.audio && it.transcript && <button onClick={() => speakDe(it.transcript)} style={{ background: C.gold, color: "#fff", border: "none", borderRadius: 9, padding: "6px 12px", fontWeight: 700, fontSize: 13, marginBottom: 8, display:"inline-flex", alignItems:"center", gap:5 }}><Volume2 size={13} /> {lang === "tr" ? `Dinle ${i + 1}` : lang === "en" ? `Listen ${i + 1}` : lang === "ar" ? `استمع ${i + 1}` : `گوێ بگرە ${i + 1}`}</button>}
                      <div dir="ltr" style={{ marginBottom: 10 }}><De size={15}>{it.statement}</De></div>
                      <div style={{ display: "flex", gap: 8 }}>
                        <Opt on={() => setPA(i, true)} active={a[pi + "_" + i] === true}>PLUS (+)</Opt>
                        <Opt on={() => setPA(i, false)} active={a[pi + "_" + i] === false}>MINUS (–)</Opt>
                      </div>
                    </div>
                  ))}
                </>)}

                {(p.kind === "mc") && (<>
                  {p.text && <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="ltr"><De size={14.5}>{p.text}</De></div>}
                  {p.items.map((it, i) => (
                    <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                      {p.audio && it.transcript && <button onClick={() => speakDe(it.transcript)} style={{ background: C.gold, color: "#fff", border: "none", borderRadius: 9, padding: "6px 12px", fontWeight: 700, fontSize: 13, marginBottom: 8, display:"inline-flex", alignItems:"center", gap:5 }}><Volume2 size={13} /> {lang === "tr" ? `Dinle ${i + 1}` : lang === "en" ? `Listen ${i + 1}` : lang === "ar" ? `استمع ${i + 1}` : `گوێ بگرە ${i + 1}`}</button>}
                      <div dir="ltr" style={{ fontWeight: 600, marginBottom: 8 }}><De size={15}>{it.q}</De></div>
                      <div style={{ display: "grid", gap: 7 }}>{it.options.map((o, oi) => <Opt key={oi} on={() => setPA(i, oi)} active={a[pi + "_" + i] === oi}><span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}>{String.fromCharCode(97 + oi)}) {o}</span></Opt>)}</div>
                    </div>
                  ))}
                </>)}

                {(p.kind === "match") && (() => {
                  const usePassage = Array.isArray(p.passage) && p.passage.length;
                  const items = p.prompts || p.texts || [];
                  const opts = usePassage ? p.passage.map((x) => x.label) : (p.options || []);
                  return (<>
                    {usePassage ? (
                      <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                        {p.passage.map((x, xi) => <div key={xi} dir="ltr" style={{ padding: "5px 0", borderBottom: xi < p.passage.length - 1 ? `1px solid ${C.line}` : "none" }}><b style={{ color: C.red }}>{x.label})</b> <De size={13.5}>{x.text}</De></div>)}
                      </div>
                    ) : (
                      <div style={{ background: C.bg, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                        {opts.map((o, oi) => <div key={oi} dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 14, padding: "3px 0" }}>{String.fromCharCode(97 + oi)}) {o}</div>)}
                      </div>
                    )}
                    {items.map((t, i) => (
                      <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                        <div dir="ltr" style={{ marginBottom: 10, lineHeight: 1.8 }}><De size={14.5}>{t}</De></div>
                        <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>{opts.map((o, oi) => <Opt key={oi} on={() => setPA(i, oi)} active={a[pi + "_" + i] === oi}><span dir="ltr">{String.fromCharCode(97 + oi)}</span></Opt>)}</div>
                      </div>
                    ))}
                  </>);
                })()}
              </div>
            );
          })}

          {!content.parts && sec.type === "sprachbausteine" && (<>
            <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 2 }} dir="ltr"><De size={15}>{content.text}</De></div>
            {content.gaps.map((g, i) => (
              <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: "10px 14px", display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                <span style={{ fontWeight: 700, color: C.red, minWidth: 22 }} dir="ltr">{g.n}.</span>
                {g.options.map((o, oi) => {
                  const on = a[i] === oi;
                  return <button key={oi} onClick={() => setA({ ...a, [i]: oi })} style={{ background: on ? C.red : "#fff", color: on ? "#fff" : C.ink, border: `1.5px solid ${on ? C.red : C.line}`, borderRadius: 8, padding: "5px 11px", fontSize: 14, fontWeight: on ? 700 : 400 }}><span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}>{o}</span></button>;
                })}
              </div>
            ))}
          </>)}

          {!content.parts && sec.type === "hoeren" && (<>
            <div style={{ fontWeight: 700, color: C.muted, fontSize: 13 }}>Teil A — RICHTIG (+) / FALSCH (–)</div>
            {(content.rf || []).map((it, i) => (
              <div key={"rf" + i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                <div style={{ fontSize: 13, color: C.muted, marginBottom: 6 }}>{it.situation}</div>
                <button onClick={() => speakDe(it.transcript)} style={{ background: C.gold, color: "#fff", border: "none", borderRadius: 9, padding: "6px 12px", fontWeight: 700, fontSize: 13, marginBottom: 8, display:"inline-flex", alignItems:"center", gap:5 }}><Volume2 size={13} /> {lang === "tr" ? "Dinle" : lang === "en" ? "Listen" : lang === "ar" ? "استمع" : lang === "es" ? "Escuchar" : lang === "uk" ? "Слухати" : lang === "fa" ? "گوش دادن" : lang === "fr" ? "Écoute." : "گوێ بگرە"}</button>
                <div dir="ltr" style={{ marginBottom: 10 }}><De size={15}>{it.statement}</De></div>
                <div style={{ display: "flex", gap: 8 }}>
                  <Opt on={() => setA({ ...a, ["rf" + i]: true })} active={a["rf" + i] === true}>RICHTIG (+)</Opt>
                  <Opt on={() => setA({ ...a, ["rf" + i]: false })} active={a["rf" + i] === false}>FALSCH (–)</Opt>
                </div>
              </div>
            ))}
            <div style={{ fontWeight: 700, color: C.muted, fontSize: 13, marginTop: 6 }}>Teil B — a / b</div>
            {(content.mc || []).map((it, i) => (
              <div key={"mc" + i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                <button onClick={() => speakDe(it.transcript)} style={{ background: C.gold, color: "#fff", border: "none", borderRadius: 9, padding: "6px 12px", fontWeight: 700, fontSize: 13, marginBottom: 8, display:"inline-flex", alignItems:"center", gap:5 }}><Volume2 size={13} /> {lang === "tr" ? "Dinle" : lang === "en" ? "Listen" : lang === "ar" ? "استمع" : lang === "es" ? "Escuchar" : lang === "uk" ? "Слухати" : lang === "fa" ? "گوش دادن" : lang === "fr" ? "Écoute." : "گوێ بگرە"}</button>
                <div dir="ltr" style={{ marginBottom: 10 }}><De size={15}>{it.q}</De></div>
                <div style={{ display: "grid", gap: 7 }}>{it.options.map((o, oi) => <Opt key={oi} on={() => setA({ ...a, ["mc" + i]: oi })} active={a["mc" + i] === oi}><span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}>{String.fromCharCode(97 + oi)}) {o}</span></Opt>)}</div>
              </div>
            ))}
          </>)}

          {!content.parts && sec.type === "antworten" && (<>
            <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
              <div style={{ fontWeight: 700, fontSize: 13, color: C.muted, marginBottom: 8 }}>{lang === "tr" ? "Hazır cevaplar:" : lang === "en" ? "Ready-made answers:" : lang === "ar" ? "إجابات جاهزة:" : lang === "es" ? "Respuestas listas:" : lang === "uk" ? "Готові відповіді:" : lang === "fa" ? "پاسخ‌های آماده:" : lang === "fr" ? "Réponses prêtes à être apportées :" : "وەڵامە ئامادەکان:"}</div>
              {content.responses.map((r, ri) => <div key={ri} dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 14, padding: "3px 0" }}>{String.fromCharCode(97 + ri)}) {r}</div>)}
            </div>
            {content.prompts.map((p, i) => (
              <div key={i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                <button onClick={() => speakDe(p)} style={{ background: C.gold, color: "#fff", border: "none", borderRadius: 9, padding: "6px 12px", fontWeight: 700, fontSize: 13, marginBottom: 8, display:"inline-flex", alignItems:"center", gap:5 }}><Volume2 size={13} /> {lang === "tr" ? `Dinle ${i + 1}` : lang === "en" ? `Listen ${i + 1}` : lang === "ar" ? `استمع ${i + 1}` : `گوێ بگرە ${i + 1}`}</button>
                <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>{content.responses.map((r, ri) => <Opt key={ri} on={() => setA({ ...a, [i]: ri })} active={a[i] === ri}><span dir="ltr">{String.fromCharCode(97 + ri)}</span></Opt>)}</div>
              </div>
            ))}
          </>)}

          {!content.parts && sec.type === "lesen" && (<>
            {content.teilA && (<>
              <div style={{ fontWeight: 700, color: C.muted, fontSize: 13 }}>Teil A — {lang === "tr" ? "Metin için başlık seç" : lang === "en" ? "Choose a title for the text" : lang === "ar" ? "اختر عنوانًا للنص" : lang === "es" ? "Elige un título para el texto" : lang === "uk" ? "Оберіть заголовок для тексту" : lang === "fa" ? "برای متن یک عنوان انتخاب کنید" : lang === "fr" ? "Choisissez un titre pour le texte" : "سەردێڕ بۆ دەق دیاری بکە"}</div>
              <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                {content.teilA.headings.map((h, hi) => <div key={hi} dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 14, padding: "3px 0" }}>{String.fromCharCode(97 + hi)}) {h}</div>)}
              </div>
              {content.teilA.texts.map((t, i) => (
                <div key={"A" + i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                  <div dir="ltr" style={{ marginBottom: 10, lineHeight: 1.8 }}><De size={14.5}>{t}</De></div>
                  <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>{content.teilA.headings.map((h, hi) => <Opt key={hi} on={() => setA({ ...a, ["A" + i]: hi })} active={a["A" + i] === hi}><span dir="ltr">{String.fromCharCode(97 + hi)}</span></Opt>)}</div>
                </div>
              ))}
            </>)}

            {content.teilB && (<>
              <div style={{ fontWeight: 700, color: C.muted, fontSize: 13, marginTop: 6 }}>Teil B — RICHTIG (+) / FALSCH (–)</div>
              <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="ltr"><De size={14.5}>{content.teilB.text}</De></div>
              {content.teilB.items.map((it, i) => (
                <div key={"B" + i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                  <div dir="ltr" style={{ marginBottom: 10 }}><De size={15}>{it.statement}</De></div>
                  <div style={{ display: "flex", gap: 8 }}>
                    <Opt on={() => setA({ ...a, ["B" + i]: true })} active={a["B" + i] === true}>RICHTIG (+)</Opt>
                    <Opt on={() => setA({ ...a, ["B" + i]: false })} active={a["B" + i] === false}>FALSCH (–)</Opt>
                  </div>
                </div>
              ))}
            </>)}

            {Array.isArray(content.teilC) && (<>
              <div style={{ fontWeight: 700, color: C.muted, fontSize: 13, marginTop: 6 }}>Teil C — {lang === "tr" ? "Hangi ilan uyuyor? (a / b)" : lang === "en" ? "Which ad fits? (a / b)" : lang === "ar" ? "أي إعلان يناسب؟ (a / b)" : lang === "es" ? "¿Qué anuncio encaja? (a / b)" : lang === "uk" ? "Яке оголошення підходить? (a / b)" : lang === "fa" ? "کدام آگهی مناسب است؟ (a / b)" : lang === "fr" ? "Quelle annonce convient? (a / b)" : "کام ڕیکلام دەگونجێت؟ (a / b)"}</div>
              {content.teilC.map((it, i) => (
                <div key={"C" + i} style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14 }}>
                  <div style={{ fontWeight: 600, marginBottom: 10 }} dir="auto">{it.situation}</div>
                  <div style={{ display: "grid", gap: 8 }}>
                    {["a", "b"].map((lbl, oi) => (
                      <button key={oi} onClick={() => setA({ ...a, ["C" + i]: oi })}
                        style={{ textAlign: "right", background: a["C" + i] === oi ? "#e3f0ef" : "#fff", border: `1.5px solid ${a["C" + i] === oi ? C.red : C.line}`, borderRadius: 10, padding: "10px 13px", fontSize: 14 }}>
                        <span dir="ltr" style={{ fontFamily: "'Satoshi',system-ui,sans-serif" }}><b>{lbl})</b> {it[lbl]}</span>
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </>)}
          </>)}

          {sec.type === "schreiben" && (<>
            {content.teilA ? (<>
              <div style={{ fontWeight: 700, color: C.muted, fontSize: 13 }}>Teil A — Formular</div>
              <div style={{ background: "#fff8ec", border: `1px solid ${C.gold}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="auto">{content.teilA.intro}</div>
              <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="ltr"><De size={14.5}>{content.teilA.person}</De></div>
              <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 12, padding: 16 }}>
                {content.teilA.fields.map((f, i) => (
                  <div key={i} dir="ltr" style={{ display: "flex", alignItems: "baseline", gap: 8, padding: "7px 0", fontFamily: "'Satoshi',system-ui,sans-serif", fontSize: 14.5 }}>
                    <span style={{ fontWeight: 700, color: C.red, minWidth: 26 }}>{f.n}</span>
                    <span style={{ minWidth: 120 }}>{f.label}:</span>
                    <span style={{ flex: 1, borderBottom: `1.5px dotted ${C.muted}` }}>&nbsp;</span>
                  </div>
                ))}
              </div>
              <div style={{ fontWeight: 700, color: C.muted, fontSize: 13, marginTop: 6 }}>Teil B — E-Mail</div>
              <div style={{ background: "#fff8ec", border: `1px solid ${C.gold}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="auto">{content.teilB.task}</div>
            </>) : (
              <div style={{ background: "#fff8ec", border: `1px solid ${C.gold}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="auto">{content.task}</div>
            )}
            <div style={{ background: "#eef6ef", border: `1px solid ${C.green}`, borderRadius: 12, padding: "14px 16px", textAlign: "center" }}>
              <div style={{ fontSize: 22 }}>✏️📓</div>
              <div style={{ fontWeight: 700, fontSize: 15.5, color: C.green, marginTop: 4 }}>{lang === "tr" ? "Şimdi defter ve kalem zamanı 😊" : lang === "en" ? "Now it's notebook and pen time 😊" : lang === "ar" ? "الآن حان وقت الدفتر والقلم 😊" : lang === "es" ? "Ahora es momento de cuaderno y bolígrafo 😊" : lang === "uk" ? "Тепер час зошита та ручки 😊" : lang === "fa" ? "حالا وقت دفتر و خودکار است 😊" : lang === "fr" ? "Maintenant c'est le temps du carnet et du stylo" : "ئێستا کاتی دەفتەر و پێنووسەیە 😊"}</div>
              <div style={{ fontSize: 13.5, color: C.muted, marginTop: 4, lineHeight: 1.8 }}>{lang === "tr" ? "Bu bölüm uygulamada değil — defterinize elle yazarak yazma pratiği yapın." : lang === "en" ? "This section isn't in the app — practice writing by hand in your notebook." : lang === "ar" ? "هذا القسم ليس في التطبيق — تدرّب على الكتابة بخط اليد في دفترك." : lang === "es" ? "Esta sección no está en la app — practica la escritura a mano en tu cuaderno." : lang === "uk" ? "Цього розділу немає в застосунку — тренуйтеся писати від руки в зошиті." : lang === "fa" ? "این بخش در برنامه نیست — نوشتن با دست را در دفترتان تمرین کنید." : lang === "fr" ? "Cette section n'est pas dans l'application — pratiquez l'écriture à la main dans votre carnet." : "ئەم بەشە لە ئەپدا مەنووسە — بە دەست لەسەر دەفتەرەکەت بنووسە بۆ مەشقی نووسین."}</div>
            </div>
          </>)}

          {sec.type === "muendlich" && (<>
            <div style={{ background: "#fff8ec", border: `1px solid ${C.gold}`, borderRadius: 12, padding: 16, lineHeight: 1.9 }} dir="auto">{content.task}</div>
            <div style={{ fontSize: 12.5, color: C.muted }}>ⓘ {lang === "tr" ? "Bu bölüm sözlü pratik içindir ve puanlara dahil edilmez — yüksek sesle konuşun." : lang === "en" ? "This section is for spoken practice and isn't scored — speak out loud." : lang === "ar" ? "هذا القسم للتدريب الشفهي ولا يُحتسب في الدرجات — تحدث بصوت عالٍ." : lang === "es" ? "Esta sección es para practicar el habla y no se puntúa — habla en voz alta." : lang === "uk" ? "Цей розділ для усної практики й не оцінюється — говоріть уголос." : lang === "fa" ? "این بخش برای تمرین شفاهی است و امتیازدهی نمی‌شود — بلند صحبت کنید." : lang === "fr" ? "Cette section est pour la pratique orale et n'est pas notée — parlez à haute voix." : "ئەم بەشە بۆ مەشقی زارەکییە و لە نمرە ناژمێردرێت — بە دەنگی بەرز قسەی بکە."}</div>
          </>)}
        </div>
      )}

      <div style={{ display: "flex", gap: 10, marginTop: 20 }}>
        {idx > 0 && <button onClick={() => openSection(idx - 1)} style={{ background: "transparent", color: C.muted, border: `1.5px solid ${C.line}`, padding: "12px 14px", borderRadius: 11, fontWeight: 700 }}>{lang === "tr" ? "→ Önceki" : lang === "en" ? "→ Previous" : lang === "ar" ? "→ السابق" : lang === "es" ? "→ Anterior" : lang === "uk" ? "→ Попередній" : lang === "fa" ? "→ قبلی" : lang === "fr" ? "→ Précédent" : "→ پێشوو"}</button>}
        {idx < SECS.length - 1 ? (
          <button onClick={() => openSection(idx + 1)} style={{ flex: 1, background: C.red, color: "#fff", border: "none", padding: 13, borderRadius: 11, fontWeight: 700, fontSize: 15 }}>{lang === "tr" ? "Sonraki bölüm ←" : lang === "en" ? "Next section ←" : lang === "ar" ? "القسم التالي ←" : lang === "es" ? "Siguiente sección ←" : lang === "uk" ? "Наступний розділ ←" : lang === "fa" ? "بخش بعدی ←" : lang === "fr" ? "Section suivante ←" : "بەشی دواتر ←"}</button>
        ) : (
          <button onClick={() => setPhase("overview")} style={{ flex: 1, background: C.green, color: "#fff", border: "none", padding: 13, borderRadius: 11, fontWeight: 700, fontSize: 15 }}>📋 {lang === "tr" ? "Genel Bakış ←" : lang === "en" ? "Overview ←" : lang === "ar" ? "نظرة عامة ←" : lang === "es" ? "Resumen ←" : lang === "uk" ? "Огляд ←" : lang === "fa" ? "نمای کلی ←" : lang === "fr" ? "Aperçu ←" : "پێداچوونەوە ←"}</button>
        )}
        <button onClick={onClose} style={{ background: "transparent", color: C.redDk, border: `1.5px solid ${C.line}`, padding: "13px 16px", borderRadius: 11, fontWeight: 700 }}>{lang === "tr" ? "Kapat" : lang === "en" ? "Close" : lang === "ar" ? "إغلاق" : lang === "es" ? "Cerrar" : lang === "uk" ? "Закрити" : lang === "fa" ? "بستن" : lang === "fr" ? "Fermer" : "داخستن"}</button>
      </div>
    </div>
  );
}

function ExpRenderer({ text, color = "#5B5BD6" }) {
  if (!text) return null;

  // pronoun → display label + color
  const PC = {
    "ich": "#5B5BD6", "du": "#F5A524",
    "er": "#16A06F",  "er/sie/es": "#16A06F", "er/sie": "#16A06F",
    "wir": "#FF6B5E", "ihr": "#7C3AED",
    "sie": "#0F766E", "Sie": "#0F766E", "sie/Sie": "#0F766E",
    "man": "#94A3B8",
  };
  // display label remapping (combine er/sie/es → er/sie/es shown)
  const PL = { "er": "er/sie/es", "sie": "sie/Sie" };
  const PRONOUNS = Object.keys(PC);

  // highlight «German» words in plain text
  const hilite = (str) => {
    const parts = str.split(/«([^»]+)»/);
    return parts.map((p, i) => i % 2 === 0
      ? <span key={i}>{p}</span>
      : <span key={i} style={{ background:`${color}18`, color, fontWeight:700, borderRadius:6, padding:"1px 6px" }}>{p}</span>
    );
  };

  // split text into logical segments at ". " boundaries
  const segments = text
    .replace(/\.\s+/g, ".\n")
    .replace(/\.\s*$/, "")
    .split("\n")
    .map(s => s.trim())
    .filter(Boolean);

  function renderSeg(seg, si) {
    // ── 1. Example block ──────────────────────────────────────────
    if (seg.startsWith("نموونە:")) {
      const content = seg.slice(seg.indexOf(":") + 1).trim();
      const parts = content.includes("→") ? content.split("→").map(s => s.trim()) : [content];
      return (
        <div key={si} style={{ background:`${color}07`, border:`1.5px solid ${color}20`, borderRadius:16, padding:"13px 16px" }}>
          <div style={{ fontSize:10, fontWeight:800, color, letterSpacing:".06em", marginBottom:10, opacity:.75 }}>نموونە</div>
          <div style={{ display:"flex", alignItems:"center", flexWrap:"wrap", gap:10 }}>
            {parts.map((p, pi) => (
              <span key={pi} style={{ display:"flex", alignItems:"center", gap:10 }}>
                {pi > 0 && <span style={{ color, fontWeight:900, fontSize:18, lineHeight:1 }}>→</span>}
                <code dir="ltr" style={{ fontSize:14, fontWeight:700, color:"#1A1F2E", background:`${color}12`, borderRadius:8, padding:"4px 10px", fontFamily:"'Satoshi',system-ui,sans-serif" }}>{p}</code>
              </span>
            ))}
          </div>
        </div>
      );
    }

    // ── 2. ،-separated list? ──────────────────────────────────────
    if (seg.includes("،")) {
      // find label vs list: split at LAST colon where part-after has ،
      let label = "", listPart = seg;
      const colonIdx = seg.lastIndexOf(":");
      if (colonIdx > 0) {
        const after = seg.slice(colonIdx + 1).trim();
        const before = seg.slice(0, colonIdx);
        if (after.includes("،")) { label = before.trim(); listPart = after; }
      }
      const items = listPart.split("،").map(s => s.trim().replace(/\.$/,"")).filter(Boolean);

      // check CONJUGATION: ≥3 items whose first word is a pronoun (and form has no parens)
      const conjItems = items.map(item => {
        const sp = item.indexOf(" ");
        if (sp < 1) return null;
        const word = item.slice(0, sp).replace(/[،.]/g,"");
        const form = item.slice(sp + 1).replace(/[،.]/g,"").trim();
        if (PRONOUNS.includes(word) && !form.startsWith("(")) {
          return { pronoun: word, label: PL[word] || word, form, color: PC[word] };
        }
        return null;
      }).filter(Boolean);

      if (conjItems.length >= 3) {
        return (
          <div key={si}>
            {label && (
              <div style={{ fontSize:12, fontWeight:700, color, marginBottom:9, letterSpacing:".03em", opacity:.85 }}>
                {label}
              </div>
            )}
            <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:7 }}>
              {conjItems.map(({ pronoun, label: pl, form, color: pc }) => (
                <div key={pronoun} style={{ background:`${pc}10`, border:`1.5px solid ${pc}28`, borderRadius:12, padding:"10px 6px", textAlign:"center" }}>
                  <div style={{ fontSize:10, fontWeight:800, color:pc, marginBottom:5, letterSpacing:".02em" }}>{pl}</div>
                  <div dir="ltr" style={{ fontSize:14, fontWeight:800, color:"#1A1F2E", fontFamily:"'Satoshi',system-ui,sans-serif" }}>{form}</div>
                </div>
              ))}
            </div>
          </div>
        );
      }

      // check WORD-TRANSLATION: ≥2 items with (meaning) format
      const wordItems = items.map(item => {
        const po = item.indexOf("("), pc2 = item.lastIndexOf(")");
        if (po > 0 && pc2 > po) {
          return { word: item.slice(0, po).trim(), meaning: item.slice(po + 1, pc2).trim() };
        }
        return { word: item.replace(/[،.]/g,""), meaning: null };
      });
      const meanCount = wordItems.filter(w => w.meaning).length;
      if (meanCount >= 2 && meanCount >= Math.ceil(items.length / 2)) {
        return (
          <div key={si}>
            {label && (
              <div style={{ fontSize:13, color:"#71717A", fontWeight:600, marginBottom:9, lineHeight:1.6 }}>
                {hilite(label)}
              </div>
            )}
            <div style={{ display:"flex", flexWrap:"wrap", gap:7 }}>
              {wordItems.map(({ word, meaning }, wi) => (
                <div key={wi} style={{ background:`${color}09`, border:`1.5px solid ${color}22`, borderRadius:10, padding:"6px 12px", display:"flex", alignItems:"baseline", gap:6 }}>
                  <span dir="ltr" style={{ fontWeight:800, color, fontSize:13.5, fontFamily:"'Satoshi',system-ui,sans-serif" }}>{word}</span>
                  {meaning && <span style={{ fontSize:11.5, color:"#71717A", fontWeight:600 }}>{meaning}</span>}
                </div>
              ))}
            </div>
          </div>
        );
      }
    }

    // ── 3. Inline → arrow ─────────────────────────────────────────
    if (seg.includes("→")) {
      const parts = seg.split("→").map(s => s.trim());
      return (
        <div key={si} style={{ display:"flex", alignItems:"center", flexWrap:"wrap", gap:8, background:`${color}07`, border:`1px solid ${color}18`, borderRadius:13, padding:"10px 14px" }}>
          {parts.map((p, pi) => (
            <span key={pi} style={{ display:"flex", alignItems:"center", gap:8 }}>
              {pi > 0 && <span style={{ color, fontWeight:900, fontSize:17, lineHeight:1 }}>→</span>}
              <span dir="ltr" style={{ fontSize:14, fontWeight:700, color:"#1A1F2E", fontFamily:"'Satoshi',system-ui,sans-serif" }}>{p}</span>
            </span>
          ))}
        </div>
      );
    }

    // ── 4. Plain text (with «» highlights) ───────────────────────
    return (
      <p key={si} style={{ fontSize:14.5, lineHeight:1.95, color:"#2A3040", margin:0 }}>
        {hilite(seg)}
      </p>
    );
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:13 }}>
      {segments.map(renderSeg)}
    </div>
  );
}

// ── "W" icon for the words tab ─────────────────────────────────────
function WIcon({ size = 24, color = "currentColor" }) {
  return (
    <span style={{ fontSize: Math.round(size * 0.82), fontWeight: 900, color,
      lineHeight: 1, fontFamily: "'Satoshi',system-ui,sans-serif",
      letterSpacing: "-.04em", display: "inline-block" }}>W</span>
  );
}

// ── WheelPicker label helper (module-scope) ─────────────────────────
function WPLabel({ icon: Icon, label, color }) {
  const clr = color || C.muted;
  return (
    <div style={{ display:"flex", alignItems:"center", gap:7, marginBottom:10, marginTop:2 }}>
      <div style={{ width:24, height:24, borderRadius:6, background:`${clr}18`, display:"grid", placeItems:"center" }}>
        <Icon size={12} color={clr} />
      </div>
      <span style={{ fontSize:12, fontWeight:700, color:clr, letterSpacing:".03em" }}>{label}</span>
    </div>
  );
}

// ── iPhone-style physics wheel picker ──────────────────────────────
const WP_IH  = 68;   // item height px
const WP_VIS = 282;  // viewport height px

function WheelPicker({ items, selIdx, onSelect, renderCard, accent = "#5B5BD6", getItemColor, getProgress }) {
  const CY  = Math.floor(WP_VIS / 2 - WP_IH / 2);
  const MAX = Math.max(0, (items.length - 1) * WP_IH);

  const offRef    = useRef(selIdx * WP_IH);
  const [off, setOff] = useState(selIdx * WP_IH);
  const isDragRef = useRef(false);
  const [isDrag,  setIsDrag] = useState(false);
  const lyRef     = useRef(0);
  const ltRef     = useRef(0);
  const velRef    = useRef(0);
  const totalMvRef = useRef(0);
  const prevIdxRef = useRef(selIdx);
  const rafRef    = useRef(null);
  const snapRef   = useRef(null);
  const audRef    = useRef(null);
  const containerRef  = useRef(null);
  const applyRef      = useRef(null);  // always-current function refs for wheel handler
  const stopRAFRef    = useRef(null);
  const wheelTimerRef = useRef(null);

  function tick() {
    try {
      if (!audRef.current) audRef.current = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = audRef.current;
      if (ctx.state === "suspended") ctx.resume();
      const osc = ctx.createOscillator(), gn = ctx.createGain();
      osc.connect(gn); gn.connect(ctx.destination);
      osc.type = "sine"; osc.frequency.value = 1050;
      gn.gain.setValueAtTime(0.055, ctx.currentTime);
      gn.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.042);
      osc.start(); osc.stop(ctx.currentTime + 0.042);
    } catch { /* Video frame rendering is best-effort. */ }
  }
  function haptic() { try { navigator.vibrate?.(6); } catch { /* Video frame rendering is best-effort. */ } }

  function stopRAF() {
    if (rafRef.current) { cancelAnimationFrame(rafRef.current); rafRef.current = null; }
  }

  function apply(v) {
    const c = Math.max(0, Math.min(MAX, v));
    offRef.current = c;
    setOff(c);
    const idx = Math.max(0, Math.min(items.length - 1, Math.round(c / WP_IH)));
    if (idx !== prevIdxRef.current) {
      prevIdxRef.current = idx;
      onSelect(idx);
      tick(); haptic();
    }
  }

  function snapToIdx(idx) {
    stopRAF();
    const target = Math.max(0, Math.min(MAX, idx * WP_IH));
    const from   = offRef.current;
    const t0     = performance.now();
    function frame(now) {
      const t = Math.min((now - t0) / 390, 1);
      const e = 1 - Math.pow(1 - t, 3.5);
      apply(from + (target - from) * e);
      if (t < 1) rafRef.current = requestAnimationFrame(frame);
    }
    rafRef.current = requestAnimationFrame(frame);
  }
  useEffect(() => {
    snapRef.current = snapToIdx;
    applyRef.current = apply;
    stopRAFRef.current = stopRAF;
  });

  function momentumFlick() {
    stopRAF();
    function frame() {
      velRef.current *= 0.876;
      apply(offRef.current + velRef.current);
      if (Math.abs(velRef.current) > 0.6) rafRef.current = requestAnimationFrame(frame);
      else snapToIdx(Math.round(offRef.current / WP_IH));
    }
    rafRef.current = requestAnimationFrame(frame);
  }

  function onPD(e) {
    stopRAF();
    isDragRef.current = true; setIsDrag(true);
    lyRef.current = e.clientY; ltRef.current = performance.now();
    velRef.current = 0; totalMvRef.current = 0;
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* Video frame rendering is best-effort. */ }
  }
  function onPM(e) {
    if (!isDragRef.current) return;
    const now = performance.now(), dy = e.clientY - lyRef.current, dt = Math.max(1, now - ltRef.current);
    velRef.current = (-dy / dt) * 16;
    totalMvRef.current += Math.abs(dy);
    apply(offRef.current - dy);
    lyRef.current = e.clientY; ltRef.current = now;
  }
  function onPU() {
    if (!isDragRef.current) return;
    isDragRef.current = false; setIsDrag(false);
    if (Math.abs(velRef.current) > 1.5) momentumFlick();
    else snapToIdx(Math.round(offRef.current / WP_IH));
  }

  // non-passive wheel listener (prevents page scroll inside picker)
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    function onWheel(e) {
      e.preventDefault();
      e.stopPropagation();
      stopRAFRef.current?.();
      // deltaMode 0 = px, 1 = lines, 2 = pages
      const scale = e.deltaMode === 1 ? WP_IH : e.deltaMode === 2 ? WP_VIS : 0.55;
      applyRef.current?.(offRef.current + e.deltaY * scale);
      if (wheelTimerRef.current) clearTimeout(wheelTimerRef.current);
      wheelTimerRef.current = setTimeout(() => {
        snapRef.current?.(Math.round(offRef.current / WP_IH));
      }, 90);
    }
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("wheel", onWheel);
      if (wheelTimerRef.current) clearTimeout(wheelTimerRef.current);
    };
  }, []);

  // sync external selIdx (level/mode reset fires this)
  useEffect(() => {
    if (!isDragRef.current) snapRef.current?.(selIdx);
  }, [selIdx]);

  const curIdx = Math.max(0, Math.min(items.length - 1, Math.round(off / WP_IH)));
  const iColors = items.length
    ? items.map((item, i) => getItemColor ? getItemColor(item, i) : accent)
    : [accent];
  const tlGrad = iColors.length < 2
    ? `linear-gradient(to bottom,${iColors[0]}99,${iColors[0]})`
    : `linear-gradient(to bottom,${iColors.map((c, i) => `${c} ${Math.round(i / (iColors.length - 1) * 100)}%`).join(',')})`;
  const selColor = iColors[curIdx] || accent;

  return (
    <>
      <style>{`
        @keyframes wpEnergyFlow {
          0%   { background-position: 0% 0%;   }
          100% { background-position: 0% 300%; }
        }
      `}</style>
      <div ref={containerRef} dir="ltr"
        style={{ position:"relative", height:WP_VIS, overflow:"hidden",
          userSelect:"none", touchAction:"none",
          background:"linear-gradient(180deg,#F8FAFC 0%,#F1F5F9 100%)",
          cursor: isDrag ? "grabbing" : "grab",
          perspective:"700px", perspectiveOrigin:"50% 50%" }}
        onPointerDown={onPD} onPointerMove={onPM}
        onPointerUp={onPU} onPointerLeave={onPU} onPointerCancel={onPU}>

        {/* gradient timeline bar */}
        <div style={{ position:"absolute", left:18, top:0, bottom:0, width:2,
          background:tlGrad, pointerEvents:"none", zIndex:1 }} />

        {/* section number watermark behind active card */}
        <div style={{ position:"absolute", right:14, top:CY-4, height:WP_IH+8,
          display:"flex", alignItems:"center",
          fontSize:68, fontWeight:900, color:selColor, opacity:.042,
          fontFamily:"'Satoshi',system-ui,sans-serif", letterSpacing:"-.04em",
          lineHeight:1, pointerEvents:"none", zIndex:3, userSelect:"none" }}>
          {String(curIdx+1).padStart(2,"0")}
        </div>

        {/* ambient glow radiating from active card */}
        <div style={{ position:"absolute", left:16, right:16,
          top:CY-8, height:WP_IH+16, borderRadius:24,
          background:`radial-gradient(ellipse 90% 70% at 50% 50%,${selColor}1C,transparent 72%)`,
          pointerEvents:"none", zIndex:4 }} />

        {/* glassmorphism focus zone */}
        <div style={{ position:"absolute", top:CY-5, left:4, right:4, height:WP_IH+10,
          background:"rgba(255,255,255,0.60)",
          backdropFilter:"blur(10px) saturate(180%)",
          WebkitBackdropFilter:"blur(10px) saturate(180%)",
          borderRadius:18,
          border:"1px solid rgba(255,255,255,0.88)",
          boxShadow:"0 8px 32px rgba(0,0,0,.07),inset 0 1px 0 rgba(255,255,255,.95)",
          pointerEvents:"none", zIndex:5 }} />

        {/* animated energy line */}
        <div style={{ position:"absolute", left:5, top:CY+6,
          width:3, height:WP_IH-12, borderRadius:99,
          background:"linear-gradient(to bottom,#38BDF8,#8B5CF6,#06B6D4)",
          backgroundSize:"100% 300%",
          animation:"wpEnergyFlow 2s linear infinite",
          pointerEvents:"none", zIndex:8, opacity:.92 }} />

        {/* top/bottom vignette fade */}
        <div style={{ position:"absolute", inset:0, pointerEvents:"none", zIndex:6,
          background:"linear-gradient(to bottom,#F8FAFC 0%,transparent 22%,transparent 78%,#F1F5F9 100%)" }} />

        {/* items — 3-D cylinder physics */}
        {items.map((item, i) => {
          const y          = CY + i * WP_IH - off;
          if (y < -WP_IH * 2.5 || y > WP_VIS + WP_IH * 1.5) return null;
          const signedDist = (y - CY) / WP_IH;
          const theta      = signedDist * 22;                    // ° per item step on cylinder
          const cosT       = Math.cos(theta * Math.PI / 180);
          const scale      = Math.max(0.46, cosT);
          const opa        = Math.max(0.05, Math.pow(Math.max(0, cosT), 1.8));
          const isSel      = i === curIdx;
          const ic         = getItemColor ? getItemColor(item, i) : accent;
          const pct        = getProgress  ? Math.min(100, Math.max(0, getProgress(item, i))) : 0;
          const rR = 8, rCirc = 2 * Math.PI * rR;
          return (
            <div key={i}
              style={{ position:"absolute", left:8, right:8, top:y,
                height:WP_IH-8, zIndex: isSel ? 7 : 3,
                opacity:opa,
                transform:`rotateX(${theta}deg) scale(${scale})`,
                transformOrigin:"center center",
                willChange:"transform,opacity",
                transition: isDrag ? "none" : "transform .14s cubic-bezier(.25,.46,.45,.94),opacity .14s ease",
                cursor: isSel ? "default" : "pointer" }}
              onClick={() => { if (totalMvRef.current < 8) { haptic(); snapToIdx(i); } }}>
              {renderCard(item, i, isSel)}
              {/* circular progress ring overlaid on the circle node */}
              {pct > 0 && (
                <svg width={22} height={22} viewBox="0 0 22 22"
                  style={{ position:"absolute", left:0, top:"50%",
                    transform:"translateY(-50%)", pointerEvents:"none", zIndex:10 }}>
                  <circle cx={11} cy={11} r={rR} fill="none"
                    stroke={`${ic}30`} strokeWidth={2.2} />
                  <circle cx={11} cy={11} r={rR} fill="none"
                    stroke={ic} strokeWidth={2.2}
                    strokeDasharray={`${rCirc*pct/100} ${rCirc*(1-pct/100)}`}
                    strokeLinecap="round"
                    transform="rotate(-90 11 11)" />
                </svg>
              )}
            </div>
          );
        })}
      </div>
    </>
  );
}

// ── Übung section metadata (used by WheelPicker in ubung mode) ──────
const UBUNG_SECTIONS = [
  { id:"drag",      label:"Sprachbausteine", sub:"پڕکردنەوەی بۆشایی",    subTr:"Boşluk doldurma",    subUk:"Заповнення пропусків", subFa:"پر کردن جای خالی",   emoji:"🧩", color:"#5B5BD6" ,"subFr":"Remplir l'espace"},
  { id:"lesenA",    label:"Lesen A",          sub:"سەردێڕ دیاری بکە",    subTr:"Başlık seç",          subUk:"Оберіть заголовок", subFa:"انتخاب عنوان",       emoji:"📰", color:"#059669" ,"subFr":"Sélectionner le titre"},
  { id:"lesenB",    label:"Lesen B",          sub:"ڕاست یان هەڵە",       subTr:"Doğru ya da yanlış",  subUk:"Правда чи хиба", subFa:"درست یا نادرست",          emoji:"📖", color:"#0891B2" ,"subFr":"Droit ou mal"},
  { id:"lesenC",    label:"Lesen C",          sub:"دەق و پرسیار",        subTr:"Metin ve sorular",    subUk:"Текст і питання", subFa:"متن و پرسش",         emoji:"📚", color:"#7C3AED" ,"subFr":"Texte et questions"},
  { id:"schreibA",  label:"Schreiben A",      sub:"نووسینی فۆرم",        subTr:"Form doldurma",       subUk:"Заповнення форми", subFa:"پر کردن فرم",        emoji:"✍️", color:"#B45309" ,"subFr":"Remplissez le formulaire"},
  { id:"schreibB",  label:"Schreiben B",      sub:"نووسینی ئازاد",       subTr:"Serbest yazma",       subUk:"Вільне письмо", subFa:"نوشتن آزاد",           emoji:"📝", color:"#BE185D" ,"subFr":"L'écriture gratuite"},
  { id:"mundlichA", label:"Mündlich A",       sub:"ئامادەکاری قسەکردن",  subTr:"Konuşma hazırlığı",  subUk:"Підготовка до мовлення", subFa:"آمادگی برای صحبت",  emoji:"🗣️", color:"#0F766E" ,"subFr":"Préparation des discours"},
  { id:"mundlichB", label:"Mündlich B",       sub:"ئامادەکاری قسەکردن",  subTr:"Konuşma hazırlığı",  subUk:"Підготовка до мовлення", subFa:"آمادگی برای صحبت",  emoji:"💬", color:"#1D4ED8" ,"subFr":"Préparation des discours"},
];

// ── Collapsing Picker Header ─────────────────────────────────────────
// Wraps any WheelPicker in a sticky container that collapses to a
// compact glassmorphism bar as the user scrolls into the content area.
const CPH_COMPACT = 58;    // px — height when fully collapsed
const CPH_RANGE   = 110;   // px of page-scroll that drives full→compact

function CollapsingPickerHeader({ children, compact, accent = "#5B5BD6" }) {
  const outerRef      = useRef(null);
  const pickerRef     = useRef(null);
  const compactRef    = useRef(null);
  const rafRef        = useRef(null);
  const expandRafRef  = useRef(null);
  const baseScrollRef = useRef(0);   // scrollY at the time picker was last expanded

  function applyP(p) {
    if (!outerRef.current) return;
    const h = WP_VIS + (CPH_COMPACT - WP_VIS) * p;
    outerRef.current.style.height = `${h}px`;
    if (pickerRef.current) {
      pickerRef.current.style.transform = `translateY(-${(WP_VIS - CPH_COMPACT) * p}px)`;
      pickerRef.current.style.opacity   = String(Math.max(0, 1 - p * 1.5));
    }
    if (compactRef.current) {
      const cp = Math.max(0, (p - 0.48) / 0.52);
      compactRef.current.style.opacity       = String(cp);
      compactRef.current.style.pointerEvents = cp > 0.8 ? "auto" : "none";
      compactRef.current.style.transform     = `translateY(${(1 - cp) * 12}px)`;
    }
  }

  /* Expand picker in-place — no page scroll. Sets baseScroll so the
     scroll-driven collapse starts from the current position.          */
  function expandInPlace() {
    baseScrollRef.current = window.scrollY;
    if (expandRafRef.current) cancelAnimationFrame(expandRafRef.current);
    const startH  = parseFloat(outerRef.current?.style.height) || CPH_COMPACT;
    const startT  = performance.now();
    function frame(now) {
      const t    = Math.min(1, (now - startT) / 300);
      const ease = 1 - Math.pow(1 - t, 3);            // ease-out cubic
      const h    = startH + (WP_VIS - startH) * ease;
      const p    = Math.max(0, 1 - (h - CPH_COMPACT) / (WP_VIS - CPH_COMPACT));
      applyP(p);
      if (t < 1) expandRafRef.current = requestAnimationFrame(frame);
      else       expandRafRef.current = null;
    }
    expandRafRef.current = requestAnimationFrame(frame);
  }

  useEffect(() => {
    baseScrollRef.current = 0;
    applyP(0);
    function onScroll() {
      if (expandRafRef.current) return;   // don't interrupt manual expand
      if (rafRef.current) return;
      rafRef.current = requestAnimationFrame(() => {
        // p is relative to baseScroll: expanding resets the collapse origin
        const p = Math.max(0, Math.min(1,
          (window.scrollY - baseScrollRef.current) / CPH_RANGE));
        applyP(p);
        rafRef.current = null;
      });
    }
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (rafRef.current)     { cancelAnimationFrame(rafRef.current);     rafRef.current     = null; }
      if (expandRafRef.current) { cancelAnimationFrame(expandRafRef.current); expandRafRef.current = null; }
    };
  }, []);

  return (
    <div ref={outerRef}
      style={{ position:"sticky", top:0, zIndex:10,
        height: WP_VIS, overflow:"hidden",
        background:"#fff", borderRadius:18,
        border:"1.5px solid #E4E6EE",
        boxShadow:"0 4px 24px rgba(0,0,0,.11)",
        marginBottom:16 }}>

      {/* WheelPicker — slides up as page scrolls */}
      <div ref={pickerRef} style={{ position:"absolute", inset:0 }}>
        {children}
      </div>

      {/* Compact glassmorphism bar — fades in as picker collapses */}
      <div ref={compactRef}
        style={{ position:"absolute", top:0, left:0, right:0, height:CPH_COMPACT,
          zIndex:30, opacity:0, pointerEvents:"none",
          display:"flex", alignItems:"center",
          background:"rgba(255,255,255,0.84)",
          backdropFilter:"blur(20px) saturate(200%)",
          WebkitBackdropFilter:"blur(20px) saturate(200%)",
          boxShadow:`inset 0 -1px 0 ${accent}22, 0 2px 16px rgba(0,0,0,.06)`,
          cursor:"pointer", padding:"0 14px", gap:10,
          transform:"translateY(12px)" }}
        onClick={expandInPlace}>
        {compact}
        <svg width={18} height={18} viewBox="0 0 18 18" fill="none"
          style={{ flexShrink:0, marginLeft:"auto", opacity:.45 }}>
          <path d="M4.5 7L9 11.5L13.5 7" stroke={accent} strokeWidth={2.2}
            strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </div>
    </div>
  );
}

// ── Grammar content (used inline below the picker) ──────────────────
function GrammarContent({ g, level, progress, mkBatch, lang = "ku" }) {
  if (!g) return null;
  const lc     = levelColor(level);
  const gt     = GTABLES[g.de];
  const gtHeaders = gt ? (lang === "tr" ? (gt.headersTr || gt.headers) : lang === "en" ? (gt.headersEn || gt.headers) : lang === "ar" ? (gt.headersAr || gt.headers) : lang === "uk" ? (gt.headersUk || gt.headers) : lang === "fa" ? (gt.headersFa || gt.headers) : lang === "es" ? (gt.headersEs || gt.headersEn || gt.headers) : gt.headers) : null;
  const gtRows    = gt ? (lang === "tr" ? (gt.rowsTr || gt.rows) : lang === "en" ? (gt.rowsEn || gt.rows) : lang === "ar" ? (gt.rowsAr || gt.rows) : lang === "uk" ? (gt.rowsUk || gt.rows) : lang === "fa" ? (gt.rowsFa || gt.rows) : lang === "es" ? (gt.rowsEs || gt.rowsEn || gt.rows) : gt.rows) : null;
  const gtLtr  = lang === "tr" || lang === "en" || (!!gt && (gt.headers[0] === "کەس" || gt.headers[0] === "ئەڵمانی"));
  const exList = (lang !== "ku" && g.ex?.length) ? g.ex : (GEXAMPLES[g.de] || g.ex || []);
  return (
    <div key={g.de} style={{ display:"flex", flexDirection:"column", gap:13, paddingTop:14 }}>
      {/* hero */}
      <div className="rise" style={{ animationDelay:"0ms", background:`linear-gradient(145deg,${lc},${lc}CC)`, borderRadius:20, padding:"18px 18px 16px", color:"#fff", boxShadow:`0 3px 0 rgba(0,0,0,.11),0 10px 26px ${lc}44`, position:"relative", overflow:"hidden" }}>
        <div style={{ position:"absolute", top:-25, left:-25, width:100, height:100, borderRadius:"50%", background:"rgba(255,255,255,.08)", pointerEvents:"none" }} />
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <div style={{ width:44, height:44, borderRadius:13, background:"rgba(255,255,255,.2)", display:"grid", placeItems:"center", fontSize:22, flexShrink:0, boxShadow:"0 2px 0 rgba(0,0,0,.1)" }}>{g.icon}</div>
          <div>
            <h3 style={{ fontWeight:800, fontSize:20, margin:0, letterSpacing:"-.02em" }}>{tC(g, lang)}</h3>
            <div dir="ltr" style={{ fontSize:13, opacity:.85, marginTop:2, fontFamily:"'Satoshi',system-ui,sans-serif" }}>{g.de}</div>
          </div>
        </div>
      </div>
      {/* explanation */}
      <div className="rise" style={{ animationDelay:"30ms", background:"#fff", border:`1.5px solid ${lc}22`, borderRadius:16, padding:"14px 16px", boxShadow:`0 2px 0 rgba(0,0,0,.06),0 5px 16px ${lc}0E` }}>
        <WPLabel icon={AlertCircle} label={tApp(lang,"gc_explain")} color={lc} />
        <ExpRenderer text={lang === "tr" ? (g.expTr || g.exp) : lang === "en" ? (g.expEn || g.exp) : lang === "ar" ? (g.expAr || g.exp) : lang === "uk" ? (g.expUk || g.exp) : lang === "fa" ? (g.expFa || g.exp) : lang === "es" ? (g.expEs || g.expEn || g.exp) : g.exp} color={lc} />
      </div>
      {/* table */}
      {gt && (
        <div className="rise" style={{ animationDelay:"60ms" }}>
          <WPLabel icon={SlidersHorizontal} label={tApp(lang,"gc_table")} color="#7B6BB5" />
          <div style={{ overflowX:"auto", border:"1.5px solid #7B6BB51A", borderRadius:14, boxShadow:"0 2px 0 rgba(0,0,0,.05),0 5px 16px rgba(123,107,181,.07)" }}>
            <table dir={gtLtr?"ltr":"rtl"} style={{ width:"100%", borderCollapse:"collapse", fontSize:14 }}>
              <thead><tr style={{ background:"#7B6BB5" }}>
                {gtHeaders.map((h,hi) => <th key={hi} style={{ color:"#fff",fontWeight:700,padding:"10px 12px",textAlign:gtLtr?"left":"right",whiteSpace:"nowrap" }}><span dir="auto">{h}</span></th>)}
              </tr></thead>
              <tbody>{gtRows.map((row,ri) => (
                <tr key={ri} style={{ background:ri%2?"#F6F4FB":"#fff" }}>
                  {row.map((cell,ci) => (
                    <td key={ci} style={{ padding:"9px 12px",borderTop:"1px solid #EDE8F5",textAlign:gtLtr?"left":"right",color:ci===0?"#1A1F2E":"#7B6BB5",fontWeight:ci===0?700:500 }}>
                      <span dir="auto" style={{ fontFamily:/[A-Za-zÄÖÜäöüß]/.test(cell)?"'Satoshi',system-ui,sans-serif":"inherit" }}>{cell}</span>
                    </td>
                  ))}
                </tr>
              ))}</tbody>
            </table>
          </div>
        </div>
      )}
      {/* article groups */}
      {g.groups && g.groups.map((grp,gi) => (
        <div key={grp.art} className="rise" style={{ animationDelay:`${70+gi*35}ms`, background:"#fff", border:`1.5px solid ${grp.color}22`, borderRadius:16, overflow:"hidden", boxShadow:`0 2px 0 rgba(0,0,0,.06),0 5px 18px ${grp.color}10` }}>
          <div style={{ background:grp.color, padding:"11px 14px", display:"flex", alignItems:"center", gap:9 }}>
            <div style={{ width:34,height:34,borderRadius:10,background:"rgba(255,255,255,.2)",display:"grid",placeItems:"center",fontSize:18,flexShrink:0 }}>{grp.emoji}</div>
            <div>
              <span dir="ltr" style={{ fontFamily:"'Satoshi',system-ui,sans-serif",fontSize:20,fontWeight:800,color:"#fff" }}>{grp.art}</span>
              <span style={{ fontSize:12,fontWeight:600,color:"rgba(255,255,255,.85)",marginInlineStart:7 }}>— {grp[lang] || grp.ku}</span>
            </div>
          </div>
          <div style={{ padding:"12px 14px" }}>
            <WPLabel icon={Pin} label={tApp(lang,"gc_rules")} color={grp.color} />
            <ul style={{ margin:"0 0 12px",paddingInlineStart:18,fontSize:14,lineHeight:1.9,color:"#2A3040" }}>
              {(grp['rules' + lang.charAt(0).toUpperCase() + lang.slice(1)] || grp.rules).map((r,ri) => <li key={ri}>{r}</li>)}
            </ul>
            <WPLabel icon={FileText} label={tApp(lang,"gc_examples")} color={grp.color} />
            <div style={{ display:"flex",flexWrap:"wrap",gap:7 }}>
              {grp.words.map((w,wi) => (
                <span key={wi} style={{ display:"inline-flex",flexDirection:"column",gap:3,background:`${grp.color}0D`,border:`1.5px solid ${grp.color}22`,borderRadius:11,padding:"7px 11px",minWidth:86 }}>
                  <span style={{ display:"flex",alignItems:"center",gap:3 }}><De size={14} color="#1A1F2E">{w[0]}</De><Speak text={w[0]} size={13} /></span>
                  <span style={{ fontSize:12,color:grp.color,fontWeight:700 }}>{({tr:w[2],en:w[3],ar:w[4],uk:w[5],fa:w[6],es:w[7],fr:w[8]}[lang]) || w[1]}</span>
                </span>
              ))}
            </div>
          </div>
        </div>
      ))}
      {/* merksatz */}
      {g.merksatz && (
        <div className="rise" style={{ animationDelay:"100ms", background:`linear-gradient(145deg,${lc},${lc}DD)`, borderRadius:16, padding:"14px 16px", boxShadow:`0 3px 0 rgba(0,0,0,.1),0 8px 24px ${lc}40` }}>
          <div style={{ display:"flex",alignItems:"center",gap:6,marginBottom:10 }}>
            <div style={{ width:26,height:26,borderRadius:7,background:"rgba(255,255,255,.2)",display:"grid",placeItems:"center" }}><Zap size={13} color="#fff" /></div>
            <span style={{ fontSize:12.5,fontWeight:800,color:"#fff",letterSpacing:".03em" }}>{lang === "tr" ? "Hatırlatma Cümlesi (Merksatz)" : lang === "en" ? "Memory Sentence (Merksatz)" : lang === "ar" ? "جملة تذكيرية (Merksatz)" : lang === "es" ? "Frase para recordar (Merksatz)" : lang === "uk" ? "Речення для запам'ятовування (Merksatz)" : lang === "fa" ? "جمله برای به خاطر سپردن (Merksatz)" : lang === "fr" ? "Condamnation à la mémoire (Merksatz)" : "ڕستەی بیرهێنانەوە (Merksatz)"}</span>
          </div>
          <div style={{ display:"flex",flexWrap:"wrap",gap:10 }}>
            {g.merksatz.map((m,mi) => (
              <div key={mi} style={{ background:"rgba(255,255,255,.18)",borderRadius:11,padding:"7px 12px",display:"flex",alignItems:"center",gap:7 }}>
                <span dir="ltr" style={{ fontFamily:"'Satoshi',system-ui,sans-serif",fontSize:16,fontWeight:800,color:"#fff" }}>{m.de}</span>
                <span style={{ fontSize:12.5,color:"rgba(255,255,255,.85)" }}>= {tC(m, lang)}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      {/* examples */}
      <div className="rise" style={{ animationDelay:"128ms" }}>
        <WPLabel icon={BookOpen} label={`${tApp(lang,"gc_examples")} / Beispiele (${exList.length})`} color={C.gold} />
        <div style={{ display:"grid", gap:8 }}>
          {exList.map((e,i) => (
            <div key={i} className="rise" style={{ animationDelay:`${142+i*18}ms`, background:"#fff", border:"1.5px solid #F0F1F5", borderRadius:13, padding:"11px 13px", display:"flex", gap:10, alignItems:"flex-start", boxShadow:"0 1px 0 rgba(0,0,0,.05),0 4px 12px rgba(0,0,0,.05)" }}>
              <span style={{ width:21,height:21,borderRadius:6,background:`${C.gold}18`,display:"grid",placeItems:"center",fontSize:10,fontWeight:800,color:C.gold,flexShrink:0,marginTop:1 }}>{i+1}</span>
              <div style={{ flex:1 }}>
                <div style={{ display:"flex",alignItems:"flex-start",gap:4 }}>
                  <div style={{ flex:1 }}><De size={15} color="#1A1F2E">{e.de}</De></div>
                  <Speak text={e.de} size={13} />
                </div>
                {(e[lang] || e.ku) && (
                  <div style={{ color:lc,fontSize:14,marginTop:4,lineHeight:1.7 }}>{e[lang] || e.ku}</div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
      {/* AI */}
      <div className="rise" style={{ animationDelay:"195ms" }}>
        <AITest subject={lang === "tr" ? `Dilbilgisi: «${g.de}» (${tC(g, lang)})` : lang === "en" ? `Grammar: «${g.de}» (${tC(g, lang)})` : lang === "ar" ? `القواعد: «${g.de}» (${tC(g, lang)})` : lang === "fa" ? `دستور زبان: «${g.de}» (${tC(g, lang)})` : lang === "es" ? `Gramática: «${g.de}» (${tC(g, lang)})` : lang === "uk" ? `Граматика: «${g.de}» (${tC(g, lang)})` : lang === "fr" ? `Grammaire: «${g.de}_» (${tC(g, lang)}_)` : `ڕێزمان: «${g.de}» (${tC(g, lang)})`} level={level}
          pct={progress[level+"::"+g.de]||0} onBatch={mkBatch(level+"::"+g.de)} lang={lang} />
      </div>
    </div>
  );
}


