// ── Spaced-repetition scheduler (SM-2 lite) ─────────────────────────
// Persisted in localStorage 'fuxi_srs' keyed by lowercased German word.
// Each entry: { ease, interval(days), reps, due(ms), last(ms) }.
const SRS_DAY = 86400000;
function srsLoad() { try { return JSON.parse(localStorage.getItem("fuxi_srs") || "{}"); } catch { return {}; } }
function srsSave(s) { try { localStorage.setItem("fuxi_srs", JSON.stringify(s)); } catch { /* Local storage may be unavailable. */ } }
function srsGrade(de, correct) {
  if (!de) return;
  const s = srsLoad();
  const key = de.toLowerCase();
  const now = Date.now();
  const e = s[key] || { ease: 2.5, interval: 0, reps: 0 };
  if (correct) {
    e.reps = (e.reps || 0) + 1;
    e.interval = e.reps === 1 ? 1 : e.reps === 2 ? 3 : Math.round((e.interval || 1) * (e.ease || 2.5));
    e.ease = Math.min(3.0, (e.ease || 2.5) + 0.1);
  } else {
    e.reps = 0;
    e.interval = 0; // resurface next review session
    e.ease = Math.max(1.3, (e.ease || 2.5) - 0.2);
  }
  e.due = now + e.interval * SRS_DAY;
  e.last = now;
  s[key] = e;
  srsSave(s);
}
// Word objects (from all levels) whose review is due now.
function srsDueWords() {
  const s = srsLoad();
  const now = Date.now();
  const dueKeys = new Set(Object.keys(s).filter((k) => (s[k].due || 0) <= now));
  if (!dueKeys.size) return [];
  const seen = new Set();
  return Object.values(FLASHCARDS).flat().filter((w) => {
    const k = (w.de || "").toLowerCase();
    if (!dueKeys.has(k) || seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}
function srsDueCount() {
  const s = srsLoad();
  const now = Date.now();
  return Object.keys(s).filter((k) => (s[k].due || 0) <= now).length;
}

// ── کارت / Flashcards ──────────────────────────────────────────────
function Flashcards({ fixedLevel, favs = [], toggleFav, lang = "ku" } = {}) {
  const [level,    setLevel]    = useState(fixedLevel || "A1");
  const [deck,     setDeck]     = useState(() => mkDeck(fixedLevel || "A1"));
  const [idx,      setIdx]      = useState(0);
  const [selected, setSelected] = useState(null); // null | option-index
  const [scores,   setScores]   = useState({ correct: 0, wrong: 0 });
  const [streak,   setStreak]   = useState(0);
  const [optKey,   setOptKey]   = useState(0); // bump → regenerate options

  function mkDeck(lv) {
    const source = lv === "REVIEW" ? srsDueWords() : (FLASHCARDS[lv] || []);
    return source.map((w, i) => ({
      ...w, key: i,
      uid: `${i}-${Math.random()}`, // unique per instance (repeats get different uid)
      retries: 0,
    })).sort(() => Math.random() - 0.5);
  }

  // ── build 3 options: 1 correct + 2 random wrong ──

  const options = useMemo(() => {
    const card = deck[idx];
    if (!card) return [];
    const pool = (FLASHCARDS[level] || []).filter(w => w.de !== card.de);
    // fallback: pick from all levels if pool too small
    const src = pool.length >= 2 ? pool
      : Object.values(FLASHCARDS).flat().filter(w => w.de !== card.de);
    const wrong = [...src].sort(() => Math.random() - 0.5).slice(0, 2)
      .map(w => ({ label: tC(w, lang), correct: false }));
    return [{ label: tC(card, lang), correct: true }, ...wrong].sort(() => Math.random() - 0.5);
  // optKey is the trigger — we intentionally read deck/idx/level from closure
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [optKey]);

  function reset(lv) {
    const d = mkDeck(lv);
    setDeck(d); setIdx(0); setSelected(null);
    setScores({ correct: 0, wrong: 0 }); setStreak(0);
    setOptKey(k => k + 1);
  }
  function changeLevel(lv) { setLevel(lv); reset(lv); }

  function choose(i) {
    if (selected !== null) return;
    const correct = options[i].correct;
    const answeredCard = deck[idx];
    if (answeredCard) srsGrade(answeredCard.de, correct); // spaced-repetition grade
    setSelected(i);
    setScores(s => ({ ...s, correct: s.correct + (correct ? 1 : 0), wrong: s.wrong + (correct ? 0 : 1) }));
    setStreak(s => correct ? s + 1 : 0);
    // Wrong answer → push card back 3-5 positions (max 2 retries)
    if (!correct) {
      const card = deck[idx];
      if (card.retries < 2) {
        const nextDeck = [...deck];
        const at = Math.min(idx + 3 + Math.floor(Math.random() * 3), nextDeck.length);
        nextDeck.splice(at, 0, { ...card, retries: card.retries + 1, uid: `${card.key}-r${card.retries + 1}-${Math.random()}` });
        setDeck(nextDeck);
      }
    }
  }

  function next() {
    setIdx(i => i + 1);
    setSelected(null);
    setOptKey(k => k + 1);
  }

  // ── keyboard: 1/2/3 = choose, Space/Enter = next ──
  useEffect(() => {
    function onKey(e) {
      if (idx >= deck.length) return;
      if (selected === null) {
        if (e.key === "1") choose(0);
        if (e.key === "2") choose(1);
        if (e.key === "3") choose(2);
      } else {
        if (e.code === "Space" || e.code === "Enter") { e.preventDefault(); next(); }
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected, idx, deck, options]);

  const card     = deck[idx];
  const finished = idx >= deck.length;
    const total    = scores.correct + scores.wrong;
  const accuracy = total > 0 ? Math.round((scores.correct / total) * 100) : 0;
  const lvColor  = level === "REVIEW" ? "#7C3AED" : levelColor(level);
  const dueCount = srsDueCount();
  const meta     = card ? WORD_META[card.de] : null;
  const artInfo  = card ? detectArticle(card.de) : null;
  const displayWord = card ? (artInfo ? card.de.slice(card.de.indexOf(" ") + 1) : card.de) : "";

  return (
    <div className="rise">
      {/* ── Header (only when standalone, not embedded inside Lessons) ── */}
      {!fixedLevel && (
        <>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:4 }}>
            <h2 style={{ fontWeight:700, fontSize:22, margin:0 }}>{lang === "tr" ? "Kelime Kartları" : lang === "en" ? "Flashcards" : lang === "ar" ? "بطاقات الكلمات" : lang === "es" ? "Tarjetas" : lang === "uk" ? "Картки" : lang === "fa" ? "کارت‌ها" : lang === "fr" ? "Cartes-éclair" : "کارتی وشەکان"}</h2>
            {streak > 1 && (
              <div style={{ display:"flex", alignItems:"center", gap:4, background:"rgba(245,165,36,.15)", border:"1px solid rgba(245,165,36,.3)", borderRadius:99, padding:"4px 12px" }}>
                <Zap size={14} color={C.gold} />
                <span style={{ fontSize:13, fontWeight:700, color:C.gold }}>{streak} 🔥</span>
              </div>
            )}
          </div>
          <p style={{ color:C.muted, fontSize:13, marginBottom:14 }}>{lang === "tr" ? "Beyin hazır mı? Kelimeler savaşa hazır — kimin kazanacağını gör! ⚔️🧠" : lang === "en" ? "Brain ready? The words are ready to battle — see who wins! ⚔️🧠" : lang === "ar" ? "هل عقلك جاهز؟ الكلمات جاهزة للمعركة — انظر من سيفوز! ⚔️🧠" : lang === "es" ? "¿Cerebro listo? Las palabras están listas para la batalla — ¡mira quién gana! ⚔️🧠" : lang === "uk" ? "Мозок готовий? Слова готові до бою — побач, хто переможе! ⚔️🧠" : lang === "fa" ? "مغزت آماده است؟ واژه‌ها آماده نبردند — ببین چه کسی می‌برد! ⚔️🧠" : lang === "fr" ? "Le cerveau est prêt? Les mots sont prêts à combattre — voir qui gagne!" : "مێشکت ئامادەیە؟ وشەکان ئامادەی شەڕن — ببینە کێ دەبەرێت! ⚔️🧠"}</p>
          <LevelPills value={level} onChange={changeLevel} />
          {/* Spaced-repetition review entry */}
          <div style={{ display:"flex", justifyContent:"center", marginTop:10 }}>
            <button onClick={() => changeLevel("REVIEW")} disabled={level !== "REVIEW" && dueCount === 0}
              style={{ display:"inline-flex", alignItems:"center", gap:7, borderRadius:99, padding:"7px 16px", cursor: (level !== "REVIEW" && dueCount === 0) ? "default" : "pointer",
                border: `1.5px solid ${level === "REVIEW" ? "#7C3AED" : (dueCount ? "#7C3AED55" : C.line)}`,
                background: level === "REVIEW" ? "#7C3AED" : (dueCount ? "#7C3AED10" : "transparent"),
                color: level === "REVIEW" ? "#fff" : (dueCount ? "#7C3AED" : C.muted), fontWeight:700, fontSize:13 }}>
              <RefreshCw size={14} />
              {lang === "tr" ? "Tekrar" : lang === "en" ? "Review" : lang === "ar" ? "مراجعة" : lang === "es" ? "Repaso" : lang === "uk" ? "Повторення" : lang === "fa" ? "مرور" : lang === "fr" ? "Révision" : "پێداچوونەوە"}
              {dueCount > 0 && (
                <span style={{ background: level === "REVIEW" ? "rgba(255,255,255,.25)" : "#7C3AED", color:"#fff", borderRadius:99, padding:"1px 8px", fontSize:11, fontWeight:800 }}>{dueCount}</span>
              )}
            </button>
          </div>
        </>
      )}
      {/* ── When embedded: streak badge ── */}
      {fixedLevel && streak > 1 && (
        <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:10 }}>
          <div style={{ display:"flex", alignItems:"center", gap:4, background:"rgba(245,165,36,.15)", border:"1px solid rgba(245,165,36,.3)", borderRadius:99, padding:"4px 12px" }}>
            <Zap size={14} color={C.gold} />
            <span style={{ fontSize:13, fontWeight:700, color:C.gold }}>{streak} 🔥</span>
          </div>
        </div>
      )}

      {level === "REVIEW" && deck.length === 0 ? (
        /* ── No reviews due ── */
        <div className="rise" style={{ textAlign:"center", padding:"40px 20px" }}>
          <div style={{ fontSize:44, marginBottom:12 }}>✅</div>
          <h3 style={{ fontWeight:800, fontSize:20, margin:"0 0 6px" }}>
            {lang === "tr" ? "Tekrar edilecek kelime yok" : lang === "en" ? "No words due for review" : lang === "ar" ? "لا توجد كلمات للمراجعة" : lang === "es" ? "No hay palabras para repasar" : lang === "uk" ? "Немає слів для повторення" : lang === "fa" ? "واژه‌ای برای مرور نیست" : lang === "fr" ? "Aucun mot n'est attendu pour être examiné" : "هیچ وشەیەک بۆ پێداچوونەوە نییە"}
          </h3>
          <p style={{ color:C.muted, fontSize:13.5, lineHeight:1.6, maxWidth:320, margin:"0 auto" }}>
            {lang === "tr" ? "Kartları çalış; öğrendiğin kelimeler zamanı gelince burada tekrar için birikir." : lang === "en" ? "Practise the cards — the words you learn will show up here for review when they're due." : lang === "ar" ? "تدرّب على البطاقات — ستظهر الكلمات التي تتعلّمها هنا للمراجعة عند حلول موعدها." : lang === "es" ? "Practica las tarjetas — las palabras que aprendas aparecerán aquí para repasar cuando toque." : lang === "uk" ? "Тренуйте картки — вивчені слова з'являться тут для повторення, коли настане час." : lang === "fa" ? "کارت‌ها را تمرین کنید — واژه‌های یادگرفته‌شده هنگام فرارسیدن زمان برای مرور اینجا ظاهر می‌شوند." : lang === "fr" ? "Pratiquez les cartes — les mots que vous apprendrez seront ici pour examen quand ils seront dus." : "کارتەکان مەشق بکە — ئەو وشانەی فێری دەبیت لێرە بۆ پێداچوونەوە کۆدەبنەوە کاتێک کاتیان دێت."}
          </p>
        </div>
      ) : finished ? (
        /* ── Completion ── */
        <div className="rise" style={{ textAlign:"center", padding:"32px 0" }}>
          <div style={{ width:80, height:80, borderRadius:"50%", background:`linear-gradient(135deg,${lvColor},${C.gold})`, display:"grid", placeItems:"center", margin:"0 auto 16px", boxShadow:`0 12px 32px ${lvColor}55` }}>
            <Trophy size={36} color="#fff" />
          </div>
          <h3 style={{ fontWeight:800, fontSize:26, margin:"0 0 8px" }}>{lang === "tr" ? "Tebrikler!" : lang === "en" ? "Congratulations!" : lang === "ar" ? "تهانينا!" : lang === "es" ? "¡Enhorabuena!" : lang === "uk" ? "Вітаємо!" : lang === "fa" ? "تبریک!" : lang === "fr" ? "Félicitations!" : "تەواوت کرد!"}</h3>
          <p style={{ color:C.muted, fontSize:14, marginBottom:20 }}>
            {scores.correct} {lang === "tr" ? "/ " : lang === "en" ? "/ " : lang === "ar" ? "/ " : lang === "es" ? "/ " : lang === "uk" ? "/ " : lang === "fa" ? "/ " : lang === "fr" ? "/" : "لە "}{total} — <strong style={{ color:lvColor }}>{accuracy}%</strong>
          </p>
          <div style={{ display:"flex", gap:12, justifyContent:"center", marginBottom:24 }}>
            {[
              { Icon:CheckCircle2, count:scores.correct, label: lang === "tr" ? "Doğru" : lang === "en" ? "Correct" : lang === "ar" ? "صحيح" : lang === "es" ? "Correcto" : lang === "uk" ? "Правильно" : lang === "fa" ? "درست" : lang === "fr" ? "Corrigé" : "دروست", color:"#16A06F" },
              { Icon:XCircle,      count:scores.wrong,   label: lang === "tr" ? "Yanlış" : lang === "en" ? "Wrong" : lang === "ar" ? "خطأ" : lang === "es" ? "Incorrecto" : lang === "uk" ? "Неправильно" : lang === "fa" ? "غلط" : lang === "fr" ? "Faux" : "هەڵە",  color:"#ef4444" },
            ].map(s => (
              <div key={s.label} style={{ background:C.panel, border:`1px solid ${C.line}`, borderRadius:16, padding:"16px 28px" }}>
                <s.Icon size={24} color={s.color} style={{ margin:"0 auto 6px", display:"block" }} />
                <div style={{ fontWeight:800, fontSize:26, color:s.color }}>{s.count}</div>
                <div style={{ fontSize:12, color:C.muted }}>{s.label}</div>
              </div>
            ))}
          </div>
          <button onClick={() => reset(level)}
            style={{ background:`linear-gradient(135deg,${lvColor},${C.gold})`, color:"#fff", border:"none", padding:"13px 32px", borderRadius:16, fontWeight:700, fontSize:15, cursor:"pointer", display:"inline-flex", alignItems:"center", gap:8, boxShadow:`0 6px 20px ${lvColor}44` }}>
            <RefreshCw size={16} /> {lang === "tr" ? "Tekrar Pratik Yap" : lang === "en" ? "Practice Again" : lang === "ar" ? "تدرّب مرة أخرى" : lang === "es" ? "Practicar de nuevo" : lang === "uk" ? "Потренуватися ще раз" : lang === "fa" ? "دوباره تمرین کن" : lang === "fr" ? "Pratiquez encore" : "دووبارە مەشق بکە"}
          </button>
        </div>
      ) : card ? (
        <>
          {/* ── Deck counter ── */}
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16, marginTop:4 }}>
            <span style={{ background:lvColor, color:"#fff", padding:"3px 11px", borderRadius:14, fontSize:12, fontWeight:700 }}>{level}</span>
            <span style={{ display:"flex", alignItems:"center", gap:6, background:"#F4F6FA", borderRadius:99, padding:"5px 14px" }}>
              <span style={{ fontSize:14, fontWeight:800, color:C.ink }}>{idx + 1}</span>
              <span style={{ fontSize:11, color:"#C4CAD8", fontWeight:600 }}>/</span>
              <span style={{ fontSize:12, fontWeight:600, color:C.muted }}>{deck.length}</span>
            </span>
          </div>

          {/* ── Circular card with ring border + flip ── */}
          {(() => {
            const SIZE = 270;
            const R = 127;
            const CX = SIZE / 2, CY = SIZE / 2;
            const CIRC = 2 * Math.PI * R;
            const ringPct = deck.length > 0 ? scores.correct / deck.length : 0;
            const dash = ringPct * CIRC;
            const flipped = selected !== null;
            const faceStyle = {
              position:"absolute", inset:0,
              borderRadius:"50%",
              display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center",
              textAlign:"center", padding:"22px 18px", gap:5, overflow:"hidden",
              backfaceVisibility:"hidden", WebkitBackfaceVisibility:"hidden",
            };
            return (
              <div style={{ display:"flex", justifyContent:"center", marginBottom:16 }}>
                <div style={{ position:"relative", width:SIZE, height:SIZE }}>
                  {/* SVG progress ring */}
                  <svg width={SIZE} height={SIZE}
                    style={{ position:"absolute", inset:0, transform:"rotate(-90deg)", pointerEvents:"none", zIndex:0 }}>
                    <circle cx={CX} cy={CY} r={R} fill="none" stroke="#E8EAF0" strokeWidth={7} />
                    <circle cx={CX} cy={CY} r={R} fill="none" stroke="#16A06F" strokeWidth={7}
                      strokeDasharray={`${dash} ${CIRC}`} strokeLinecap="round"
                      style={{ transition:"stroke-dasharray .6s cubic-bezier(.34,1.56,.64,1)" }} />
                  </svg>

                  {/* Flip container */}
                  <div key={card.uid} className="card-flip"
                    style={{
                      position:"absolute", inset:10,
                      transformStyle:"preserve-3d",
                      transition:"transform .65s cubic-bezier(.34,1.1,.64,1)",
                      transform: flipped ? "rotateY(180deg)" : "rotateY(0deg)",
                    }}>

                    {/* ── FRONT: German word ── */}
                    <div style={{
                      ...faceStyle,
                      background:"linear-gradient(145deg,#ffffff,#f5f7fc)",
                      boxShadow:"0 8px 32px rgba(0,0,0,.09), inset 0 1px 0 rgba(255,255,255,.9)",
                    }}>
                      {artInfo && (
                        <div style={{ background:artInfo.color, color:"#fff", fontSize:11, fontWeight:700,
                          padding:"2px 12px", borderRadius:99 }}>{artInfo.art}</div>
                      )}
                      <De size={displayWord.length <= 9 ? 34 : displayWord.length <= 13 ? 26 : displayWord.length <= 18 ? 20 : 16} color={C.ink}>{displayWord}</De>
                      <div><Speak text={card.de} size={22} /></div>
                      <div style={{ fontSize:10, letterSpacing:".07em", color:C.muted, fontWeight:600 }}>Deutsch</div>
                    </div>

                    {/* ── BACK: example sentence ── */}
                    <div style={{
                      ...faceStyle,
                      background:"linear-gradient(145deg,#0f172a,#1e293b)",
                      boxShadow:"0 8px 32px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.07)",
                      transform:"rotateY(180deg)",
                      gap:8,
                    }}>
                      {/* Native lang answer */}
                      <div style={{ fontWeight:800, fontSize:20, color:"#fff", lineHeight:1.2 }}>{tC(card, lang)}</div>
                      {/* divider */}
                      <div style={{ width:32, height:2, borderRadius:2, background:`linear-gradient(90deg,${lvColor},transparent)` }} />
                      {/* example */}
                      {card.ex && (
                        <div style={{ fontSize:12, color:"rgba(255,255,255,.75)", lineHeight:1.65, fontStyle:"italic" }} dir="ltr">
                          {card.ex}
                        </div>
                      )}
                      {(lang === "tr" ? (card.extr || card.exku) : lang === "en" ? (card.exen || card.exku) : lang === "ar" ? (card.exar || card.exku) : lang === "fa" ? (card.exfa || card.exku) : lang === "es" ? (card.exes || card.exku) : lang === "uk" ? (card.exuk || card.exku) : card.exku) && (
                        <div style={{ fontSize:11, color:"rgba(255,255,255,.45)", lineHeight:1.5 }}>{lang === "tr" ? (card.extr || card.exku) : lang === "en" ? (card.exen || card.exku) : lang === "ar" ? (card.exar || card.exku) : lang === "fa" ? (card.exfa || card.exku) : lang === "es" ? (card.exes || card.exku) : lang === "uk" ? (card.exuk || card.exku) : card.exku}</div>
                      )}
                      {/* TTS on back */}
                      <div style={{ marginTop:2 }}><Speak text={card.de} size={16} color="rgba(255,255,255,.5)" /></div>
                    </div>

                  </div>
                </div>
              </div>
            );
          })()}

          {/* ── Revealed info — always rendered, content fades in after answer ── */}
          <style>{`@keyframes revealFlip { from { transform:perspective(600px) rotateX(-40deg) translateY(-8px); opacity:0; } to { transform:none; opacity:1; } }`}</style>
          <div style={{
            background:C.panel, border:`1px solid ${C.line}`,
            borderRadius:18, padding:"14px 18px", marginBottom:14, textAlign:"center",
            minHeight:100, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center",
          }}>
            {selected === null ? (
              /* placeholder dots */
              <div style={{ display:"flex", gap:6 }}>
                {[0,1,2].map(i => (
                  <div key={i} style={{ width:6, height:6, borderRadius:"50%", background:C.line }} />
                ))}
              </div>
            ) : (
              <div style={{ animation:"revealFlip .5s cubic-bezier(.34,1.1,.64,1) both", width:"100%" }}>
                <div style={{ fontWeight:700, fontSize:20, color:lvColor, marginBottom:6 }}>{tC(card, lang)}</div>
                {meta && (
                  <div style={{ display:"inline-flex", alignItems:"center", gap:6, marginBottom:8,
                    background: meta.ant ? "rgba(229,72,77,.08)" : "rgba(91,91,214,.08)",
                    border:`1px solid ${meta.ant ? "rgba(229,72,77,.25)" : "rgba(91,91,214,.25)"}`,
                    borderRadius:99, padding:"3px 12px", fontSize:12 }}>
                    <span style={{ fontWeight:700, color: meta.ant ? "#E5484D" : C.red }}>
                      {meta.ant ? "↔ Antonym:" : "≈ Synonym:"}
                    </span>
                    <De size={12} color={C.ink}>{meta.ant || meta.syn}</De>
                  </div>
                )}
                <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:5, marginBottom:2 }}>
                  <De size={13} color={C.muted}>{card.ex}</De>
                  <Speak text={card.ex} size={13} />
                </div>
                <div style={{ color:C.muted, fontSize:12, lineHeight:1.7 }}>{lang === "tr" ? (card.extr || card.exku) : lang === "en" ? (card.exen || card.exku) : lang === "ar" ? (card.exar || card.exku) : lang === "fa" ? (card.exfa || card.exku) : lang === "es" ? (card.exes || card.exku) : lang === "uk" ? (card.exuk || card.exku) : card.exku}</div>
              </div>
            )}
          </div>

          {/* ── 3 options ── */}
          <div key={optKey} style={{ display:"flex", flexDirection:"row", gap:8, animation:"fadeOpts .45s .12s cubic-bezier(.34,1.56,.64,1) both" }}>
            {options.map((opt, i) => {
              const answered  = selected !== null;
              const isCorrect = opt.correct;
              const isPicked  = selected === i;

              const state = !answered ? "idle"
                : isCorrect ? "correct"
                : isPicked  ? "wrong"
                : "dim";

              const styles = {
                idle:    { bg:"transparent",           border:"1.5px solid #E4E8F0", clr:C.ink,    dot:"#E4E8F0",  dotClr:C.muted,   shadow:"none" },
                correct: { bg:"rgba(22,160,111,.08)",  border:"1.5px solid #16A06F", clr:"#16A06F", dot:"#16A06F",  dotClr:"#fff",    shadow:"0 4px 14px rgba(22,160,111,.18)" },
                wrong:   { bg:"rgba(229,72,77,.08)",   border:"1.5px solid #E5484D", clr:"#E5484D", dot:"#E5484D",  dotClr:"#fff",    shadow:"none" },
                dim:     { bg:"transparent",           border:"1.5px solid #ECEEF2", clr:"#C4CAD8", dot:"#ECEEF2",  dotClr:"#D0D5DF", shadow:"none" },
              }[state];

              return (
                <button key={i} onClick={() => choose(i)}
                  style={{
                    flex: 1,
                    background: styles.bg,
                    border: styles.border,
                    borderRadius: 14,
                    padding: "0 8px",
                    height: 64,
                    fontFamily: "'Vazirmatn',sans-serif",
                    fontSize: 13,
                    fontWeight: state === "idle" ? 500 : 700,
                    color: styles.clr,
                    cursor: answered ? "default" : "pointer",
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: 6,
                    transition: "all .2s ease",
                    boxShadow: styles.shadow,
                    textAlign: "center",
                    lineHeight: 1.4,
                  }}>

                  <span>{opt.label}</span>
                  {/* always reserve icon space to prevent height shift */}
                  <span style={{ height:14, display:"flex", alignItems:"center", opacity: answered ? 1 : 0, transition:"opacity .2s" }}>
                    {isCorrect ? <CheckCircle2 size={14} /> : isPicked ? <XCircle size={14} /> : <span style={{ width:14 }} />}
                  </span>
                </button>
              );
            })}
          </div>

          {/* ── Next + Fav row ── always visible */}
          {(() => {
            const answered = selected !== null;
            const isFav = favs.some(f => f.de === card.de);
            return (
              <div style={{ marginTop:14, display:"flex", gap:10 }}>
                {/* Heart / fav — only active after answering */}
                <button onClick={() => answered && toggleFav && toggleFav(card)}
                  style={{ flexShrink:0, width:52, height:52, borderRadius:16,
                    border:`1.5px solid ${answered && isFav ? "#ef4444" : C.line}`,
                    background: answered && isFav ? "rgba(239,68,68,.08)" : C.panel,
                    cursor: answered ? "pointer" : "default",
                    display:"grid", placeItems:"center",
                    opacity: answered ? 1 : 0.35,
                    transition:"all .2s ease" }}>
                  <Heart size={20}
                    fill={answered && isFav ? "#ef4444" : "none"}
                    color={answered && isFav ? "#ef4444" : C.muted} />
                </button>
                {/* Continue button */}
                <button onClick={answered ? next : undefined}
                  disabled={!answered}
                  className={answered ? "glow-btn" : ""}
                  style={{ flex:1, padding:"14px", borderRadius:16, fontWeight:700, fontSize:15,
                    display:"flex", alignItems:"center", justifyContent:"center", gap:10,
                    border: answered ? "none" : `1.5px solid ${C.line}`,
                    background: answered ? undefined : C.panel,
                    color: answered ? undefined : C.muted,
                    cursor: answered ? "pointer" : "not-allowed",
                    opacity: answered ? 1 : 0.5,
                    transition:"all .25s ease" }}>
                  {lang === "tr" ? "İleri" : lang === "en" ? "Forward" : lang === "ar" ? "التالي" : lang === "es" ? "Adelante" : lang === "uk" ? "Уперед" : lang === "fa" ? "به جلو" : lang === "fr" ? "Suivant" : "بەرەو پێشەوە"}
                </button>
              </div>
            );
          })()}
        </>
      ) : null}
    </div>
  );
}

// ── دڵخوازەکان / Favourites ──────────────────────────────────────────
const FAV_TYPE_LABEL = { noun:'Substantiv', verb:'Verb', adj:'Adjektiv', adv:'Adverb', phrase:'Phrasel' };

function FavPage({ favs = [], toggleFav, lang = "ku" }) {
  if (favs.length === 0) {
    return (
      <div className="rise" style={{ textAlign:"center", padding:"64px 0" }}>
        <div style={{ width:72, height:72, borderRadius:"50%", background:"rgba(239,68,68,.08)",
          display:"grid", placeItems:"center", margin:"0 auto 16px" }}>
          <Heart size={32} color="#ef4444" />
        </div>
        <h3 style={{ fontWeight:800, fontSize:22, margin:"0 0 8px" }}>{tApp(lang,"fav_empty_h")}</h3>
        <p style={{ color:"#8892A4", fontSize:14, margin:0 }}>
          {tApp(lang,"fav_empty_p")}
        </p>
      </div>
    );
  }
  return (
    <div className="rise">
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:20 }}>
        <div style={{ width:40, height:40, borderRadius:12, background:"rgba(239,68,68,.1)",
          display:"grid", placeItems:"center" }}>
          <Heart size={20} color="#ef4444" fill="#ef4444" />
        </div>
        <div>
          <h2 style={{ fontWeight:800, fontSize:22, margin:0 }}>{tApp(lang,"fav_title")}</h2>
          <div style={{ fontSize:13, color:"#8892A4", marginTop:1 }}>{favs.length} {tApp(lang,"fav_words")}</div>
        </div>
      </div>

      <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
        {favs.map((w, i) => {
          const artInfo = detectArticle(w.de);
          const displayWord = artInfo ? w.de.slice(w.de.indexOf(" ") + 1) : w.de;
          const dictEntry = BOOK_DICT[displayWord.toLowerCase()];
          const typeLabel = dictEntry && FAV_TYPE_LABEL[dictEntry.type];
          return (
            <div key={w.de} className="rise"
              style={{ background:"#fff", borderRadius:16, border:"1.5px solid #E8EAF0",
                boxShadow:"0 2px 0 rgba(0,0,0,.06), 0 6px 18px rgba(0,0,0,.06)",
                display:"flex", alignItems:"stretch", overflow:"hidden" }}>

              {/* Left number */}
              <div style={{ width:52, flexShrink:0, background:"rgba(239,68,68,.08)",
                display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center",
                gap:1, padding:"10px 6px" }}>
                <Heart size={14} color="#ef4444" fill="#ef4444" />
                <div style={{ fontSize:10, fontWeight:700, color:"rgba(239,68,68,.6)", letterSpacing:".06em", marginTop:2 }}>
                  {String(i+1).padStart(2,"0")}
                </div>
              </div>

              {/* Content */}
              <div style={{ flex:1, padding:"12px 12px 12px 14px", display:"flex", flexDirection:"column", gap:5, minWidth:0 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                  {artInfo && (
                    <span style={{ background:artInfo.color, color:"#fff", fontSize:10, fontWeight:700,
                      padding:"1px 8px", borderRadius:99 }}>{artInfo.art}</span>
                  )}
                  <span style={{ fontWeight:800, fontSize:15, color:"#1A1F2E" }} dir="ltr">{displayWord}</span>
                  {typeLabel && (
                    <span style={{ background:"#f4f4f5", color:"#71717A", fontSize:10, fontWeight:700,
                      padding:"1px 8px", borderRadius:99 }}>{typeLabel}</span>
                  )}
                  <Speak text={w.de} size={14} />
                </div>
                <div style={{ fontWeight:700, fontSize:13, color:"#5B5BD6" }}>{tC(w, lang)}</div>
                {w.ex && (
                  <>
                    <div style={{ fontSize:12, color:"#5A6480", fontStyle:"italic" }} dir="ltr">{w.ex}</div>
                    {(tEx(w, lang)) && (
                      <div style={{ fontSize:11, color:"#8892A4" }}>{tEx(w, lang)}</div>
                    )}
                  </>
                )}
              </div>

              {/* Remove button */}
              <div style={{ width:64, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center",
                borderLeft:"1.5px solid #F0F1F5" }}>
                <button onClick={() => toggleFav(w)}
                  style={{ background:"rgba(239,68,68,.1)", border:"none", borderRadius:12, cursor:"pointer",
                    padding:"8px 6px", display:"flex", flexDirection:"column", alignItems:"center", gap:3 }}>
                  <Heart size={18} fill="#ef4444" color="#ef4444" />
                  <span style={{ fontSize:9, fontWeight:700, color:"#ef4444" }}>{tApp(lang,"fav_remove")}</span>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── گفتوگۆ / AI Talk ───────────────────────────────────────────────
function Talk({ lang = "ku" }) {
  const [msgs, setMsgs] = useState(() => [
    { role: "assistant", text: lang === "tr"
      ? "Merhaba! Ben Almanca öğretmeninizim. 😊 Kelimeler, cümleler, dilbilgisi veya serbest konuşma — ne isterseniz söyleyin, başlayalım!"
      : "سڵاو! من مامۆستای ئەڵمانیتم. 😊 هەر مەبەستێک هەیت — وشە، ڕستە، گرامەر، یان ئازادانە قسەکردن — پێمبڵێ، با دەست پێبکەین!" },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const endRef = useRef(null);
  useEffect(() => { endRef.current?.scrollIntoView({ behavior: "smooth" }); }, [msgs, loading]);

  async function send() {
    const text = input.trim();
    if (!text || loading) return;
    const next = [...msgs, { role: "user", text }];
    setMsgs(next); setInput(""); setLoading(true);

    const system = lang === "tr"
      ? "Adın «Rehber»dir, Türkçe konuşan birine nazikçe Almanca öğreten bir öğretmensin. " +
        "Öğrencinin seviyesi belirtilmemiş — yazdıklarından seviyeyi kendin belirle ve ona göre konuş. " +
        "Kullanıcı istediği konuyu açabilir — konuşma, kelime, dilbilgisi, soru, çeviri — her şey. " +
        "Almanca cevap ver ama her zaman Türkçe açıklama ve çeviri ekle. Cevapları kısa tut (2-4 cümle). " +
        "Kullanıcının hatalarını nazikçe düzelt. Her seferinde bir Almanca örnek ver ve Türkçe anlamını göster."
      : "ناوت «ڕێبەر»ە، مامۆستایەکی ئەڵمانیت کە بە دڵنەرمی فێری کەسێک دەکەیت کە زمانەکەی سۆرانی (کوردی) یە. " +
        "ئاستی فێرخواز دیاری نییە — خۆت ئاستەکەی بناسەرەوە لە ئەو شتەی بەکارهێنەر دەنووسێت و بەپێی ئەوە قسە بکە. " +
        "بەکارهێنەر ئازادە هەر مەبەستێک هەبێت — گفتوگۆ، وشە، گرامەر، پرسیار، وەرگێڕان — هەر شتێک بخوازێت. " +
        "بە ئەڵمانی وەڵام بدەرەوە بەڵام هەمیشە ڕوونکردنەوە و وەرگێڕان بە سۆرانی زیاد بکە. وەڵامەکان کورت بکە (٢-٤ ڕستە). " +
        "هەڵەکانی بەکارهێنەر بە نەرمی ڕاست بکەرەوە. هەر جارێک نموونەیەکی ئەڵمانی بدە و واتاکەی بە سۆرانی پیشان بدە.";

    try {
      const data = await callClaude({ model: "claude-sonnet-4-20250514", max_tokens: 1000, system, messages: next.map((m) => ({ role: m.role, content: m.text })) });
      const reply = (data.content || []).filter((c) => c.type === "text").map((c) => c.text).join("\n").trim();
      setMsgs((m) => [...m, { role: "assistant", text: reply || "..." }]);
    } catch {
      setMsgs((m) => [...m, { role: "assistant", text: tApp(lang,"chat_err") }]);
    } finally { setLoading(false); }
  }

  return (
    <div className="rise">

      {/* ── ROBOT MASCOT PANEL ── */}
      <div style={{ background:"linear-gradient(135deg,#0c0f24 0%,#1a1040 50%,#0c1a2e 100%)", borderRadius:28, padding:"24px 28px", marginBottom:16, position:"relative", overflow:"hidden", boxShadow:"0 24px 60px rgba(6,182,212,0.25)" }}>
        {/* star dots */}
        {[...Array(16)].map((_,i)=>(<div key={i} style={{ position:"absolute", width:i%3===0?3:2, height:i%3===0?3:2, borderRadius:"50%", background:"rgba(255,255,255,.6)", top:`${(i*17+7)%90}%`, left:`${(i*23+5)%88}%`, opacity:.35+i%4*.15, pointerEvents:"none" }}/>))}
        <div style={{ position:"absolute", top:-60, right:-50, width:220, height:220, borderRadius:"50%", background:"radial-gradient(circle,rgba(6,182,212,.22) 0%,transparent 70%)", pointerEvents:"none" }}/>
        <div style={{ position:"absolute", bottom:-50, left:60, width:180, height:180, borderRadius:"50%", background:"radial-gradient(circle,rgba(168,85,247,.18) 0%,transparent 70%)", pointerEvents:"none" }}/>

        <div style={{ display:"flex", alignItems:"center", gap:20, position:"relative" }}>
          {/* Info */}
          <div style={{ flex:1 }}>
            <div style={{ display:"inline-flex", alignItems:"center", gap:5, background:"rgba(6,182,212,.15)", border:"1px solid rgba(6,182,212,.3)", borderRadius:99, padding:"3px 12px", fontSize:11, color:"#67e8f9", fontWeight:700, marginBottom:8, letterSpacing:".06em" }}>✦ {lang === "tr" ? "Almanca Öğretmeni" : lang === "en" ? "German Teacher" : lang === "ar" ? "معلم الألمانية" : lang === "es" ? "Profesor de alemán" : lang === "uk" ? "Учитель німецької" : lang === "fa" ? "معلم آلمانی" : lang === "fr" ? "Professeur d'allemand" : "مامۆستای ئەڵمانیت"}</div>
            <div style={{ fontFamily:"'Satoshi',system-ui,sans-serif", fontSize:20, fontWeight:700, color:"#fff", lineHeight:1.3, marginBottom:6 }}>
              {loading
                ? <span style={{ color:"#fbbf24" }}>{lang === "tr" ? "Notlarıma bakıyorum… " : lang === "en" ? "Checking my notes… " : lang === "ar" ? "أتحقق من ملاحظاتي… " : lang === "es" ? "Revisando mis notas… " : lang === "uk" ? "Переглядаю свої нотатки… " : lang === "fa" ? "در حال مرور یادداشت‌هایم… " : lang === "fr" ? "Je vérifie mes notes..." : "دەفتەرەکەم دەبینم… "}<span style={{ fontSize:17 }}>📓</span></span>
                : <span>{lang === "tr" ? "Merhaba! " : lang === "en" ? "Hello! " : lang === "ar" ? "مرحبًا! " : lang === "es" ? "¡Hola! " : lang === "uk" ? "Привіт! " : lang === "fa" ? "سلام! " : lang === "fr" ? "Bonjour!" : "باشە، "}<span className="gtext">{lang === "tr" ? "Ne öğrenmek istiyorsunuz?" : lang === "en" ? "What would you like to learn?" : lang === "ar" ? "ماذا تريد أن تتعلم؟" : lang === "es" ? "¿Qué te gustaría aprender?" : lang === "uk" ? "Що б ви хотіли вивчити?" : lang === "fa" ? "چه چیزی می‌خواهید یاد بگیرید؟" : lang === "fr" ? "Qu'est-ce que tu veux apprendre?" : "چی دەتەوێت بزانیت؟"}</span></span>}
            </div>
            {loading
              ? <div style={{ display:"flex", gap:5, alignItems:"center" }}>
                  {[0,1,2].map(d=>(<div key={d} style={{ width:7, height:7, borderRadius:"50%", background:"#fbbf24", animation:`thinkDot 1.4s ${d*.22}s ease infinite` }}/>))}
                  <span style={{ color:"rgba(255,255,255,.5)", fontSize:12, marginInlineStart:6 }}>{lang === "tr" ? "Cevap hazırlanıyor…" : lang === "en" ? "Preparing an answer…" : lang === "ar" ? "جارٍ تحضير الإجابة…" : lang === "es" ? "Preparando una respuesta…" : lang === "uk" ? "Готую відповідь…" : lang === "fa" ? "در حال آماده‌سازی پاسخ…" : lang === "fr" ? "Préparer une réponse..." : "وەڵامەکە دیده دەکات…"}</span>
                </div>
              : <div style={{ color:"rgba(255,255,255,.6)", fontSize:13, lineHeight:1.7 }}>{lang === "tr" ? "Her konu · Özgürce konuş" : lang === "en" ? "Any topic · Speak freely" : lang === "ar" ? "أي موضوع · تحدث بحرية" : lang === "es" ? "Cualquier tema · Habla libremente" : lang === "uk" ? "Будь-яка тема · Говоріть вільно" : lang === "fa" ? "هر موضوعی · آزادانه صحبت کنید" : lang === "fr" ? "Tout sujet · Parlez librement" : "هەر مەبەستێک · ئازادانە قسەبکە"}</div>}
          </div>
          {/* SURI agent */}
          <div style={{ flexShrink:0, textAlign:"center" }}>
            <img src="/suri-agent.png" alt="SURI"
              style={{ width:90, height:90, objectFit:"contain",
                filter: loading ? "drop-shadow(0 0 14px rgba(251,191,36,0.7))" : "drop-shadow(0 8px 20px rgba(6,182,212,0.5))",
                animation: loading ? "robotThink 1.4s ease-in-out infinite" : "robotFloat 3.2s ease-in-out infinite" }} />
          </div>
        </div>
      </div>

      <div style={{ background:"rgba(255,255,255,0.55)", border:"1px solid rgba(255,255,255,0.5)", backdropFilter:"blur(24px)", WebkitBackdropFilter:"blur(24px)", borderRadius:22, height:420, display:"flex", flexDirection:"column", overflow:"hidden", boxShadow:"0 12px 40px rgba(14,165,233,0.1)", marginTop:14 }}>
        <div style={{ flex:1, overflowY:"auto", padding:18, display:"flex", flexDirection:"column", gap:12 }}>
          {msgs.map((m, i) => (
            <div key={i} style={{ display:"flex", alignItems:"flex-end", gap:10, flexDirection: m.role==="user" ? "row-reverse" : "row" }}>
              {m.role==="assistant" && (
                <img src="/suri-agent.png" alt="SURI" style={{ width:36, height:36, objectFit:"contain", flexShrink:0, filter:"drop-shadow(0 3px 8px rgba(6,182,212,0.45))" }} />
              )}
              {m.role==="user" && (
                <div style={{ width:34, height:34, borderRadius:"50%", background:"linear-gradient(135deg,#0ea5e9,#8b5cf6)", display:"grid", placeItems:"center", fontSize:16, flexShrink:0, boxShadow:"0 4px 12px rgba(14,165,233,0.4)" }}>🧑‍🎓</div>
              )}
              <div style={{ maxWidth:"78%" }}>
                <div style={{ background: m.role==="user" ? "linear-gradient(135deg,#0ea5e9,#8b5cf6)" : "rgba(255,255,255,0.92)", color: m.role==="user" ? "#fff" : C.ink, border: m.role==="user" ? "none" : "1px solid rgba(148,163,184,0.2)", padding:"12px 16px", borderRadius: m.role==="user" ? "18px 4px 18px 18px" : "4px 18px 18px 18px", fontSize:15, lineHeight:1.8, whiteSpace:"pre-wrap", boxShadow: m.role==="user" ? "0 4px 16px rgba(14,165,233,0.35)" : "0 2px 10px rgba(0,0,0,0.05)" }}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div style={{ display:"flex", alignItems:"center", gap:10 }}>
              <img src="/suri-agent.png" alt="SURI" style={{ width:36, height:36, objectFit:"contain", flexShrink:0, animation:"robotThink 1.4s ease-in-out infinite", filter:"drop-shadow(0 3px 8px rgba(251,191,36,0.5))" }} />
              <div style={{ background:"rgba(255,255,255,0.92)", border:"1px solid rgba(148,163,184,0.2)", padding:"12px 18px", borderRadius:"4px 18px 18px 18px", display:"flex", gap:5 }}>
                {[0,1,2].map(d=>(<div key={d} style={{ width:8, height:8, borderRadius:"50%", background:C.red, animation:`thinkDot 1.4s ${d*.22}s ease infinite` }}/>))}
              </div>
            </div>
          )}
          <div ref={endRef} />
        </div>

        <div style={{ borderTop:"1px solid rgba(148,163,184,0.2)", padding:14, display:"flex", gap:10 }}>
          <input value={input} onChange={(e)=>setInput(e.target.value)} onKeyDown={(e)=>e.key==="Enter"&&send()}
            placeholder={lang === "tr" ? "Buraya Almanca yazın… (örn: Ich heiße…)" : lang === "en" ? "Type in German here… (e.g. Ich heiße…)" : lang === "ar" ? "اكتب بالألمانية هنا… (مثال: Ich heiße…)" : lang === "es" ? `Escribe en alemán aquí… (p. ej. Ich heiße…)` : lang === "uk" ? "Пишіть німецькою тут… (напр.: Ich heiße…)" : lang === "fa" ? "اینجا به آلمانی بنویسید… (مثلاً: Ich heiße…)" : lang === "fr" ? "Tapez ici en allemand... (par exemple Ich heiße...)" : "لێرە بە ئەڵمانی بنووسە… (نموونە: Ich heiße…)"}
            style={{ flex:1, border:"1px solid rgba(148,163,184,0.3)", borderRadius:14, padding:"12px 16px", fontSize:15, outline:"none", background:"rgba(255,255,255,0.9)", color:C.ink, fontFamily:"inherit" }} />
          <button onClick={send} disabled={loading} style={{ background:loading?C.muted:"linear-gradient(135deg,#0ea5e9,#8b5cf6)", color:"#fff", border:"none", padding:"0 22px", borderRadius:14, fontWeight:700, fontSize:18, boxShadow:loading?"none":"0 4px 14px rgba(14,165,233,0.4)" }}>↑</button>
        </div>
      </div>
    </div>
  );
}

