// ── ArtikelQuiz ────────────────────────────────────────────────────────
function ArtikelQuiz({ lang = "ku", onBack }) {
  const AQT = {
    ku:{ title:"ئارتیکل کویز", sub:"der، die، das — کامیانە؟", start:"دەست پێبکە", score:"ئەنجام", restart:"دووبارە", back:"گەڕانەوە", correct:"دروستە!", wrong:"هەڵەیە!", finish:"کۆتایی", lvl_all:"هەموو ئاست", lvl_label:"ئاست هەڵبژێرە", transl:"وەرگێڕان" },
    tr:{ title:"Artikel Quiz",  sub:"der, die veya das?", start:"Başla", score:"Puan", restart:"Tekrar", back:"Geri", correct:"Doğru!", wrong:"Yanlış!", finish:"Bitir", lvl_all:"Tüm seviyeler", lvl_label:"Seviye seç", transl:"Çeviri" },
    en:{ title:"Artikel Quiz",  sub:"der, die or das?", start:"Start", score:"Score", restart:"Restart", back:"Back", correct:"Correct!", wrong:"Wrong!", finish:"Finish", lvl_all:"All levels", lvl_label:"Choose level", transl:"Translation" },
    ar:{ title:"اختبار المقالة",sub:"der أم die أم das؟", start:"ابدأ", score:"نتيجة", restart:"إعادة", back:"رجوع", correct:"صحيح!", wrong:"خطأ!", finish:"إنهاء", lvl_all:"جميع المستويات", lvl_label:"اختر المستوى", transl:"الترجمة" },
  "es":{"title":"Artikel Quiz","sub":"¿Muere o muere?","start":"Comienzo","score":"Puntuación","restart":"Reiniciar","back":"Atrás","correct":"¡Correcto!","wrong":"¡Equivocado!","finish":"Terminar","lvl_all":"Todos los niveles","lvl_label":"Elegir nivel","transl":"Traducción"},"fr":{"title":"Quiz Artikel","sub":"Der, mourir ou das?","start":"Démarrer","score":"Score","restart":"Redémarrer","back":"Précédent","correct":"C'est exact!","wrong":"Faux!","finish":"Finition","lvl_all":"Tous niveaux","lvl_label":"Choisir le niveau","transl":"Traduction"}};
  AQT.uk = { title:"Artikel Quiz", sub:"der, die чи das?", start:"Почати", score:"Бали", restart:"Ще раз", back:"Назад", correct:"Правильно!", wrong:"Неправильно!", finish:"Завершити", lvl_all:"Усі рівні", lvl_label:"Оберіть рівень", transl:"Переклад" };
  AQT.fa = { title:"Artikel Quiz", sub:"der، die یا das؟", start:"شروع", score:"امتیاز", restart:"دوباره", back:"بازگشت", correct:"درست!", wrong:"غلط!", finish:"پایان", lvl_all:"همه سطوح", lvl_label:"انتخاب سطح", transl:"ترجمه" };
  const aqt = (k) => (AQT[lang]||AQT.tr)[k] || (AQT.tr[k]||k);

  const LEVELS = ['All','A1','A2','B1','B2','C1','C2'];
  const ART_COLOR = { der:'#3b82f6', die:'#e879f9', das:'#22c55e' };
  const ART_BG    = { der:'#3b82f615', die:'#e879f915', das:'#22c55e15' };

  const [phase,    setPhase]    = useState('setup');
  const [selLvl,   setSelLvl]   = useState('All');
  const [questions,setQuestions]= useState([]);
  const [qIdx,     setQIdx]     = useState(0);
  const [chosen,   setChosen]   = useState(null);
  const [score,    setScore]    = useState(0);
  const timerRef = useRef(null);

  const getNat = (item) => lang==='tr' ? item.tr : lang==='ku' ? item.ku : lang==='ar' ? item.ar : lang==='uk' ? (item.uk||item.en) : lang==='fa' ? (item.fa||item.en) : (item[lang]||item.en);

  const speak = (text) => {
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'de-DE'; u.rate = 0.85;
    window.speechSynthesis.speak(u);
  };

  const startGame = () => {
    let pool = selLvl==='All' ? ARTIKEL_DATA : ARTIKEL_DATA.filter(d=>d.lv===selLvl);
    if (pool.length < 5) pool = ARTIKEL_DATA;
    const qs = [...pool].sort(()=>Math.random()-0.5).slice(0,10);
    setQuestions(qs); setQIdx(0); setScore(0); setChosen(null);
    setPhase('game');
  };

  const handleAnswer = (art) => {
    if (chosen) return;
    setChosen(art);
    const correct = questions[qIdx].a;
    if (art===correct) setScore(s=>s+1);
    speak(questions[qIdx].w);
    timerRef.current = setTimeout(()=>{
      const nxt = qIdx+1;
      if (nxt>=questions.length) setPhase('result');
      else { setQIdx(nxt); setChosen(null); }
    }, 1400);
  };

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);

  /* SETUP */
  if (phase==='setup') return (
    <div style={{ maxWidth:480, margin:'0 auto', padding:'8px 0' }}>
      <button onClick={onBack} style={{ background:'none',border:'none',color:'#888',cursor:'pointer',display:'flex',alignItems:'center',gap:6,fontSize:14,marginBottom:20 }}>← {aqt('back')}</button>
      <div style={{ textAlign:'center', marginBottom:28 }}>
        <div style={{ fontSize:44 }}>🎯</div>
        <div style={{ fontWeight:800, fontSize:22, marginTop:8 }}>{aqt('title')}</div>
        <div style={{ fontSize:14, color:'#888', marginTop:4 }}>{aqt('sub')}</div>
      </div>
      <div style={{ background:'#fff',borderRadius:16,padding:18,marginBottom:22,border:'1px solid #ebebf0' }}>
        <div style={{ fontSize:12,fontWeight:700,color:'#888',letterSpacing:'.06em',marginBottom:12 }}>{aqt('lvl_label')}</div>
        <div style={{ display:'flex',gap:8,flexWrap:'wrap' }}>
          {LEVELS.map(lv=>(
            <button key={lv} onClick={()=>setSelLvl(lv)}
              style={{ padding:'8px 16px',borderRadius:10,border:`2px solid ${selLvl===lv?'#5B5BD6':'#ddd'}`,background:selLvl===lv?'rgba(91,91,214,.1)':'#fff',color:selLvl===lv?'#5B5BD6':'#555',fontWeight:selLvl===lv?700:500,fontSize:14,cursor:'pointer',transition:'all .15s' }}>
              {lv==='All' ? aqt('lvl_all') : lv}
            </button>
          ))}
        </div>
      </div>
      {/* Article color legend */}
      <div style={{ display:'flex',gap:10,marginBottom:22,justifyContent:'center' }}>
        {Object.entries(ART_COLOR).map(([a,c])=>(
          <div key={a} style={{ display:'flex',alignItems:'center',gap:6,padding:'6px 14px',borderRadius:10,background:`${c}15`,border:`1px solid ${c}44` }}>
            <div style={{ width:8,height:8,borderRadius:'50%',background:c }} />
            <span style={{ fontWeight:700,color:c,fontSize:15 }}>{a}</span>
          </div>
        ))}
      </div>
      <button onClick={startGame}
        style={{ width:'100%',padding:'14px',borderRadius:14,border:'none',background:'linear-gradient(135deg,#E5484D,#f97316)',color:'#fff',fontWeight:700,fontSize:16,cursor:'pointer' }}>
        {aqt('start')} →
      </button>
    </div>
  );

  /* RESULT */
  if (phase==='result') {
    const pct = Math.round((score/questions.length)*100);
    return (
      <div style={{ maxWidth:420, margin:'0 auto', textAlign:'center', padding:'32px 0' }}>
        <div style={{ fontSize:56 }}>{pct>=80?'🏆':pct>=50?'👍':'💪'}</div>
        <div style={{ fontWeight:800,fontSize:22,margin:'16px 0 6px' }}>{aqt('score')}</div>
        <div style={{ fontSize:52,fontWeight:900,color:'#E5484D',lineHeight:1 }}>{score}<span style={{ fontSize:22,color:'#aaa' }}> / {questions.length}</span></div>
        <div style={{ fontSize:24,marginTop:6,color:pct>=70?'#30A46C':'#f97316',fontWeight:700 }}>{pct}%</div>
        <div style={{ display:'flex',gap:12,marginTop:32,justifyContent:'center' }}>
          <button onClick={()=>setPhase('setup')} style={{ padding:'12px 28px',borderRadius:12,border:'1px solid #ddd',background:'#fff',fontWeight:600,fontSize:15,cursor:'pointer' }}>{aqt('back')}</button>
          <button onClick={startGame} style={{ padding:'12px 28px',borderRadius:12,border:'none',background:'linear-gradient(135deg,#E5484D,#f97316)',color:'#fff',fontWeight:700,fontSize:15,cursor:'pointer' }}>{aqt('restart')}</button>
        </div>
      </div>
    );
  }

  /* GAME */
  const q = questions[qIdx];
  const correct = q.a;
  const isRight = chosen===correct;

  return (
    <div style={{ maxWidth:480, margin:'0 auto' }}>
      {/* Progress */}
      <div style={{ display:'flex',alignItems:'center',gap:12,marginBottom:24 }}>
        <button onClick={()=>{if(timerRef.current)clearTimeout(timerRef.current);setPhase('setup');}} style={{ background:'none',border:'none',color:'#888',cursor:'pointer',fontSize:18 }}>←</button>
        <div style={{ flex:1,height:7,background:'#ebebf0',borderRadius:4 }}>
          <div style={{ height:'100%',width:`${(qIdx/questions.length)*100}%`,background:'linear-gradient(90deg,#E5484D,#f97316)',borderRadius:4,transition:'width .4s' }} />
        </div>
        <div style={{ fontSize:13,color:'#888',fontWeight:600 }}>{qIdx+1}/{questions.length}</div>
      </div>

      {/* Word card */}
      <div style={{ background:'#fff',borderRadius:24,padding:'32px 24px',textAlign:'center',border:'1px solid #ebebf0',boxShadow:'0 4px 20px rgba(0,0,0,.08)',marginBottom:28 }}>
        {/* Level badge */}
        <div style={{ display:'inline-block',padding:'3px 12px',borderRadius:20,background:'rgba(229,72,77,.1)',color:'#E5484D',fontSize:11,fontWeight:700,letterSpacing:'.08em',marginBottom:16 }}>{q.lv}</div>
        {/* Word + audio */}
        <div style={{ display:'flex',alignItems:'center',justifyContent:'center',gap:12,marginBottom:12 }}>
          <div style={{ fontSize:38,fontWeight:900,color:'#1a1a2e',letterSpacing:'-.5px' }}>{q.w}</div>
          <button onClick={()=>speak(q.w)} style={{ width:38,height:38,borderRadius:10,border:'1px solid #eee',background:'#f8f8fb',cursor:'pointer',fontSize:17 }}>🔊</button>
        </div>
        {/* Translation */}
        <div style={{ fontSize:18,color:'#666',fontWeight:500 }}>{getNat(q)}</div>

        {/* Feedback */}
        {chosen && (
          <div style={{ marginTop:16,padding:'10px 16px',borderRadius:12,
            background: isRight?'#30A46C12':'#E5484D10',
            border:`1px solid ${isRight?'#30A46C44':'#E5484D44'}` }}>
            {isRight
              ? <div style={{ color:'#30A46C',fontWeight:700,fontSize:15 }}>{aqt('correct')} — <span style={{ color:ART_COLOR[correct] }}>{correct}</span> {q.w}</div>
              : <div style={{ color:'#E5484D',fontWeight:600,fontSize:14 }}>{aqt('wrong')} → <span style={{ color:ART_COLOR[correct],fontWeight:700 }}>{correct}</span> {q.w}</div>
            }
          </div>
        )}
      </div>

      {/* Article buttons */}
      <div style={{ display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:14 }}>
        {['der','die','das'].map(art=>{
          const isPicked  = chosen===art;
          const isCorrect = chosen && art===correct;
          const isWrong   = isPicked && !isCorrect;
          return (
            <button key={art} onClick={()=>handleAnswer(art)} disabled={!!chosen}
              style={{ padding:'18px 8px',borderRadius:16,border:`2px solid ${isCorrect?ART_COLOR[art]:isWrong?'#E5484D':chosen?'#ddd':ART_COLOR[art]}`,
                background: isCorrect?ART_BG[art]:isWrong?'#E5484D10':chosen?'#f8f8fb':ART_BG[art],
                color: isCorrect?ART_COLOR[art]:isWrong?'#E5484D':chosen?'#bbb':ART_COLOR[art],
                fontWeight:800,fontSize:22,cursor:chosen?'default':'pointer',
                transition:'all .2s',
                transform: isPicked?'scale(1.04)':'scale(1)',
                boxShadow: isPicked?`0 4px 16px ${ART_COLOR[art]}44`:'none' }}>
              {art}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// ── WordMatch oyunu ────────────────────────────────────────────────────
function WordMatch({ lang = "ku", onBack }) {
  const LK = ['a1','b1','b2','c1','c2'];
  const LL = ['A1','B1','B2','C1','C2'];
  const LC = { ku:['هەموو','کردار','ناو','ڕەوانە'], tr:['Hepsi','Fiil','İsim','Sıfat'], en:['All','Verb','Noun','Adj.'], ar:['الكل','فعل','اسم','صفة'], uk:['Усі','Дієслово','Іменник','Прикм.'], fa:['همه','فعل','اسم','صفت'] ,"es":["Todos","Verbo","Nombre","Adj."],"fr":["Tous","Verbe","Nom","- Oui."]};
  const LCK = ['all','fiil','isim','sifat'];
  const WT = {
    ku:{ ref:'ئاستی بنچینە', match:'ئاستی دۆشان', cat:'جۆری وشە', start:'یاری دەست پێبکە', drag_here:'وشەی هاوتا ئێرەی بکێشە', correct:'دروستە ✓', wrong:'هەڵەیە ✗', next:'دواتر', finish:'کۆتایی', score:'ئەنجامت', of:' / ', restart:'دووبارە', back:'گەڕانەوە', ex:'نموونە', listen:'گوێ بگرە', lvl_same:'ئاستەکان دەبێت جیاوازبن', tap_hint:'کرتە بکە یان بکێشە' },
    tr:{ ref:'Referans seviye', match:'Eşleşme seviyesi', cat:'Kelime türü', start:'Oyunu başlat', drag_here:'Eş anlamlıyı sürükle', correct:'Doğru ✓', wrong:'Yanlış ✗', next:'İleri', finish:'Bitir', score:'Puanın', of:' / ', restart:'Tekrar', back:'Geri', ex:'Örnek', listen:'Dinle', lvl_same:'Seviyeler farklı olmalı', tap_hint:'Tıkla veya sürükle' },
    en:{ ref:'Reference level', match:'Match level', cat:'Word type', start:'Start game', drag_here:'Drag the synonym here', correct:'Correct ✓', wrong:'Wrong ✗', next:'Next', finish:'Finish', score:'Score', of:' / ', restart:'Restart', back:'Back', ex:'Example', listen:'Listen', lvl_same:'Levels must be different', tap_hint:'Tap or drag' },
    ar:{ ref:'المستوى المرجعي', match:'مستوى المطابقة', cat:'نوع الكلمة', start:'ابدأ اللعبة', drag_here:'اسحب الكلمة المرادفة', correct:'صحيح ✓', wrong:'خطأ ✗', next:'التالي', finish:'إنهاء', score:'نتيجتك', of:' / ', restart:'إعادة', back:'رجوع', ex:'مثال', listen:'استمع', lvl_same:'يجب أن تكون المستويات مختلفة', tap_hint:'انقر أو اسحب' },
  "es":{"ref":"Nivel de referencia","match":"Nivel de coincidencia","cat":"Tipo de palabra","start":"Iniciar juego","drag_here":"Arrastre el sinónimo aquí","correct":"Correcto ✓","wrong":"Equivocado #","next":"Siguiente","finish":"Terminar","score":"Puntuación","of":"/","restart":"Reiniciar","back":"Atrás","ex":"Ejemplo","listen":"Escucha.","lvl_same":"Los niveles deben ser diferentes","tap_hint":"Toque o arrastre"},"fr":{"ref":"Niveau de référence","match":"Niveau correspondant","cat":"Type de mot","start":"Démarrer le jeu","drag_here":"Faites glisser le synonyme ici","correct":"Corrigé ✓","wrong":"Erreur","next":"Suivant","finish":"Finition","score":"Score","of":"/","restart":"Redémarrer","back":"Précédent","ex":"Exemple","listen":"Écoute.","lvl_same":"Les niveaux doivent être différents","tap_hint":"Taper ou glisser"}};
  WT.uk = { ref:'Референсний рівень', match:'Рівень зіставлення', cat:'Тип слова', start:'Почати гру', drag_here:'Перетягніть синонім сюди', correct:'Правильно ✓', wrong:'Неправильно ✗', next:'Далі', finish:'Завершити', score:'Бали', of:' / ', restart:'Ще раз', back:'Назад', ex:'Приклад', listen:'Слухати', lvl_same:'Рівні мають відрізнятися', tap_hint:'Торкніться або перетягніть' };
  WT.fa = { ref:"سطح مرجع", match:"سطح تطبیق", cat:"نوع واژه", start:"شروع بازی", drag_here:"مترادف را اینجا بکش", correct:"درست ✓", wrong:"غلط ✗", next:"بعدی", finish:"پایان", score:"امتیاز", of:" / ", restart:"دوباره", back:"بازگشت", ex:"مثال", listen:"گوش دادن", lvl_same:"سطوح باید متفاوت باشند", tap_hint:"بزن یا بکش" };
  const wt = (k) => (WT[lang]||WT.tr)[k] || (WT.tr[k]||k);

  const [phase,      setPhase]     = useState('setup');
  const [lvl1,       setLvl1]      = useState(0);
  const [lvl2,       setLvl2]      = useState(2);
  const [categ,      setCateg]     = useState('all');
  const [questions,  setQuestions] = useState([]);
  const [poolData,   setPoolData]  = useState([]);
  const [qIdx,       setQIdx]      = useState(0);
  const [options,    setOptions]   = useState([]);
  const [dropResult, setDropResult]= useState(null);
  const [wrongGuess, setWrongGuess]= useState(null);
  const [score,      setScore]     = useState(0);
  const [, setDragging] = useState(null);

  const lc = (i) => ['#22c55e','#3b82f6','#6366f1','#f59e0b','#ef4444'][i];

  const getEx = (item, lk) => {
    const p = lk==='a1' ? '' : `_${lk}`;
    const de  = item[`ex${p}`] || '';
    const localizedKey = `ex${p}_${lang}`;
    const nat = lang === 'de' ? '' : (item[localizedKey] || '');
    return { de, nat: nat||'' };
  };

  const speak = (text) => {
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'de-DE'; u.rate = 0.85;
    window.speechSynthesis.speak(u);
  };

  const buildOpts = (qs, idx, pool, k2) => {
    const correct = qs[idx][k2];
    const wrongs  = pool.filter(d => d[k2] && d.id !== qs[idx].id)
                        .sort(() => Math.random()-0.5).slice(0,3).map(d => d[k2]);
    return [correct, ...wrongs].sort(() => Math.random()-0.5);
  };

  const startGame = () => {
    if (lvl1===lvl2) return;
    const k1=LK[lvl1], k2=LK[lvl2];
    let pool = categ==='fiil' ? FIIL_DATA : categ==='isim' ? ISIM_DATA : categ==='sifat' ? SIFAT_DATA : [...FIIL_DATA,...ISIM_DATA,...SIFAT_DATA];
    pool = pool.filter(d => d[k1] && d[k2]);
    const qs = [...pool].sort(() => Math.random()-0.5).slice(0, Math.min(10, pool.length));
    setPoolData(pool); setQuestions(qs); setQIdx(0); setScore(0);
    setDropResult(null); setWrongGuess(null);
    setOptions(buildOpts(qs, 0, pool, k2));
    setPhase('game');
  };

  const handleAnswer = (word) => {
    if (dropResult) return;
    const correct = questions[qIdx][LK[lvl2]];
    if (word===correct) { setDropResult('correct'); setScore(s=>s+1); }
    else { setDropResult('wrong'); setWrongGuess(word); }
  };

  const handleNext = () => {
    const nxt = qIdx+1;
    if (nxt >= questions.length) { setPhase('result'); return; }
    setQIdx(nxt); setDropResult(null); setWrongGuess(null);
    setOptions(buildOpts(questions, nxt, poolData, LK[lvl2]));
  };

  /* ── SETUP ── */
  if (phase==='setup') return (
    <div style={{ maxWidth:540, margin:'0 auto', padding:'8px 0' }}>
      <button onClick={onBack} style={{ background:'none',border:'none',color:'#888',cursor:'pointer',display:'flex',alignItems:'center',gap:6,fontSize:14,marginBottom:20 }}>← {wt('back')}</button>
      <div style={{ textAlign:'center', marginBottom:24 }}>
        <div style={{ fontSize:40 }}>🃏</div>
        <div style={{ fontWeight:800, fontSize:22, marginTop:8 }}>{tSpiel(lang,'wm_name')}</div>
        <div style={{ fontSize:13, color:'#888', marginTop:4 }}>{tSpiel(lang,'wm_desc')}</div>
      </div>
      {/* Level 1 */}
      <div style={{ background:'#fff',borderRadius:16,padding:18,marginBottom:10,border:'1px solid #ebebf0' }}>
        <div style={{ fontSize:12,fontWeight:700,color:'#888',letterSpacing:'.06em',marginBottom:10 }}>{wt('ref')}</div>
        <div style={{ display:'flex',gap:8,flexWrap:'wrap' }}>
          {LK.map((k,i)=>(
            <button key={k} onClick={()=>setLvl1(i)}
              style={{ padding:'8px 18px',borderRadius:10,border:`2px solid ${lvl1===i?lc(i):'#ddd'}`,background:lvl1===i?`${lc(i)}15`:'#fff',color:lvl1===i?lc(i):'#555',fontWeight:700,fontSize:15,cursor:'pointer',transition:'all .15s' }}>
              {LL[i]}
            </button>
          ))}
        </div>
      </div>
      {/* Level 2 */}
      <div style={{ background:'#fff',borderRadius:16,padding:18,marginBottom:10,border:'1px solid #ebebf0' }}>
        <div style={{ fontSize:12,fontWeight:700,color:'#888',letterSpacing:'.06em',marginBottom:10 }}>{wt('match')}</div>
        <div style={{ display:'flex',gap:8,flexWrap:'wrap' }}>
          {LK.map((k,i)=>(
            <button key={k} onClick={()=>setLvl2(i)}
              style={{ padding:'8px 18px',borderRadius:10,border:`2px solid ${lvl2===i?lc(i):'#ddd'}`,background:lvl2===i?`${lc(i)}15`:'#fff',color:lvl2===i?lc(i):'#555',fontWeight:700,fontSize:15,cursor:'pointer',transition:'all .15s' }}>
              {LL[i]}
            </button>
          ))}
        </div>
      </div>
      {/* Category */}
      <div style={{ background:'#fff',borderRadius:16,padding:18,marginBottom:20,border:'1px solid #ebebf0' }}>
        <div style={{ fontSize:12,fontWeight:700,color:'#888',letterSpacing:'.06em',marginBottom:10 }}>{wt('cat')}</div>
        <div style={{ display:'flex',gap:8,flexWrap:'wrap' }}>
          {LCK.map((k,i)=>(
            <button key={k} onClick={()=>setCateg(k)}
              style={{ padding:'8px 16px',borderRadius:10,border:`2px solid ${categ===k?'#5B5BD6':'#ddd'}`,background:categ===k?'rgba(91,91,214,.1)':'#fff',color:categ===k?'#5B5BD6':'#555',fontWeight:600,fontSize:14,cursor:'pointer',transition:'all .15s' }}>
              {(LC[lang]||LC.tr)[i]}
            </button>
          ))}
        </div>
      </div>
      {lvl1===lvl2 && <div style={{ color:'#E5484D',fontSize:13,textAlign:'center',marginBottom:10 }}>{wt('lvl_same')}</div>}
      <button onClick={startGame} disabled={lvl1===lvl2}
        style={{ width:'100%',padding:'14px',borderRadius:14,border:'none',background:lvl1===lvl2?'#ccc':'linear-gradient(135deg,#5B5BD6,#7c3aed)',color:'#fff',fontWeight:700,fontSize:16,cursor:lvl1===lvl2?'not-allowed':'pointer' }}>
        {wt('start')} →
      </button>
    </div>
  );

  /* ── RESULT ── */
  if (phase==='result') {
    const pct = Math.round((score/questions.length)*100);
    return (
      <div style={{ maxWidth:480,margin:'0 auto',textAlign:'center',padding:'32px 0' }}>
        <div style={{ fontSize:56 }}>{pct>=70?'🏆':pct>=40?'👍':'💪'}</div>
        <div style={{ fontWeight:800,fontSize:22,margin:'16px 0 6px' }}>{wt('score')}</div>
        <div style={{ fontSize:52,fontWeight:900,color:'#5B5BD6',lineHeight:1 }}>{score}<span style={{ fontSize:22,color:'#aaa' }}>{wt('of')}{questions.length}</span></div>
        <div style={{ fontSize:24,marginTop:6,color:pct>=70?'#30A46C':'#F76B15',fontWeight:700 }}>{pct}%</div>
        <div style={{ display:'flex',gap:12,marginTop:32,justifyContent:'center' }}>
          <button onClick={()=>setPhase('setup')} style={{ padding:'12px 28px',borderRadius:12,border:'1px solid #ddd',background:'#fff',fontWeight:600,fontSize:15,cursor:'pointer' }}>{wt('back')}</button>
          <button onClick={startGame} style={{ padding:'12px 28px',borderRadius:12,border:'none',background:'linear-gradient(135deg,#5B5BD6,#7c3aed)',color:'#fff',fontWeight:700,fontSize:15,cursor:'pointer' }}>{wt('restart')}</button>
        </div>
      </div>
    );
  }

  /* ── GAME ── */
  const q = questions[qIdx];
  const k1 = LK[lvl1], k2 = LK[lvl2];
  const refWord = q[k1], correctWord = q[k2];
  const exRef   = getEx(q, k1);
  const exMatch = getEx(q, k2);

  return (
    <div style={{ maxWidth:540, margin:'0 auto' }}>
      {/* Progress bar */}
      <div style={{ display:'flex',alignItems:'center',gap:12,marginBottom:20 }}>
        <button onClick={()=>setPhase('setup')} style={{ background:'none',border:'none',color:'#888',cursor:'pointer',fontSize:18 }}>←</button>
        <div style={{ flex:1,height:7,background:'#ebebf0',borderRadius:4 }}>
          <div style={{ height:'100%',width:`${(qIdx/questions.length)*100}%`,background:'linear-gradient(90deg,#5B5BD6,#7c3aed)',borderRadius:4,transition:'width .4s' }} />
        </div>
        <div style={{ fontSize:13,color:'#888',whiteSpace:'nowrap',fontWeight:600 }}>{qIdx+1}/{questions.length}</div>
      </div>

      {/* Reference word */}
      <div style={{ background:'linear-gradient(135deg,#5B5BD6,#7c3aed)',borderRadius:20,padding:'22px 20px',marginBottom:14,color:'#fff' }}>
        <div style={{ fontSize:11,fontWeight:700,opacity:.65,letterSpacing:'.1em',marginBottom:6 }}>{LL[lvl1]}</div>
        <div style={{ display:'flex',alignItems:'center',gap:10 }}>
          <div style={{ fontSize:34,fontWeight:900,flex:1,lineHeight:1.15 }}>{refWord}</div>
          <button onClick={()=>speak(refWord)} style={{ width:38,height:38,borderRadius:10,border:'none',background:'rgba(255,255,255,.2)',color:'#fff',cursor:'pointer',fontSize:17 }}>🔊</button>
        </div>
        {exRef.de && (
          <div style={{ marginTop:12,fontSize:13,borderTop:'1px solid rgba(255,255,255,.2)',paddingTop:10 }}>
            <div style={{ fontStyle:'italic',opacity:.9 }}>{exRef.de}</div>
            {exRef.nat && <div style={{ marginTop:3,opacity:.65,fontSize:12 }}>{exRef.nat}</div>}
          </div>
        )}
      </div>

      {/* Drop zone */}
      <div
        onDragOver={e=>e.preventDefault()}
        onDrop={e=>{ e.preventDefault(); handleAnswer(e.dataTransfer.getData('word')); }}
        style={{ border:`2px dashed ${dropResult==='correct'?'#30A46C':dropResult==='wrong'?'#E5484D':'#5B5BD6'}`,
          borderRadius:16,padding:'16px 18px',marginBottom:16,
          background:dropResult==='correct'?'#30A46C0e':dropResult==='wrong'?'#E5484D0e':'rgba(91,91,214,.04)',
          textAlign:'center',minHeight:68,display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:5,
          transition:'all .25s' }}>
        {!dropResult && <>
          <div style={{ fontSize:13,color:'#5B5BD6',fontWeight:600 }}>{wt('drag_here')}</div>
          <div style={{ fontSize:11,color:'#bbb' }}>{LL[lvl1]} → {LL[lvl2]} · {wt('tap_hint')}</div>
        </>}
        {dropResult==='correct' && <>
          <div style={{ fontSize:24,color:'#30A46C',fontWeight:800 }}>{correctWord}</div>
          <div style={{ fontSize:13,color:'#30A46C',fontWeight:600 }}>{wt('correct')}</div>
          {exMatch.de && <div style={{ fontSize:12,color:'#555',fontStyle:'italic',marginTop:4 }}>{exMatch.de}</div>}
          {exMatch.nat && <div style={{ fontSize:11,color:'#888' }}>{exMatch.nat}</div>}
          <button onClick={()=>speak(correctWord)} style={{ marginTop:6,padding:'4px 14px',borderRadius:8,border:'1px solid #30A46C44',background:'#30A46C10',color:'#30A46C',cursor:'pointer',fontSize:12 }}>🔊 {wt('listen')}</button>
        </>}
        {dropResult==='wrong' && <>
          <div style={{ fontSize:13,color:'#E5484D',fontWeight:600 }}>{wt('wrong')}</div>
          <div style={{ fontSize:12,color:'#555' }}>✓ <strong>{correctWord}</strong></div>
          <button onClick={()=>speak(correctWord)} style={{ marginTop:4,padding:'3px 12px',borderRadius:8,border:'1px solid #ddd',background:'#fff',cursor:'pointer',fontSize:11 }}>🔊 {correctWord}</button>
        </>}
      </div>

      {/* Option cards */}
      <div style={{ display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:18 }}>
        {options.map((word,i)=>{
          const isOk   = dropResult==='correct' && word===correctWord;
          const isBad  = dropResult==='wrong'   && word===wrongGuess;
          const reveal = dropResult==='wrong'   && word===correctWord;
          return (
            <div key={i}
              draggable={!dropResult}
              onDragStart={e=>{ e.dataTransfer.setData('word',word); setDragging(word); }}
              onDragEnd={()=>setDragging(null)}
              onClick={()=>handleAnswer(word)}
              style={{ background:isOk?'#30A46C12':reveal?'#30A46C08':isBad?'#E5484D10':'#fff',
                border:`2px solid ${isOk?'#30A46C':reveal?'#30A46C55':isBad?'#E5484D':'#ebebf0'}`,
                borderRadius:14,padding:'15px 12px',textAlign:'center',
                cursor:dropResult?'default':'grab',
                opacity:dropResult&&!isOk&&!isBad&&!reveal?.45:1,
                transition:'all .2s',userSelect:'none',
                display:'flex',flexDirection:'column',alignItems:'center',gap:8 }}>
              <div style={{ fontSize:15,fontWeight:700,color:'#1a1a2e',lineHeight:1.3,wordBreak:'break-word' }}>{word}</div>
              <button onClick={e=>{e.stopPropagation();speak(word);}}
                style={{ padding:'3px 10px',borderRadius:7,border:'1px solid #eee',background:'#f8f8fb',cursor:'pointer',fontSize:11,color:'#666' }}>🔊</button>
            </div>
          );
        })}
      </div>

      {/* Next */}
      {dropResult && (
        <button onClick={handleNext}
          style={{ width:'100%',padding:'14px',borderRadius:14,border:'none',background:'linear-gradient(135deg,#5B5BD6,#7c3aed)',color:'#fff',fontWeight:700,fontSize:16,cursor:'pointer' }}>
          {qIdx+1>=questions.length ? wt('finish') : wt('next')} →
        </button>
      )}
    </div>
  );
}

