const BOOK_DICT_KEYS = Object.keys(BOOK_DICT);

// ── Chapter quiz engine ──────────────────────────────────────────────────
// Extracts every BOOK_DICT word that actually appears in a chapter's narrative/dialogue
// lines (same tokenization renderWithDict uses), then builds a multiple-choice quiz from them.
function extractChapterWords(scenes) {
  const seen = new Set();
  const words = [];
  for (const scene of scenes) {
    for (const line of scene.lines || []) {
      if (line.t !== 'n' && line.t !== 'd') continue;
      if (!line.s) continue;
      for (const part of line.s.split(/\s+/)) {
        const clean = part.replace(/[.,!?;:"„"«»''()[\]]+/g, '').toLowerCase();
        if (!clean || seen.has(clean)) continue;
        const entry = BOOK_DICT[clean];
        if (!entry) continue;
        seen.add(clean);
        words.push({ word: part.replace(/[.,!?;:"„"«»''()[\]]+/g, ''), key: clean, entry });
      }
    }
  }
  return words;
}

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildChapterQuiz(scenes, lang = 'tr') {
  const chapterWords = shuffle(extractChapterWords(scenes)).slice(0, 10);
  const tField = ['ku', 'tr', 'en', 'ar', 'uk', 'fa', 'es', 'fr'].includes(lang) ? lang : 'tr';

  return chapterWords.map(({ word, key, entry }) => {
    const isNoun = entry.type === 'noun' && entry.article;
    const types = isNoun ? ['meaning', 'spelling', 'artikel'] : ['meaning', 'spelling'];
    const qType = types[Math.floor(Math.random() * types.length)];

    if (qType === 'artikel') {
      return { type: 'artikel', word, prompt: word, options: ['der', 'die', 'das'], correctIndex: ['der', 'die', 'das'].indexOf(entry.article) };
    }

    if (qType === 'meaning') {
      const others = shuffle(BOOK_DICT_KEYS.filter(k => k !== key)).slice(0, 2).map(k => BOOK_DICT[k][tField]);
      const options = shuffle([entry[tField], ...others]);
      return { type: 'meaning', word, prompt: word, options, correctIndex: options.indexOf(entry[tField]) };
    }

    // spelling: prefer same-type distractors for plausibility, fall back to any
    const sameType = BOOK_DICT_KEYS.filter(k => k !== key && BOOK_DICT[k].type === entry.type);
    const pool = sameType.length >= 2 ? sameType : BOOK_DICT_KEYS.filter(k => k !== key);
    const others = shuffle(pool).slice(0, 2).map(k => (BOOK_DICT[k].article ? BOOK_DICT[k].article + ' ' : '') + k);
    const correctLabel = (entry.article ? entry.article + ' ' : '') + key;
    const options = shuffle([correctLabel, ...others]);
    return { type: 'spelling', word, prompt: entry[tField], options, correctIndex: options.indexOf(correctLabel) };
  });
}

// ── ChapterQuiz — end-of-chapter comprehension gate ─────────────────────
const CHAPTER_QUIZ_T = {
  tr: { title: 'Bölüm Testi', question: 'Soru', artikel_q: 'der, die yoksa das?', meaning_q: 'Anlamı ne?', spelling_q: 'Almancası ne?', correct: 'Doğru!', wrong: 'Yanlış!', pass: 'Geçtin!', fail: 'Bu sefer olmadı', passSub: 'sorudan doğru — kart kazandın!', failSub: 'sorudan doğru — 8 gerekiyor. Tekrar dene!', retry: 'Tekrar Dene', continueBtn: 'Devam Et' },
  ku: { title: 'تاقیکردنەوەی بەش', question: 'پرسیار', artikel_q: 'der، die یان das؟', meaning_q: 'واتای چیە؟', spelling_q: 'بە ئەڵمانی چۆنە؟', correct: 'ڕاستە!', wrong: 'هەڵەیە!', pass: 'دەرچوویت!', fail: 'ئەم جارە نا', passSub: 'وەڵامی ڕاست — کارتێکت بەدەستهێنا!', failSub: 'وەڵامی ڕاست — پێویستە بە ٨. دووبارە هەوڵبدەرەوە!', retry: 'دووبارە هەوڵبدەرەوە', continueBtn: 'بەردەوامبە' },
  en: { title: 'Chapter Test', question: 'Question', artikel_q: 'der, die or das?', meaning_q: 'What does it mean?', spelling_q: 'What is it in German?', correct: 'Correct!', wrong: 'Wrong!', pass: 'You passed!', fail: 'Not this time', passSub: 'correct — you earned a card!', failSub: 'correct — need 8. Try again!', retry: 'Try Again', continueBtn: 'Continue' },
  ar: { title: 'اختبار الفصل', question: 'سؤال', artikel_q: 'der أم die أم das؟', meaning_q: 'ما المعنى؟', spelling_q: 'كيف تقال بالألمانية؟', correct: 'صحيح!', wrong: 'خطأ!', pass: 'لقد نجحت!', fail: 'ليس هذه المرة', passSub: 'صحيحة — لقد ربحت بطاقة!', failSub: 'صحيحة — تحتاج 8. حاول مرة أخرى!', retry: 'حاول مرة أخرى', continueBtn: 'متابعة' },
  uk: { title: 'Тест розділу', question: 'Питання', artikel_q: 'der, die чи das?', meaning_q: 'Що це означає?', spelling_q: 'Як це німецькою?', correct: 'Правильно!', wrong: 'Неправильно!', pass: 'Ти склав!', fail: 'Не цього разу', passSub: 'правильних — ти отримав картку!', failSub: 'правильних — потрібно 8. Спробуй ще раз!', retry: 'Спробувати ще раз', continueBtn: 'Продовжити' },
  fa: { title: 'آزمون فصل', question: 'سؤال', artikel_q: 'der، die یا das؟', meaning_q: 'یعنی چه؟', spelling_q: 'به آلمانی چه می‌شود؟', correct: 'درست!', wrong: 'غلط!', pass: 'قبول شدی!', fail: 'این بار نشد', passSub: 'درست — یک کارت گرفتی!', failSub: 'درست — به ۸ نیاز داری. دوباره تلاش کن!', retry: 'دوباره تلاش کن', continueBtn: 'ادامه' },
"es":{"title":"Capítulo Prueba","question":"Pregunta","artikel_q":"¿Muere o muere?","meaning_q":"¿Qué significa?","spelling_q":"¿Qué es en alemán?","correct":"¡Correcto!","wrong":"¡Equivocado!","pass":"¡Pasaste!","fail":"Esta vez no.","passSub":"correcto — ¡te ganaste una tarjeta!","failSub":"Correcto — necesidad 8. ¡Inténtalo de nuevo!","retry":"Inténtalo de nuevo","continueBtn":"Continuar"},"fr":{"title":"Essai de chapitre","question":"Question","artikel_q":"Der, mourir ou das?","meaning_q":"Qu'est-ce que ça veut dire?","spelling_q":"Qu'est-ce qu'il y a en allemand?","correct":"C'est exact!","wrong":"Faux!","pass":"Vous êtes passé!","fail":"Pas cette fois.","passSub":"correcte — vous avez gagné une carte!","failSub":"Réessayez!","retry":"Essayez encore","continueBtn":"Continuer"}};
function ChapterQuiz({ scenes, lang = 'tr', onPass, onCancel }) {
  const t = (k) => CHAPTER_QUIZ_T[lang]?.[k] ?? CHAPTER_QUIZ_T.tr[k];
  const [quiz, setQuiz] = useState(() => buildChapterQuiz(scenes, lang));
  const [qIdx, setQIdx] = useState(0);
  const [chosen, setChosen] = useState(null);
  const [correctCount, setCorrectCount] = useState(0);
  const [done, setDone] = useState(false);

  const total = quiz.length;
  const needed = Math.ceil(total * 0.8);
  const q = quiz[qIdx];

  const pick = (i) => {
    if (chosen !== null) return;
    setChosen(i);
    const isCorrect = i === q.correctIndex;
    if (isCorrect) setCorrectCount(c => c + 1);
    setTimeout(() => {
      if (qIdx + 1 < total) {
        setQIdx(qIdx + 1);
        setChosen(null);
      } else {
        setDone(true);
      }
    }, 900);
  };

  const passed = done && correctCount >= needed;

  const retry = () => {
    setQuiz(buildChapterQuiz(scenes, lang));
    setQIdx(0);
    setChosen(null);
    setCorrectCount(0);
    setDone(false);
  };

  const qLabel = q?.type === 'artikel' ? t('artikel_q') : q?.type === 'meaning' ? t('meaning_q') : t('spelling_q');

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 99997, background: '#fdf6e8', display: 'flex', flexDirection: 'column' }}>
      <div style={{ flexShrink: 0, position: 'relative', padding: '18px 22px 14px', borderBottom: '1px solid rgba(180,130,60,.18)', textAlign: 'center' }}>
        {onCancel && (
          <button onClick={onCancel} style={{ position: 'absolute', left: 18, top: 16, background: 'transparent', border: 'none', color: '#8B6030', fontSize: 15, cursor: 'pointer', fontFamily: 'Georgia,serif' }}>
            {lang === 'ku' ? 'گەران ←' : lang === 'uk' ? '← Назад' : lang === 'en' ? '← Back' : lang === 'ar' ? 'رجوع ←' : '← Geri'}
          </button>
        )}
        <div style={{ fontSize: 13, fontWeight: 800, color: '#8B6030', fontFamily: 'Georgia,serif' }}>{t('title')}</div>
        {!done && <div style={{ fontSize: 11, color: '#b08050', marginTop: 2 }}>{t('question')} {qIdx + 1} / {total}</div>}
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '28px 24px', display: 'flex', flexDirection: 'column' }}>
        {!done && q && (
          <>
            <div style={{ fontSize: 12, color: '#9a7040', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '.06em', marginBottom: 10, textAlign: 'center' }}>{qLabel}</div>
            <div style={{ fontSize: 28, fontWeight: 800, color: '#2c1408', textAlign: 'center', marginBottom: 32, fontFamily: 'Georgia,serif' }}>{q.prompt}</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 12, maxWidth: 420, margin: '0 auto', width: '100%' }}>
              {q.options.map((opt, i) => {
                const isChosen = chosen === i;
                const isCorrectOpt = chosen !== null && i === q.correctIndex;
                const isWrongChosen = isChosen && i !== q.correctIndex;
                return (
                  <button key={i} onClick={() => pick(i)} disabled={chosen !== null} style={{
                    padding: '16px 20px', borderRadius: 14, fontSize: 16, fontWeight: 700, textAlign: 'left',
                    cursor: chosen === null ? 'pointer' : 'default', fontFamily: 'Georgia,serif',
                    border: isCorrectOpt ? '2px solid #30A46C' : isWrongChosen ? '2px solid #E5484D' : '1.5px solid rgba(180,130,60,.3)',
                    background: isCorrectOpt ? 'rgba(48,164,108,.12)' : isWrongChosen ? 'rgba(229,72,77,.1)' : '#fff',
                    color: isCorrectOpt ? '#1B5E20' : isWrongChosen ? '#8B1A1A' : '#2c1408',
                    transition: 'all .15s',
                  }}>
                    {opt}{isCorrectOpt ? ' ✓' : isWrongChosen ? ' ✗' : ''}
                  </button>
                );
              })}
            </div>
          </>
        )}

        {done && (
          <div style={{ textAlign: 'center', margin: 'auto', maxWidth: 340 }}>
            <div style={{ fontSize: 52, marginBottom: 12 }}>{passed ? '🎉' : '📚'}</div>
            <div style={{ fontSize: 22, fontWeight: 800, color: passed ? '#1B5E20' : '#8B1A1A', fontFamily: 'Georgia,serif', marginBottom: 8 }}>
              {passed ? t('pass') : t('fail')}
            </div>
            <div style={{ fontSize: 14, color: '#6B4A2A', marginBottom: 24 }}>
              {correctCount}/{total} {passed ? t('passSub') : t('failSub')}
            </div>
            {passed ? (
              <button onClick={onPass} style={{ background: 'linear-gradient(135deg,#5B5BD6,#7c3aed)', color: '#fff', border: 'none', borderRadius: 14, padding: '14px 32px', fontWeight: 800, fontSize: 15, cursor: 'pointer' }}>{t('continueBtn')}</button>
            ) : (
              <button onClick={retry} style={{ background: 'linear-gradient(135deg,#f7971e,#f5576c)', color: '#fff', border: 'none', borderRadius: 14, padding: '14px 32px', fontWeight: 800, fontSize: 15, cursor: 'pointer' }}>{t('retry')}</button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ── JourneyScreen ──────────────────────────────────────────────────────
// ── BookReaderModal — premium full-screen page-flip story reader ───────────
function BookReaderModal({ scenes, onClose, userName, userLang }) {
  const [page, setPage] = useState(0);
  const [flipping, setFlipping] = useState(false);
  const [flipDir, setFlipDir] = useState(null);
  const [dictEntry, setDictEntry] = useState(null);
  const [favWords, setFavWords] = useState(() => {
    try { return new Set(JSON.parse(localStorage.getItem('fuxi_favs') || '[]').map(f => f.de.toLowerCase())); }
    catch { return new Set(); }
  });
  const [sessionWords, setSessionWords] = useState([]); // words tapped during THIS reading session, for the end-of-chapter summary
  const toggleFavWord = (de, entry) => {
    const stored = (() => { try { return JSON.parse(localStorage.getItem('fuxi_favs') || '[]'); } catch { return []; } })();
    const key = de.toLowerCase();
    const exists = stored.some(f => f.de.toLowerCase() === key);
    const next = exists
      ? stored.filter(f => f.de.toLowerCase() !== key)
      : [...stored, { de, ku: entry.ku || '', tr: entry.tr || '', en: entry.en || '', ar: entry.ar || '', uk: entry.uk || '', fa: entry.fa || '', ex: entry.ex || '', exku: entry.ex_ku || '', extr: entry.ex_tr || '', exen: entry.ex_en || '', exar: entry.ex_ar || '', exuk: entry.ex_uk || '', exfa: entry.ex_fa || '' }];
    localStorage.setItem('fuxi_favs', JSON.stringify(next));
    setFavWords(prev => { const s = new Set(prev); if (exists) s.delete(key); else s.add(key); return s; });
  };
  const touchStartX = useRef(0);
  const touchStartY = useRef(0);
  const flipTimer = useRef(null);
  const FLIP_MS = 620;
  const total = scenes.length;

  const go = dir => {
    if (flipping) return;
    if (dir === 'fwd' && page >= total - 1) return;
    if (dir === 'bwd' && page <= 0) return;
    clearTimeout(flipTimer.current);
    setFlipDir(dir);
    setFlipping(true);
    if (window.navigator && window.navigator.vibrate) window.navigator.vibrate(8);
    flipTimer.current = setTimeout(() => {
      setPage(p => dir === 'fwd' ? p + 1 : p - 1);
      setFlipping(false);
      setFlipDir(null);
    }, FLIP_MS);
  };

  const bgScene = flipping ? scenes[flipDir === 'fwd' ? page + 1 : page - 1] : scenes[page];
  const fgScene = scenes[page];

  const resolveName = s => s.replace(/\[N\]/g, userName);

  const charColor = who => {
    const w = (who || '').replace(/\[N\]/g, userName);
    if (w === userName) return '#7B3F00';
    if (w.startsWith('Stefan')) return '#1B5E20';
    if (w === 'Klaus') return '#8B4513';
    if (w.startsWith('Frau')) return '#1A237E';
    if (w === 'Lisa') return '#880E4F';
    if (w === 'Maria') return '#6A1B9A';
    if (w === 'Anne') return '#AD1457';
    if (w === 'Alle') return '#455A64';
    return '#4A3520';
  };

  const WHO_KU = { 'Anne':'دایک', 'Hostes':'میهماندار', 'Alle':'هەموو کەس', 'Chef Klaus':'Chef Klaus' };
  const resolveWho = who => {
    const base = resolveName(who || '');
    return userLang === 'ku' ? (WHO_KU[base] || base) : base;
  };

  const renderWithDict = (text, seenSet) => {
    if (!text) return text;
    return text.split(/(\s+)/).map((part, i) => {
      if (/^\s+$/.test(part)) return part;
      const clean = part.replace(/[.,!?;:"„"«»''()[\]]+/g, '').toLowerCase();
      const entry = BOOK_DICT[clean];
      if (!entry || seenSet.has(clean)) return <span key={i}>{part}</span>;
      seenSet.add(clean);
      return (
        <span key={i}
          onClick={(e) => {
            e.stopPropagation();
            const r = e.currentTarget.getBoundingClientRect();
            const cleanWord = part.replace(/[.,!?;:"„"«»''()[\]]+/g, '');
            setDictEntry({ word: cleanWord, ...entry, _x: r.left, _y: r.bottom });
            setSessionWords(prev => prev.includes(cleanWord) ? prev : [...prev, cleanWord]);
          }}
          style={{ borderBottom: '1.5px dotted #5B5BD6', color: '#3D37A8', cursor: 'pointer', fontStyle: 'inherit' }}>
          {part}
        </span>
      );
    });
  };

  const renderLine = (line, i, seenSet) => {
    // Pick narration text by UI language: ku→s_ku (no dict), en→s_en, ar→s_ar (rtl), else Turkish s. German learning-words stay embedded so the tap-word dictionary keeps working for tr/en/ar.
    let raw = line.s, rtl = false, useDict = true, langLabel = line.lang;
    if (userLang === 'ku' && line.s_ku) { raw = line.s_ku; rtl = true; useDict = false; langLabel = 'کوردی'; }
    else if (userLang === 'en' && line.s_en) { raw = line.s_en; rtl = false; useDict = true; langLabel = 'English'; }
    else if (userLang === 'ar' && line.s_ar) { raw = line.s_ar; rtl = true; useDict = true; langLabel = 'العربية'; }
    else if (userLang === 'uk' && line.s_uk) { raw = line.s_uk; rtl = false; useDict = true; langLabel = 'Українська'; }
    else if (userLang === 'fa' && line.s_fa) { raw = line.s_fa; rtl = true; useDict = true; langLabel = 'فارسی'; }
    else if (userLang === 'es' && line.s_es) { raw = line.s_es; rtl = false; useDict = true; langLabel = 'Español'; }
    const s = resolveName(raw);
    const rtlStyle = rtl ? { direction:'rtl', textAlign:'right' } : {};
    const body = useDict ? renderWithDict(s, seenSet) : s;
    if (line.t === 'n') return (
      <p key={i} style={{ margin: '0 0 14px', fontSize: 15, color: '#2c1a08', lineHeight: 1.82, fontFamily: 'Georgia,serif', ...rtlStyle }}>
        {body}
      </p>
    );
    if (line.t === 'd') return (
      <div key={i} style={{ marginBottom: 14, display: 'flex', gap: 10, alignItems: 'flex-start', direction: 'ltr' }}>
        <span style={{ fontWeight: 700, fontSize: 12.5, color: charColor(line.who), flexShrink: 0, minWidth: 58, paddingTop: 3.5, fontStyle: 'italic', letterSpacing: '.01em', fontFamily: 'Georgia,serif', direction: 'ltr' }}>
          {resolveWho(line.who)}:
        </span>
        <span style={{ fontSize: 15, color: '#1a0e04', lineHeight: 1.78, fontFamily: 'Georgia,serif', direction: 'ltr' }}>
          &ldquo;{body}&rdquo;
        </span>
      </div>
    );
    if (line.t === 'i') {
      return (
        <div key={i} style={{ margin: '4px 0 14px', padding: '10px 14px', background: 'rgba(120,80,30,.08)', borderRadius: 10, borderLeft: '3px solid rgba(180,120,50,.35)' }}>
          <div style={{ fontSize: 10, color: '#9a7040', fontWeight: 700, marginBottom: 4, textTransform: 'uppercase', letterSpacing: '.07em', fontFamily: 'Georgia,serif', direction: 'ltr' }}>
            💭 {resolveWho(line.who)} ({langLabel})
          </div>
          <div style={{ fontSize: 14, color: '#4a2e10', fontStyle: 'italic', lineHeight: 1.78, fontFamily: 'Georgia,serif', ...rtlStyle }}>{s}</div>
        </div>
      );
    }
    if (line.t === 'sms') {
      return (
        <div key={i} style={{ margin: '4px 0 14px', padding: '10px 14px', background: 'rgba(50,120,50,.08)', borderRadius: 12, borderLeft: '3px solid rgba(50,150,50,.3)', ...rtlStyle }}>
          <div style={{ fontSize: 11, color: '#2a7a2a', fontWeight: 700, marginBottom: 3, fontFamily: 'Georgia,serif', direction: 'ltr', textAlign: 'left' }}>📱 {resolveWho(line.who)} (SMS)</div>
          <div style={{ fontSize: 14, color: '#1a3a1a', lineHeight: 1.7, fontFamily: 'Georgia,serif', ...rtlStyle }}>{s}</div>
        </div>
      );
    }
    if (line.t === 'sys') return (
      <div key={i} style={{ textAlign: 'center', margin: '4px 0 14px' }}>
        <span style={{ fontSize: 12, color: '#7a6040', fontStyle: 'italic', background: 'rgba(0,0,0,.045)', padding: '4px 12px', borderRadius: 8, fontFamily: 'Georgia,serif' }}>🔊 {s}</span>
      </div>
    );
    return null;
  };

  const PageView = ({ scene }) => (
    <div style={{ position: 'absolute', inset: 0, overflowY: 'auto', overflowX: 'hidden', background: 'linear-gradient(170deg,#fef9f0 0%,#fdf4e2 55%,#faf0d6 100%)' }}>
      {/* Paper ruled lines */}
      <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', backgroundImage: 'repeating-linear-gradient(180deg,transparent 0px,transparent 27px,rgba(150,100,30,.055) 28px)', zIndex: 0 }} />
      {/* Vignette */}
      <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 1, background: 'radial-gradient(ellipse at 50% 50%, transparent 55%, rgba(0,0,0,.07) 100%)' }} />
      {/* Content */}
      <div style={{ position: 'relative', zIndex: 2, fontFamily: 'Georgia,serif' }}>
        <div style={{ padding: '20px 26px 0' }}>
          {/* Scene header */}
          <div style={{ marginBottom: scene.img ? 14 : 22, paddingBottom: scene.img ? 10 : 14, borderBottom: '1.5px solid rgba(180,130,60,.22)' }}>
            <div style={{ fontSize: 10, color: '#7A5C30', fontWeight: 700, letterSpacing: '.15em', textTransform: 'uppercase', marginBottom: 5 }}>
              {userLang === 'ku' ? 'سەحنە' : userLang === 'en' ? 'Scene' : userLang === 'ar' ? 'المشهد' : userLang === 'uk' ? 'Сцена' : userLang === 'fa' ? 'صحنه' : userLang === "fr" ? "Scène" : 'Sahne'} {scene.n} / {total}
            </div>
            <div style={{ fontSize: 20, fontWeight: 700, color: '#2c1408', lineHeight: 1.32 }}>{scene.title}</div>
          </div>
        </div>
        {/* Scene image */}
        {scene.img && (
          <img src={scene.img} alt={scene.title} style={{ width: '100%', aspectRatio: '16/9', objectFit: 'cover', display: 'block' }} />
        )}
        <div style={{ padding: '18px 26px 100px' }}>
          {scene.place && (
            <div style={{ fontSize: 12.5, color: '#6B4A2A', fontStyle: 'italic', marginBottom: 18, lineHeight: 1.55 }}>📍 {scene['place_' + userLang] || (userLang === 'ku' && scene.place_ku ? scene.place_ku : scene.place)}</div>
          )}
          {(() => { const ss = new Set(); return scene.lines.map((l, i) => renderLine(l, i, ss)); })()}
        </div>
      </div>
    </div>
  );

  return (
    <>
      <style>{`
        @keyframes brFlipFwd {
          0%   { transform:perspective(1200px) rotateY(0deg)    translateZ(2px);  box-shadow: 4px 0 20px rgba(0,0,0,.12); }
          20%  { transform:perspective(1200px) rotateY(-35deg)  translateZ(8px);  box-shadow:10px 0 32px rgba(0,0,0,.18); }
          50%  { transform:perspective(1200px) rotateY(-90deg)  translateZ(12px); box-shadow:18px 0 48px rgba(0,0,0,.25); }
          80%  { transform:perspective(1200px) rotateY(-145deg) translateZ(6px);  box-shadow: 8px 0 24px rgba(0,0,0,.14); }
          100% { transform:perspective(1200px) rotateY(-180deg) translateZ(0px);  box-shadow:none; visibility:hidden; }
        }
        @keyframes brFlipBwd {
          0%   { transform:perspective(1200px) rotateY(0deg)    translateZ(2px);  box-shadow:-4px 0 20px rgba(0,0,0,.12); }
          20%  { transform:perspective(1200px) rotateY(35deg)   translateZ(8px);  box-shadow:-10px 0 32px rgba(0,0,0,.18); }
          50%  { transform:perspective(1200px) rotateY(90deg)   translateZ(12px); box-shadow:-18px 0 48px rgba(0,0,0,.25); }
          80%  { transform:perspective(1200px) rotateY(145deg)  translateZ(6px);  box-shadow:-8px 0 24px rgba(0,0,0,.14); }
          100% { transform:perspective(1200px) rotateY(180deg)  translateZ(0px);  box-shadow:none; visibility:hidden; }
        }
        @keyframes brBgReveal {
          0%   { filter:brightness(.82); }
          100% { filter:brightness(1); }
        }
        @keyframes brShadowSweep {
          0%   { opacity:0; }
          40%  { opacity:1; }
          100% { opacity:0; }
        }
      `}</style>

      <div
        style={{ position: 'fixed', inset: 0, zIndex: 2000, background: '#fdf6e8', overflow: 'hidden', userSelect: 'none', WebkitUserSelect: 'none', display: 'flex', flexDirection: 'column' }}
        onTouchStart={e => { touchStartX.current = e.touches[0].clientX; touchStartY.current = e.touches[0].clientY; }}
        onTouchEnd={e => {
          const dx = e.changedTouches[0].clientX - touchStartX.current;
          const dy = e.changedTouches[0].clientY - touchStartY.current;
          if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 50) go(dx < 0 ? 'fwd' : 'bwd');
        }}
      >
        {/* Top bar */}
        <div style={{ flexShrink: 0, display: 'flex', alignItems: 'center', padding: '14px 18px 12px', borderBottom: '1px solid rgba(180,130,60,.18)', background: '#fdf6e8' }}>
          <button onClick={() => onClose({ finished: page === total - 1, sessionWords })} style={{ background: 'transparent', border: 'none', color: '#8B6030', fontSize: 15, cursor: 'pointer', fontFamily: 'Georgia,serif', padding: '4px 8px 4px 0', marginRight: 8 }}>
            {userLang === 'ku' ? 'گەران ←' : userLang === 'ar' ? 'رجوع ←' : '← ' + (userLang === 'uk' ? 'Назад' : userLang === 'en' ? 'Back' : userLang === 'fa' ? 'بازگشت' : userLang === "fr" ? "Précédent" : 'Geri')}
          </button>
          <div style={{ flex: 1, textAlign: 'center' }}>
            <div style={{ fontSize: 13, fontWeight: 700, color: '#4a2e10', fontFamily: 'Georgia,serif', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {scenes[page]?.title}
            </div>
            <div style={{ fontSize: 11, color: '#b08050', fontFamily: 'Georgia,serif', marginTop: 1 }}>
              {userLang === 'ku' ? 'سەحنە' : userLang === 'en' ? 'Scene' : userLang === 'ar' ? 'المشهد' : userLang === 'uk' ? 'Сцена' : userLang === 'fa' ? 'صحنه' : userLang === "fr" ? "Scène" : 'Sahne'} {page + 1} / {total}
            </div>
          </div>
          <div style={{ width: 56 }} />
        </div>

        {/* Page flip area */}
        <div style={{ flex: 1, position: 'relative', perspective: '1200px', perspectiveOrigin: '50% 40%', overflow: 'hidden' }}>
          {/* Background page */}
          <div style={{ position: 'absolute', inset: 0, zIndex: 1, animation: flipping ? 'brBgReveal .55s ease both' : 'none' }}>
            {PageView({ scene: bgScene })}
          </div>

          {/* Shadow sweep */}
          {flipping && (
            <div style={{ position: 'absolute', inset: 0, zIndex: 4, pointerEvents: 'none', animation: 'brShadowSweep .55s ease-in-out both', background: flipDir === 'fwd' ? 'linear-gradient(to right,rgba(0,0,0,.18) 0%,rgba(0,0,0,.04) 55%,transparent 100%)' : 'linear-gradient(to left,rgba(0,0,0,.18) 0%,rgba(0,0,0,.04) 55%,transparent 100%)' }} />
          )}

          {/* Foreground page (animates away) */}
          <div style={{ position: 'absolute', inset: 0, zIndex: 2, transformOrigin: flipDir === 'bwd' ? 'right center' : 'left center', animation: flipping ? `brFlip${flipDir === 'fwd' ? 'Fwd' : 'Bwd'} ${FLIP_MS}ms cubic-bezier(.4,0,.2,1) both` : 'none', transformStyle: 'preserve-3d', backfaceVisibility: 'hidden', WebkitBackfaceVisibility: 'hidden', willChange: 'transform' }}>
            {PageView({ scene: fgScene })}
          </div>
        </div>

        {/* Bottom navigation */}
        <div style={{ flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 22px 20px', borderTop: '1px solid rgba(180,130,60,.18)', background: '#fdf6e8' }}>
          <button onClick={() => go('bwd')} disabled={page === 0 || flipping} style={{ width: 44, height: 44, borderRadius: '50%', border: '1.5px solid rgba(180,130,60,.28)', background: page === 0 ? 'transparent' : 'rgba(180,130,60,.08)', color: page === 0 ? 'rgba(180,130,60,.25)' : '#8B6030', fontSize: 22, cursor: page === 0 ? 'not-allowed' : 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'all .2s' }}>
            ‹
          </button>

          <div style={{ display: 'flex', gap: 5, alignItems: 'center', maxWidth: 200, overflow: 'hidden' }}>
            {total <= 14
              ? scenes.map((_, i) => (
                  <div key={i} onClick={() => { if (!flipping) setPage(i); }} style={{ height: 5, borderRadius: 3, width: i === page ? 18 : 5, background: i === page ? '#c09060' : i < page ? 'rgba(180,130,60,.4)' : 'rgba(180,130,60,.18)', transition: 'all .35s cubic-bezier(.4,0,.2,1)', flexShrink: 0, cursor: 'pointer' }} />
                ))
              : <span style={{ fontSize: 13, color: '#b08050', fontFamily: 'Georgia,serif' }}>{page + 1} / {total}</span>
            }
          </div>

          <button onClick={() => go('fwd')} disabled={page === total - 1 || flipping} style={{ width: 44, height: 44, borderRadius: '50%', border: '1.5px solid rgba(180,130,60,.28)', background: page === total - 1 ? 'transparent' : 'rgba(180,130,60,.08)', color: page === total - 1 ? 'rgba(180,130,60,.25)' : '#8B6030', fontSize: 22, cursor: page === total - 1 ? 'not-allowed' : 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'all .2s' }}>
            ›
          </button>
        </div>
      </div>

      {/* ── Dictionary tooltip ─────────────────────────────────────── */}
      {dictEntry && (() => {
        const ARTICLE_COLOR = { der:'#2a78d6', die:'#e34948', das:'#1baf7a' };
        const TYPE_LABEL = { noun:'Substantiv', verb:'Verb', adj:'Adjektiv', adv:'Adverb', phrase:'Phrasel' };
        const ac = dictEntry.article ? ARTICLE_COLOR[dictEntry.article] : '#5B5BD6';
        const vw = window.innerWidth;
        const tooltipW = 260;
        let left = dictEntry._x;
        if (left + tooltipW > vw - 8) left = vw - tooltipW - 8;
        if (left < 8) left = 8;
        const top = Math.min(dictEntry._y + 6, window.innerHeight - 220);
        return (
          <>
            <div onClick={() => setDictEntry(null)}
              style={{ position:'fixed', inset:0, zIndex:2001 }} />
            <div onClick={e => e.stopPropagation()}
              style={{
                position:'fixed', left, top, width:tooltipW, zIndex:2002,
                background:'#fff', borderRadius:14,
                padding:'12px 14px 14px',
                boxShadow:'0 8px 32px rgba(0,0,0,.18), 0 1px 4px rgba(0,0,0,.10)',
                border:'1px solid #ece9ff',
              }}>
              {/* Word row */}
              <div style={{ display:'flex', alignItems:'center', gap:6, marginBottom:8, flexWrap:'wrap' }}>
                {dictEntry.article && (
                  <span style={{ fontSize:11, fontWeight:700, color:ac, background:ac+'18', padding:'2px 8px', borderRadius:20 }}>
                    {dictEntry.article}
                  </span>
                )}
                <span style={{ fontSize:16, fontWeight:800, color:'#18181B', fontFamily:'Georgia,serif' }}>
                  {dictEntry.word}
                </span>
                <span style={{ fontSize:10, color:'#71717A', background:'#f4f4f5', padding:'2px 7px', borderRadius:20, fontWeight:600 }}>
                  {TYPE_LABEL[dictEntry.type] || dictEntry.type}
                </span>
              </div>
              {/* Translations */}
              <div style={{ display:'flex', flexDirection:'column', gap:4, marginBottom: dictEntry.ex ? 8 : 0 }}>
                {(() => {
                  const meta = DICT_LANG_META[userLang] || DICT_LANG_META.tr;
                  const val = userLang === 'uk' ? dictEntry.uk : (dictEntry[userLang] || dictEntry.tr || dictEntry.ku);
                  return val ? (
                    <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                      <span style={{ fontSize:10, fontWeight:700, color:'#fff', background:meta.bg, padding:'1px 5px', borderRadius:3, flexShrink:0 }}>{meta.badge}</span>
                      <span style={{ fontSize:13, color:'#18181B', fontWeight:600, direction: meta.rtl ? 'rtl' : 'ltr' }}>{val}</span>
                    </div>
                  ) : null;
                })()}
              </div>
              {/* Example */}
              {dictEntry.ex && (
                <div style={{ background:'#f8f7ff', borderLeft:'2px solid #5B5BD6', borderRadius:'0 6px 6px 0', padding:'6px 10px' }}>
                  <div style={{ fontSize:11, color:'#3D37A8', fontFamily:'Georgia,serif', fontStyle:'italic', marginBottom:2 }}>
                    {dictEntry.ex}
                  </div>
                  <div dir={(userLang === 'ku' || userLang === 'ar') ? 'rtl' : 'ltr'} style={{ fontSize:10, color:'#71717A' }}>{dictEntry['ex_' + userLang] || dictEntry.ex_tr}</div>
                </div>
              )}
              {/* Favori button */}
              {(() => {
                const de = (dictEntry.article ? dictEntry.article + ' ' : '') + dictEntry.word;
                const isFav = favWords.has(de.toLowerCase());
                return (
                  <div style={{ marginTop:10, display:'flex', justifyContent:'flex-end' }}>
                    <button onClick={() => toggleFavWord(de, dictEntry)}
                      style={{ display:'flex', alignItems:'center', gap:5, background: isFav ? '#fff0f0' : 'none', border:`1.5px solid ${isFav ? '#ef4444' : '#d1d5db'}`, borderRadius:20, padding:'5px 14px', cursor:'pointer', color: isFav ? '#ef4444' : '#6b7280', fontSize:12, fontWeight:700, transition:'all .15s' }}>
                      <Heart size={12} fill={isFav ? '#ef4444' : 'none'} color={isFav ? '#ef4444' : '#6b7280'} />
                      {isFav ? (userLang === 'tr' ? 'Favoride ✓' : userLang === 'en' ? 'Favorited ✓' : userLang === 'ar' ? 'في المفضلة ✓' : userLang === 'uk' ? 'В обраному ✓' : userLang === 'fa' ? 'در علاقه‌مندی‌ها ✓' : userLang === "fr" ? "Favoris ✓" : 'لە دڵخوازەکان ✓') : (userLang === 'tr' ? 'Favoriye ekle' : userLang === 'en' ? 'Add to favorites' : userLang === 'ar' ? 'أضف إلى المفضلة' : userLang === 'uk' ? 'Додати до обраного' : userLang === 'fa' ? 'افزودن به علاقه‌مندی‌ها' : userLang === "fr" ? "Ajouter aux favoris" : 'زیادکردن بۆ دڵخواز')}
                    </button>
                  </div>
                );
              })()}
            </div>
          </>
        );
      })()}
    </>
  );
}


function JourneyScreen({ lang="ku", onBack, onPractice }) {
  const JT = {
    ku:{ title:"گەشتی فێربوون", back:"گەڕانەوە", cont:"بەردەوامبە", level:"ئاست",
         done:"تەواو کرا ✓", active:"ئێستا", locked:"قفڵکراوە",
         xp:"XP", words:"وشە", lessons:"وانە", start:"دەستپێبکە",
         complete:"وانەی تەواوکرا!", next:"ئاستی داهاتوو ئەکرێتەوە 🎉",
         storyMode:"دۆخی چیرۆک", storyIntro:"تۆ بۆ ئەڵمانیا هاتیتەوە. لە سفیردا دەستت پێدەکات.", storyEnd:"تۆ ئامادەیت. ئەڵمانیادا ژیانی نوێ.",
         chapter:"بەشی چیرۆک", needKey:"Du brauchst eine Eintrittskarte! (پێویستە بە کارتی چوونەژوورەوە)" },
    tr:{ title:"Öğrenme Yolculuğu", back:"Geri", cont:"Devam Et", level:"Seviye",
         done:"Tamamlandı ✓", active:"Aktif", locked:"Kilitli",
         xp:"XP", words:"kelime", lessons:"ders", start:"Başla",
         complete:"Ders tamamlandı!", next:"Sonraki seviye açıldı 🎉",
         storyMode:"Hikâye Modu", storyIntro:"Almanya'ya geldin. Sıfırdan başlıyorsun.", storyEnd:"Hazırsın. Almanya'da yeni bir hayat.",
         chapter:"Hikâye Bölümü", needKey:"Du brauchst eine Eintrittskarte! (Giriş kartı lazım)" },
    en:{ title:"Your Journey", back:"Back", cont:"Continue", level:"Level",
         done:"Completed ✓", active:"Current", locked:"Locked",
         xp:"XP", words:"words", lessons:"lessons", start:"Start",
         complete:"Lesson done!", next:"Next level unlocked 🎉",
         storyMode:"Story Mode", storyIntro:"You arrived in Germany. Starting from zero.", storyEnd:"You're ready. A new life in Germany.",
         chapter:"Story Chapter", needKey:"Du brauchst eine Eintrittskarte! (You need an entry card)" },
    ar:{ title:"رحلتك", back:"رجوع", cont:"استمر", level:"المستوى",
         done:"مكتمل ✓", active:"الحالي", locked:"مقفل",
         xp:"XP", words:"كلمات", lessons:"دروس", start:"ابدأ",
         complete:"اكتملت الدرس!", next:"المستوى التالي مفتوح 🎉",
         storyMode:"وضع القصة", storyIntro:"وصلت إلى ألمانيا. تبدأ من الصفر.", storyEnd:"أنت جاهز. حياة جديدة في ألمانيا.",
         chapter:"فصل القصة", needKey:"Du brauchst eine Eintrittskarte! (تحتاج بطاقة دخول)" },
    uk:{ title:"Твоя подорож", back:"Назад", cont:"Продовжити", level:"Рівень",
         done:"Завершено ✓", active:"Поточний", locked:"Заблоковано",
         xp:"XP", words:"слів", lessons:"уроків", start:"Почати",
         complete:"Урок виконано!", next:"Наступний рівень відкрито 🎉",
         storyMode:"Режим історії", storyIntro:"Ти приїхав до Німеччини. Починаєш з нуля.", storyEnd:"Ти готовий. Нове життя в Німеччині.",
         chapter:"Розділ історії", needKey:"Du brauchst eine Eintrittskarte! (Потрібен вхідний квиток)" },
    fa:{ title:"سفر تو", back:"بازگشت", cont:"ادامه", level:"سطح",
         done:"تکمیل شد ✓", active:"فعلی", locked:"قفل",
         xp:"XP", words:"واژه", lessons:"درس", start:"شروع",
         complete:"درس تمام شد!", next:"سطح بعدی باز شد 🎉",
         storyMode:"حالت داستان", storyIntro:"به آلمان رسیدی. از صفر شروع می‌کنی.", storyEnd:"آماده‌ای. زندگی جدید در آلمان.",
         chapter:"فصل داستان", needKey:"Du brauchst eine Eintrittskarte! (به بلیت ورود نیاز داری)" },
  "es":{"title":"Su viaje","back":"Atrás","cont":"Continuar","level":"Nivel","done":"Terminado ✓","active":"Corriente","locked":"Bloqueado","xp":"XP","words":"palabras","lessons":"lecciones","start":"Comienzo","complete":"¡Lección hecha!","next":"Siguiente nivel desbloqueado","storyMode":"Modo de historia","storyIntro":"Llegaste a Alemania, empezando por cero.","storyEnd":"Estás listo, una nueva vida en Alemania.","chapter":"Capítulo de la historia","needKey":"Du brauchst eine Eintrittskarte! (Necesitas una tarjeta de entrada)"},"fr":{"title":"Votre voyage","back":"Précédent","cont":"Continuer","level":"Niveau","done":"Terminé ✓","active":"Actuellement","locked":"Verrouillé","xp":"xx","words":"mots","lessons":"leçons","start":"Démarrer","complete":"Leçon terminée!","next":"Niveau suivant déverrouillé -","storyMode":"Mode histoire","storyIntro":"Vous êtes arrivé en Allemagne, à partir de zéro.","storyEnd":"Tu es prête, une nouvelle vie en Allemagne.","chapter":"Chapitre historique","needKey":"Du brauchst eine Eintrittskarte! (Vous avez besoin d'une carte d'entrée)"}};
  const jt = k => (JT[lang]||JT.tr)[k]||(JT.tr[k]||k);
  const getNat = item => lang==='tr'?item.tr:lang==='ku'?item.ku:lang==='ar'?item.ar:lang==='uk'?(item.uk||item.en):lang==='fa'?(item.fa||item.en):(item[lang]||item.en);

  // ── User profile from registration ──────────────────────────────────────
  const _obData    = (() => { try { return JSON.parse(localStorage.getItem("ob_data")||"{}"); } catch { return {}; } })();
  const userName   = _obData.name   || "X";
      const getCefrLabel = cefr => (CEFR_META[cefr]?.label||{})[lang] || (CEFR_META[cefr]?.label?.tr||cefr);
  const getCefrArc = cefr => (CEFR_META[cefr]?.arc||{})[lang] || (CEFR_META[cefr]?.arc?.tr||'');

  const [currentLevel, setCurrentLevel] = useState(()=>
    parseInt(localStorage.getItem('fuxi_journey')||'1')
  );
  const [bookReader, setBookReader] = useState(null);
  const [justUnlocked, setJustUnlocked] = useState(null);
  const [quizGate, setQuizGate] = useState(null); // { levelId, scenes, sessionWords } — chapter finished, quiz must be passed to unlock
  const [sessionSummary, setSessionSummary] = useState(null); // { xpEarned, sessionWords, card } — shown after passing the quiz
  const [pendingKey, setPendingKey] = useState(() => {
    try { return JSON.parse(localStorage.getItem('fuxi_pending_key') || 'null'); } catch { return null; }
  }); // { fromLevelId, toLevelId } — a key has been earned and is waiting to be dragged onto its lock
  const [dragging, setDragging] = useState(false);
  const [dragPos, setDragPos] = useState(null); // {x,y} while dragging the key
  const [keyHome, setKeyHome] = useState(null); // {x,y} resting position of the key, near its target lock
  const [lockedMsg, setLockedMsg] = useState(null); // {x,y} — shows a brief "you need a key" toast above the tapped locked door
  const lockedMsgTimer = useRef(null);
  const targetNodeRef = useRef(null);
  const streakCount = (() => { try { return JSON.parse(localStorage.getItem('fuxi_streak')||'{}').count || 0; } catch { return 0; } })();

  const getState = id => {
    if (id < currentLevel) return 'done';
    if (id === currentLevel) return pendingKey?.toLevelId === id ? 'locked' : 'active';
    return 'locked';
  };

  const completeLevel = (id) => {
    if(id === currentLevel && currentLevel < 60){
      const next = currentLevel+1;
      localStorage.setItem('fuxi_journey', String(next));
      setCurrentLevel(next);
      const pk = { fromLevelId: id, toLevelId: next };
      localStorage.setItem('fuxi_pending_key', JSON.stringify(pk));
      setPendingKey(pk);
    }
  };

  const unlockWithKey = useCallback(() => {
    if (!pendingKey) return;
    const target = pendingKey.toLevelId;
    localStorage.removeItem('fuxi_pending_key');
    setPendingKey(null);
    setJustUnlocked(target);
    setTimeout(()=>setJustUnlocked(null), 2500);
  }, [pendingKey]);

  // Position the key at its resting spot next to the target lock whenever it (re)appears
  useEffect(() => {
    if (!pendingKey) return;
    const update = () => {
      if (targetNodeRef.current) {
        const rect = targetNodeRef.current.getBoundingClientRect();
        setKeyHome({ x: rect.left + rect.width / 2 + 56, y: rect.top + rect.height / 2 });
      }
    };
    const id = requestAnimationFrame(update);
    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    return () => {
      cancelAnimationFrame(id);
      window.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
    };
  }, [pendingKey]);

  useEffect(() => {
    if (!dragging) return;
    const onMove = (e) => {
      const p = e.touches ? e.touches[0] : e;
      setDragPos({ x: p.clientX, y: p.clientY });
    };
    const onUp = (e) => {
      setDragging(false);
      const p = e.changedTouches ? e.changedTouches[0] : e;
      if (targetNodeRef.current) {
        const rect = targetNodeRef.current.getBoundingClientRect();
        const pad = 14; // a little forgiveness around the exact lock bounds
        if (p.clientX >= rect.left - pad && p.clientX <= rect.right + pad &&
            p.clientY >= rect.top - pad && p.clientY <= rect.bottom + pad) {
          unlockWithKey();
        }
      }
      setDragPos(null);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };
  }, [dragging, unlockWithKey]);

  // Node layout constants
  const CONTAINER_W = 360;
  const CX = CONTAINER_W / 2;         // 180
  const OFFSET = 58;
  const NODE_W = 62;
  const NODE_H = 82; // matches the door artwork's 240:320 aspect ratio
  const GAP = 36;
  const getNodeX = (idx) => idx % 2 === 0 ? CX + OFFSET : CX - OFFSET; // 238 or 122

  return (
    <div style={{ maxWidth:400, margin:'0 auto', position:'relative', paddingBottom:120 }}>

      {/* ── Back button ── */}
      <div style={{ padding:'12px 16px 0' }}>
        <button onClick={onBack} style={{ background:'none',border:'none',cursor:'pointer',color:'#888',fontSize:14,padding:'2px 0' }}>← {jt('back')}</button>
      </div>


      {/* ── Map ── */}
      <div style={{ padding:'20px 0 20px', overflowX:'hidden' }}>
        {JOURNEY_LEVELS.map((lv, idx) => {
          const state = getState(lv.id);
          const nx = getNodeX(idx);
          const px = idx > 0 ? getNodeX(idx-1) : nx;
          const isNewCefr = idx===0 || JOURNEY_LEVELS[idx-1].cefr !== lv.cefr;
          const meta = CEFR_META[lv.cefr];

          return (
            <div key={lv.id}>

              {/* CEFR Section badge + arc title */}
              {isNewCefr && (
                <div style={{ textAlign:'center', margin: idx===0 ? '4px 0 16px' : '24px 0 16px' }}>
                  <img
                    src={lv.cefr==='C2' ? '/C2.png' : `/${lv.cefr}Journey.png`}
                    alt={lv.cefr}
                    style={{ display:'block', width:'calc(100% - 80px)', maxWidth:280, margin:'0 auto 12px', borderRadius:16, boxShadow:'0 4px 16px rgba(0,0,0,.13)', objectFit:'cover' }}
                  />
                  {idx > 0 && <div style={{ height:2, background:'#ebebf0', margin:'0 10% 12px' }}/>}
                  <div style={{ display:'inline-flex', flexDirection:'column', alignItems:'center', gap:5 }}>
                    <span style={{ background:meta.grad, color:'#fff', padding:'5px 18px', borderRadius:20, fontSize:12, fontWeight:800, boxShadow:`0 3px 12px ${meta.border}44` }}>
                      {lv.cefr} · {getCefrLabel(lv.cefr)}
                    </span>
                    <span style={{ fontSize:12, fontWeight:700, color:'#555', letterSpacing:'.01em' }}>
                      {getCefrArc(lv.cefr)}
                    </span>
                  </div>
                </div>
              )}

              {/* Connector SVG (from previous node) */}
              {idx > 0 && (
                <svg width={CONTAINER_W} height={GAP} style={{ display:'block', marginLeft:`calc(50% - ${CONTAINER_W/2}px)` }}
                  viewBox={`0 0 ${CONTAINER_W} ${GAP}`}>
                  <path
                    d={`M ${px} 0 C ${px} ${GAP/2}, ${nx} ${GAP/2}, ${nx} ${GAP}`}
                    stroke={ state==='locked' ? '#e0e0e0' : getState(lv.id-1)==='done' ? '#43e97b' : '#667eea' }
                    strokeWidth={state==='locked'?"2":"3"} fill="none" strokeLinecap="round"
                    strokeDasharray={state==='locked'?"5 4":"none"}
                    opacity={state==='locked'?.5:1}
                  />
                  {/* Animated flowing dot on active path */}
                  {state==='active' && (
                    <circle r="4" fill="#fff" stroke="#667eea" strokeWidth="2">
                      <animateMotion dur="1.5s" repeatCount="indefinite"
                        path={`M ${px} 0 C ${px} ${GAP/2}, ${nx} ${GAP/2}, ${nx} ${GAP}`}/>
                    </circle>
                  )}
                </svg>
              )}

              {/* Level node row */}
              <div style={{ display:'flex', justifyContent:'center', position:'relative' }}>
                <div style={{ transform:`translateX(${nx - CX}px)`, position:'relative' }}>
                  {/* Unlock burst */}
                  {justUnlocked===lv.id && (
                    <div style={{ position:'absolute', inset:-14, borderRadius:'50%',
                      background:'radial-gradient(circle,rgba(102,126,234,.25),transparent 70%)',
                      animation:'journeyUnlock .6s ease-out' }}/>
                  )}
                  {/* The door */}
                  <button
                    ref={pendingKey?.toLevelId === lv.id ? targetNodeRef : null}
                    className={`journey-node${state==='active'?' journey-active':''}`}
                    onClick={(e)=>{
                      if(state==='locked') {
                        const r = e.currentTarget.getBoundingClientRect();
                        setLockedMsg({ x: r.left + r.width / 2, y: r.top });
                        clearTimeout(lockedMsgTimer.current);
                        lockedMsgTimer.current = setTimeout(() => setLockedMsg(null), 2000);
                        return;
                      }
                      if(JOURNEY_STORIES[lv.id]) setBookReader({ scenes: JOURNEY_STORIES[lv.id], levelId: lv.id });
                      else completeLevel(lv.id);
                    }}
                    style={{
                      width:NODE_W, height:NODE_H, borderRadius:14, border:'none',
                      display:'flex', alignItems:'center', justifyContent:'center',
                      cursor:'pointer',
                      transition:'transform .18s',
                      overflow:'hidden', position:'relative',
                      background: state==='locked' ? '#fdf6e8' : 'transparent',
                      boxShadow:'none',
                    }}>
                    {state==='locked' ? (
                      <img src="/door-closed.png" alt="locked" style={{
                        position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover',
                      }} />
                    ) : (
                      <img src="/door-open.png" alt="unlocked" style={{
                        position:'absolute', inset:0, width:'100%', height:'100%', objectFit:'cover',
                        filter:'drop-shadow(0 4px 6px rgba(0,0,0,.25))',
                        animation: justUnlocked===lv.id ? 'doorOpenIn .5s cubic-bezier(.22,1,.36,1) both' : 'none',
                      }} />
                    )}
                    {state==='done' && (
                      <div style={{ position:'absolute', top:4, right:4, width:18, height:18, borderRadius:'50%',
                        background:'#30A46C', color:'#fff', display:'flex', alignItems:'center', justifyContent:'center',
                        fontSize:11, fontWeight:900, boxShadow:'0 2px 6px rgba(0,0,0,.35)' }}>✓</div>
                    )}
                  </button>

                </div>
              </div>

              {/* Label below node */}
              <div style={{ textAlign:'center', transform:`translateX(${nx - CX}px)`, marginTop:5, marginBottom:6 }}>
                <div style={{ fontSize:11, fontWeight:700,
                  color:state==='locked'?'#ccc':state==='done'?'#30A46C':'#1a1a2e',
                  lineHeight:1.25 }}>
                  {lv.de}
                </div>
                <div style={{ fontSize:9.5, color:state==='locked'?'#ccc':'#999', marginTop:1 }}>
                  {getNat(lv)}
                </div>
                <div style={{ fontSize:9, color:'#bbb', marginTop:1 }}>
                  {lv.l} {jt('lessons')} · {lv.w} {jt('words')}
                </div>
              </div>

            </div>
          );
        })}

        {/* Finish line */}
        <div style={{ textAlign:'center', marginTop:24, padding:'20px 24px',
          background:'linear-gradient(135deg,#f7971e22,#ffd20022)', border:'2px dashed #f7971e44', borderRadius:20 }}>
          <div style={{ fontSize:36 }}>🏆</div>
          <div style={{ fontWeight:800, fontSize:16, color:'#f7971e', marginTop:6 }}>Mastery Complete</div>
          <div style={{ fontSize:12, color:'#aaa', marginTop:4 }}>C2 · Level 60</div>
        </div>
      </div>

      {/* ── Draggable key: earned from the previous chapter, drop it on its lock to unlock ── */}
      {pendingKey && keyHome && (
        <div
          onPointerDown={(e) => { e.preventDefault(); setDragging(true); setDragPos({ x: e.clientX, y: e.clientY }); }}
          style={{
            position:'fixed', zIndex:60, touchAction:'none',
            left: (dragging && dragPos ? dragPos.x : keyHome.x) - 34,
            top: (dragging && dragPos ? dragPos.y : keyHome.y) - 21,
            width:68, height:42, cursor:'grab', userSelect:'none',
            transition: 'none',
            animation: dragging ? 'none' : 'robotFloat 2.4s ease-in-out infinite',
            filter: dragging ? 'drop-shadow(0 14px 22px rgba(0,0,0,.4))' : 'drop-shadow(0 6px 14px rgba(0,0,0,.3))',
          }}>
          <img src="/card.png" alt="key card" draggable={false} style={{ width:'100%', height:'100%', objectFit:'contain', pointerEvents:'none' }} />
        </div>
      )}

      {/* ── "You need a key" toast, anchored above the tapped locked door ── */}
      {lockedMsg && (
        <div style={{
          position:'fixed',
          left: Math.min(Math.max(lockedMsg.x, 110), window.innerWidth - 110),
          top: lockedMsg.y - 12,
          zIndex:70,
          background:'rgba(20,20,30,.94)', color:'#fff', padding:'10px 16px', borderRadius:14,
          fontSize:13, fontWeight:700, textAlign:'center', maxWidth:220, lineHeight:1.4,
          boxShadow:'0 8px 24px rgba(0,0,0,.35)',
          animation:'toastPopIn .25s ease-out both',
        }}>
          🔒 {jt('needKey')}
          <div style={{
            position:'absolute', bottom:-6, left:'50%', transform:'translateX(-50%)',
            width:0, height:0, borderLeft:'7px solid transparent', borderRight:'7px solid transparent',
            borderTop:'7px solid rgba(20,20,30,.94)',
          }}/>
        </div>
      )}

      {/* ── Floating continue button ── */}
      {currentLevel <= 60 && getState(currentLevel) !== 'locked' && (
        <div style={{ position:'fixed', bottom:76, left:'50%', transform:'translateX(-50%)', zIndex:50, pointerEvents:'none' }}>
          <button
            onClick={()=>{
              const lv = JOURNEY_LEVELS[currentLevel-1];
              if(lv && JOURNEY_STORIES[lv.id]) setBookReader({ scenes: JOURNEY_STORIES[lv.id], levelId: lv.id });
              else if(lv) completeLevel(lv.id);
            }}
            style={{ pointerEvents:'all', padding:'13px 32px', borderRadius:30, border:'none',
              background:'linear-gradient(135deg,#667eea,#764ba2)',
              color:'#fff', fontWeight:800, fontSize:15, cursor:'pointer',
              boxShadow:'0 8px 28px rgba(102,126,234,.55)', whiteSpace:'nowrap' }}>
            {jt('cont')} — {jt('level')} {currentLevel} {JOURNEY_LEVELS[currentLevel-1]?.e}
          </button>
        </div>
      )}

      {bookReader && (
        <BookReaderModal
          scenes={bookReader.scenes}
          onClose={(result) => {
            const finishedId = bookReader.levelId;
            const scenes = bookReader.scenes;
            setBookReader(null);
            if (result?.finished) {
              setQuizGate({ levelId: finishedId, scenes, sessionWords: result.sessionWords || [] });
            }
          }}
          userName={userName}
          userLang={lang}
        />
      )}

      {quizGate && (
        <ChapterQuiz
          scenes={quizGate.scenes}
          lang={lang}
          onCancel={() => setQuizGate(null)}
          onPass={() => {
            completeLevel(quizGate.levelId);
            addXp(100);
            awardCard(quizGate.levelId);
            const earnedCard = JOURNEY_LEVELS.find(l => l.id === quizGate.levelId);
            setSessionSummary({ xpEarned: 100, sessionWords: quizGate.sessionWords, card: earnedCard });
            setQuizGate(null);
          }}
        />
      )}

      {sessionSummary && (
        <SessionComplete
          lang={lang}
          xpEarned={sessionSummary.xpEarned}
          sessionWords={sessionSummary.sessionWords}
          card={sessionSummary.card}
          streakCount={streakCount}
          onPractice={() => { setSessionSummary(null); onPractice?.(); }}
          onContinue={() => setSessionSummary(null)}
        />
      )}
    </div>
  );
}

